(window.GAMES = window.GAMES || {})[2012] = [{"t":"007 Legends","p":["PlayStation 3","Xbox 360","Windows","Wii U"],"g":"Shooter","r":"October 16","l":"https://en.wikipedia.org/wiki/007_Legends","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co203u.jpg","s":"007 Legends features an original, overarching storyline tying together six classic Bond movies for an original James Bond experience, and equips players with state-of-the-art spy gadgets, an arsenal of weapons and more.\n\nIn addition to 007 Legends' main story, the game features the return of fan-favorite single-player Mi6 Ops Missions, which debuted in GoldenEye 007: Reloaded and challenges players to complete extra missions ranging from all-out action to stealth and gadget-based gameplay and compete for the highest online leader board scores. Also for the first time ever, players will be able to participate as one of Bond's cohorts or villainous foes, reliving the missions through their eyes, as well as 007's. Meanwhile the robust James Bond multiplayer experience includes local four-player split-screen game modes and online competitive gameplay with new maps, weapons and characters derived from Bond's 50 year legacy. With more gadgets, deeper stealth and spy investigation gameplay, gamers will have every opportunity to truly feel like the world's favorite spy."},{"t":"1000 Amps","p":["Windows"],"r":"February 22","l":"https://en.wikipedia.org/wiki/1000_Amps"},{"t":"10000000","p":["iOS"],"d":"EightyEightGames","u":"EightyEightGames","g":"Puzzle, role-playing","r":"August 29, 2012","l":"https://en.wikipedia.org/wiki/10000000_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1u7x.jpg","s":"10000000 is an award winning hybrid RPG/Action/Puzzle game. Matching tiles controls your character enabling you to explore, fight and loot. When you are not facing monsters you will be back in your prison, constructing buildings and getting stronger for your next run."},{"t":"2 Fast 4 Gnomz","p":["Nintendo 3DS","Wii"],"d":"QubicGames","u":"QubicGames, Flyhigh Works","g":"Platform","r":"February 23, 2012","l":"https://en.wikipedia.org/wiki/2_Fast_4_Gnomz","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7n08.jpg","s":"\"In this colorful arcade platform runner you will swoosh, spring, and swoop through over a hundred challenging courses. Think fast, tap faster – avoid devious traps, find the best route, and collect all the magical socks on your way to the finish line. Geki Yaba Runner tells a tale of the speedster gnomes on a quest to collect magic socks, save all the princesses, slay all the dragons, and… Well, that might just be a gnome fairytale, but the socks and the speed part is true, we swear! Answer the challenge of the magical kingdom, conquer the hardest racing tracks, laugh at danger (ha, ha!), and become the supreme gnomish speedster in Geki Yaba Runner, free on App Store and Google Play!\""},{"t":"2nd Super Robot Wars OG","p":["PlayStation 3"],"d":"Tose, B.B. Studio","u":"Namco Bandai Games","g":"Tactical role-playing","r":"November 29, 2012","l":"https://en.wikipedia.org/wiki/2nd_Super_Robot_Wars_OG","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2uam.jpg","s":"Japan-only game in the Super Robot Wars series"},{"t":"3D Classics: Kid Icarus","p":["Nintendo 3DS"],"r":"April 19","l":"https://en.wikipedia.org/wiki/Kid_Icarus"},{"t":"99 Levels to Hell","p":["Linux","Windows","macOS"],"d":"bom667","u":"Zaxis","g":"Roguelike, platform, shooter","l":"https://en.wikipedia.org/wiki/99_Levels_to_Hell","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co27ts.jpg","s":"99 Levels to Hell is a platform shooter with lots of guns, upgrades, magic, traps and monsters to kill. 99 Levels to Hell is a rogue-like-like, which means surviving is key and every time you play you get a new set of levels to play. When you complete 10 levels, the 10th being a boss-fight you unlock a door to the next dungeon.\n\nHidden in the darkness of the dungeons are shops, casinos and elevators. And if you search the dungeons carefully, you might find secret rooms that unlock more of the story, and free new adventurers that you can play as in your next game. Let this great combination of a platformer and a roguelike RPG suck you into its multi-leveled randomly-generated dungeon. You won't be back for hours!"},{"t":"99 Spirits","p":["Windows"],"d":"Toraiki","u":"Toraiki, Fruitbat Factory","g":"Puzzle, role-playing","r":"July 2012","l":"https://en.wikipedia.org/wiki/99_Spirits","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1zlt.jpg","s":"\"99 Spirits is an RPG/Puzzle game that revolves around the popular Japanese folklore of Tsukumogami, everyday objects coming alive on their 100th birthday.\n\nThe Game Features an original battle system where players will have to puzzle out the true identity of the enemy before defeating them. We would love for you to experience this unique system not found in any other game.\n\n99 Spirits is the first RPG produced by the Japanese indie game circle TORaIKI\"\n\nFruitbat Factory also published the original Japanese version on Steam and it is included in the purchase of the translated game."},{"t":"A Game of Dwarves","p":["Windows"],"r":"October 23"},{"t":"A Slower Speed of Light","p":["Windows","macOS","Linux"],"d":"MIT Game Lab","g":"First-person","l":"https://en.wikipedia.org/wiki/A_Slower_Speed_of_Light","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/rakhjxznkx94nnbgbsug.jpg","s":"A Slower Speed of Light is a first-person game prototype in which players navigate a 3D space while picking up orbs that reduce the speed of light in increments. Custom-built, open-source relativistic graphics code allows the speed of light in the game to approach the player’s own maximum walking speed. Visual effects of special relativity gradually become apparent to the player, increasing the challenge of gameplay. These effects, rendered in realtime to vertex accuracy, include the Doppler effect (red- and blue-shifting of visible light, and the shifting of infrared and ultraviolet light into the visible spectrum); the searchlight effect (increased brightness in the direction of travel); time dilation (differences in the perceived passage of time from the player and the outside world); Lorentz transformation (warping of space at near-light speeds); and the runtime effect (the ability to see objects as they were in the past, due to the travel time of light). Players can choose to share their mastery and experience of the game through Twitter. A Slower Speed of Light combines accessible gameplay and a fantasy setting with theoretical and computational physics research to deliver an engaging and pedagogically rich experience."},{"t":"A Story About My Uncle","p":[],"d":"Gone North Games","u":"Coffee Stain Studios","g":"Adventure","l":"https://en.wikipedia.org/wiki/A_Story_About_My_Uncle"},{"t":"A Valley Without Wind","p":["Windows","macOS","Linux"],"d":"Arcen Games","u":"Arcen Games","g":"Action-adventure","r":"April 24, 2012","l":"https://en.wikipedia.org/wiki/A_Valley_Without_Wind","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1n0c.jpg","s":"A Valley Without Wind is a indie and action-adventure video game developed by Arcen Games. The game was released on April 24, 2012 for the operating systems Microsoft Windows and Mac OS X on Steam. Players play as a random survivor in an unforgiving world that is shaped by the choices the player makes. The setting of the game is a post-ice-age world in the distant future."},{"t":"A Virus Named TOM","p":["Windows","macOS","Linux","PlayStation Vita"],"d":"Misfits Attic","u":"Misfits Attic","g":"Puzzle","r":"August 1, 2012","l":"https://en.wikipedia.org/wiki/A_Virus_Named_TOM","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2xmj.jpg","s":"An Action-puzzler. The puzzle comes from rearrange circuits to spread the virus. The Action comes from dodging anti-virus drones while doing it. It's one of the few puzzle games out there where you can play co-operatively (with up to 3 friends). But if you tire of working together, there is a battle mode where you can take on your friends to see who is the supreme virus."},{"t":"Abobo's Big Adventure","p":["Browser"],"d":"Team Bobo","u":"Team Bobo","g":"Beat 'em up","r":"January 11, 2012","l":"https://en.wikipedia.org/wiki/Abobo's_Big_Adventure","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2d2b.jpg","s":"Abobo's Big Adventure is a freeware parody Flash game. Inspired by various video games released for the Nintendo Entertainment System, the game features Abobo, a boss character from the Double Dragon franchise, traveling through the worlds of several different games to save his son. Developed by I-Mockery founder Roger Barr, Abobo's Big Adventure was released in January 2012 to positive critical reception."},{"t":"Abyss","p":["Nintendo DS"],"r":"August 23"},{"t":"Ace of Spades","p":["Windows"],"d":"Jagex","u":"Jagex","g":"First-person shooter, sandbox","r":"December 12, 2012","l":"https://en.wikipedia.org/wiki/Ace_of_Spades_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4kv7.jpg","s":"Say hello to the creative shooter. Ace of Spades: Battle Builder is the first-person shooter that lets you create your battleground, destroy it, then create it again. Up to 32 players choose from seven unique classes and jump into team-based, multiplayer mayhem across an endlessly evolving battlefield, to construct, destruct and take out the opposition."},{"t":"Adidas miCoach","p":[],"l":"https://en.wikipedia.org/wiki/Adidas_miCoach"},{"t":"Adventure Time: Hey Ice King! Why'd You Steal Our Garbage?!","p":["Nintendo 3DS","Nintendo DS"],"r":"November 20"},{"t":"Aero Porter","p":["Nintendo 3DS"],"r":"November 29","l":"https://en.wikipedia.org/wiki/Guild_(video_game_series)"},{"t":"AFL Live: Game of the Year Edition","p":["Windows","PlayStation 3","Xbox 360"],"r":"July 12","l":"https://en.wikipedia.org/wiki/AFL_Live#Game_of_the_Year_Edition"},{"t":"Agent Dash","p":["iOS","Android"],"d":"Full Fat","u":"Full Fat","g":"Platform","r":"August 2, 2012","l":"https://en.wikipedia.org/wiki/Agent_Dash","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/vpciiqocexuczp5jdn8f.jpg","s":"The popular running game for phones and tablets from Full Fat Productions."},{"t":"Aikatsu!","p":["Arcade"],"g":"Music, Arcade","l":"https://en.wikipedia.org/wiki/Aikatsu!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8you.jpg","s":"Aikatsu! is an arcade collectible card game based on the anime. The game revolves around using collectible cards featuring various clothes to help aspiring idols pass auditions."},{"t":"Air Conflicts: Pacific Carriers","p":["Windows","Xbox 360","PlayStation 3","PlayStation 4"],"d":"Games Farm","u":"bitComposer Games, Maximum Games","g":"Combat flight simulation","r":"December 7, 2012","l":"https://en.wikipedia.org/wiki/Air_Conflicts:_Pacific_Carriers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5dx1.jpg","s":"True heroes know no bounds! Experience top combat action in this brand new arcade flight sim and become immersed in the exploits of famous aircraft carriers. Choose the side you want to play on: the US Navy or the Imperial Japanese Navy. Climb into the cockpit and re-live the most famous battles of the War in the Pacific."},{"t":"Air Mail","p":["iOS"],"d":"Chillingo","r":"May 24, 2012","l":"https://en.wikipedia.org/wiki/Air_Mail_(video_game)"},{"t":"Akai Katana","p":["Xbox 360"],"r":"May 15","l":"https://en.wikipedia.org/wiki/Akai_Katana"},{"t":"Alan Wake","p":["Windows"],"r":"February 16","l":"https://en.wikipedia.org/wiki/Alan_Wake"},{"t":"Alan Wake's American Nightmare","p":["Xbox 360","Windows"],"g":"Shooter, Adventure","r":"February 22","l":"https://en.wikipedia.org/wiki/Alan_Wake%27s_American_Nightmare","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2eh1.jpg","s":"Alan Wake's American Nightmare is a standalone expansion to the psychological horror action-adventure game Alan Wake, developed by Remedy Entertainment. The story shifts to an alternate reality where Alan Wake finds himself in a small Arizona town. Here, he faces off against his evil doppelgänger, Mr. Scratch, a murderous entity intent on destroying everything Alan holds dear.\n\nThe gameplay involves exploring the town, battling new and familiar supernatural enemies, and uncovering pieces of the narrative through manuscripts and other clues. The expansion introduces new weapons and combat mechanics while maintaining the series' focus on the use of light to combat darkness. The narrative explores themes of duality and reality, offering a more action-oriented experience compared to the original game."},{"t":"Amazing Alex","p":["Android","iOS"],"r":"July 12","l":"https://en.wikipedia.org/wiki/Amazing_Alex"},{"t":"American Mensa Academy","p":["Nintendo 3DS"],"r":"November 27"},{"t":"Amnesia Fortnight 2012","p":["Windows"],"d":"Double Fine Productions","u":"Double Fine Productions","g":"Various","r":"November 19, 2012","l":"https://en.wikipedia.org/wiki/Amnesia_Fortnight_2012"},{"t":"Amy","p":["Xbox 360","PlayStation Network"],"r":"January 11","l":"https://en.wikipedia.org/wiki/Amy_(video_game)"},{"t":"Analogue: A Hate Story","p":["Windows","macOS","Linux"],"d":"Love Conquers All Games","g":"Visual novel","r":"February 1, 2012","l":"https://en.wikipedia.org/wiki/Analogue:_A_Hate_Story","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7ltn.jpg","s":"A dark visual mystery novel featuring transhumanism, traditional marriage, loneliness, and cosplay. Two pursuable characters. Five endings. Welcome to the future."},{"t":"Angry Birds Friends","p":["Android","iOS","Facebook","Browser","Windows"],"d":"Rovio Entertainment","u":"Rovio Entertainment","g":"Puzzle","r":"February 13, 2012","l":"https://en.wikipedia.org/wiki/Angry_Birds_Friends","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co49g7.jpg","s":"See how your Angry Birds skills stack up against your friends and the world in 3 new tournaments every week, or compete with another player one-on-one in the Star Cup! Come out on top to climb the leaderboards and earn awesome rewards."},{"t":"Angry Birds Space","p":["Windows","macOS","iOS"],"g":"Puzzle, Strategy, Arcade","r":"March 22","l":"https://en.wikipedia.org/wiki/Angry_Birds_Space","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4cro.jpg","s":"Play over 300 interstellar levels across 10 planets! Whether it’s the icy orbs of Cold Cuts, the volcanic explosiveness of Red Planet, Utopia – a planet made entirely of junk food, or the new Brass Hogs episode ruled by evil Hektor Porko, each episode offers intergalactic fun at every turn! And the low-gravity environment of space results in spectacular gameplay ranging from slow-motion puzzles to lightspeed destruction. With brand new birds, special abilities, and a whole galaxy to explore, the sky is no longer the limit!"},{"t":"Angry Birds Star Wars","p":["Windows","macOS","iOS","Android"],"g":"Puzzle, Strategy, Arcade","r":"November 8","l":"https://en.wikipedia.org/wiki/Angry_Birds_Star_Wars","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2hr4.jpg","s":"Join an epic adventure with the Angry Birds in the legendary Star Wars universe, re-mastered for gaming systems! Use the Force, wield your Lightsaber, and blast away Pigtroopers on an intergalactic journey from the deserts of Tatooine to the depths of the Pig Star! Can you become a Jedi Master and restore freedom to the galaxy?"},{"t":"Angry Birds Trilogy","p":["Xbox 360","PlayStation 3","Nintendo 3DS"],"r":"September 25","l":"https://en.wikipedia.org/wiki/Angry_Birds_Trilogy"},{"t":"Angry Brides","p":["Facebook"],"d":"Shaadi.com","g":"Simulation","l":"https://en.wikipedia.org/wiki/Angry_Brides","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co55j4.jpg","s":"Angry Brides is an online flash-based browser game on Facebook. It was launched by the matchmaking site Shaadi.com to help raise awareness of dowry harassment in India."},{"t":"Anna","p":["Windows"],"r":"July 11","l":"https://en.wikipedia.org/wiki/Anna_(video_game)"},{"t":"Anohana","p":["PlayStation Portable"],"g":"Adventure, Visual Novel","l":"https://en.wikipedia.org/wiki/Anohana","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4bzo.jpg","s":"Ano Hi Mita Hana no Namae o Bokutachi wa Mada Shiranai is a visual novel developed by guyzware, based on the anime of the same name, it contains a branching story and multiple endings made just for the game. It also contains a communication mini-game where you can talk to a 3D model of Menma every day."},{"t":"Anomaly: Warzone Earth","p":["Xbox 360","PlayStation Network"],"r":"April 6"},{"t":"Apocalypse Max: Better Dead Than Undead","p":["iOS","Android"],"d":"Wandake","g":"platform/shooting game","r":"September 14, 2012","l":"https://en.wikipedia.org/wiki/Apocalypse_Max:_Better_Dead_Than_Undead"},{"t":"ARC Squadron","p":["iOS","Android"],"d":"Psyonix","u":"Psyonix","g":"Space combat","r":"November 1, 2012","l":"https://en.wikipedia.org/wiki/ARC_Squadron","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaa4r.jpg"},{"t":"Arcane Legends","p":["iOS","Android","Browser","Windows"],"d":"Spacetime Studios","u":"Spacetime Studios","g":"hack and slash","l":"https://en.wikipedia.org/wiki/Arcane_Legends"},{"t":"Armored Core V","p":["PlayStation 3","Xbox 360"],"r":"March 20","l":"https://en.wikipedia.org/wiki/Armored_Core_V"},{"t":"Army Corps of Hell","p":["PlayStation Vita"],"r":"February 22","l":"https://en.wikipedia.org/wiki/Army_Corps_of_Hell"},{"t":"Art Academy: Lessons for Everyone!","p":["Nintendo 3DS"],"r":"October 1"},{"t":"Art of Balance Touch!","p":["Nintendo 3DS"],"r":"June 7","l":"https://en.wikipedia.org/wiki/Shin%27en_Multimedia"},{"t":"Asphalt 7: Heat","p":["iOS","Android"],"r":"June 21"},{"t":"Asphalt: Injection","p":["PlayStation Vita"],"r":"February 15"},{"t":"Assassin's Creed III","p":["PlayStation 3","Xbox 360","Wii U","Windows"],"g":"Adventure","r":"October 30","l":"https://en.wikipedia.org/wiki/Assassin%27s_Creed_III","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1xii.jpg","s":"Assassin's Creed III is an open-world action-adventure game set primarily in 18th-century Colonial America during the American Revolution. Players control two characters across the story: Haytham Kenway, a British Templar operating during the French and Indian War, and his half-Mohawk son Ratonhnhaké:ton (also known as Connor), who becomes an Assassin. Gameplay takes place across Boston, New York City, and a large wilderness frontier, with free-running, stealth, and combat using weapons including tomahawks, muskets, bows, and the series' signature Hidden Blades. The game introduces naval combat through Connor's captaining of a warship, as well as hunting, a homestead economy system, and seasonal weather that affects gameplay. A modern-day framing narrative follows Desmond Miles using the Animus to relive his ancestors' memories."},{"t":"Assassin's Creed III: Liberation","p":["PlayStation Vita"],"g":"Strategy, Hack and slash/Beat 'em up, Adventure","r":"October 30","l":"https://www.igdb.com/games/assassin-s-creed-iii-liberation","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1xim.jpg","s":"Assassin's Creed III: Liberation is a PlayStation Vita game released on October 30, 2012. Set in 1765 Louisiana, featuring Aveline de Grandpré, a mixed-race female Assassin. The game takes place during the lead-up to the American Revolution, with Aveline navigating the complex social and political landscape of New Orleans. She uses three distinct personas (Assassin, Lady, and Slave) to pursue her missions, fighting against Spanish forces and colonial powers."},{"t":"Astronot","p":["Windows","macOS","iOS"],"d":"Wade McGillis","u":"Wade McGillis","g":"Platform-adventure, Metroidvania","r":"June 12, 2012","l":"https://en.wikipedia.org/wiki/Astronot","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/bjuru6rtfmyz0b3dcf2s.jpg","s":"Fun Metroidvania style game made by Wade Mcgillis. Collect Squares and powerups!"},{"t":"Asura's Wrath","p":["PlayStation 3","Xbox 360"],"g":"Hack and slash/Beat 'em up","r":"February 21","l":"https://en.wikipedia.org/wiki/Asura%27s_Wrath","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4961.jpg","s":"The game follows the title character, the demigod Asura as he seeks revenge on the pantheon of other demigods who betrayed him. The story is presented in the style and format of an episodic series of cinematic shorts, including opening and closing credits, with the gameplay being integrated into the cinematic where players switch between third-person combat and interactive sequences with player input in the form of quick-time event button prompts. Because of its unique style, the game has been described in the media as an \"interactive anime\". According to the game's producer Kazuhiro Tsuchiya, Asura's Wrath takes elements from Hinduism and Buddhism and blends them with science fiction, with the main character based on the ever combative and superiority-seeking beings of the same name that are part of the Hindu and Buddhist cosmology."},{"t":"Atelier Meruru: The Apprentice of Arland","p":["PlayStation 3"],"r":"May 29"},{"t":"Auditorium","p":["Windows","macOS"],"r":"February 28","l":"https://en.wikipedia.org/wiki/Auditorium_(video_game)"},{"t":"Autumn Dynasty","p":["iOS","Android","BlackBerry OS"],"d":"Touch Dimensions","u":"BulkyPix","g":"Real-time strategy","r":"May 24, 2012","l":"https://en.wikipedia.org/wiki/Autumn_Dynasty","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8qvz.jpg","s":"Autumn Dynasty is a revolutionary new real time strategy game designed from the ground up for iPhone, iPad, iPod touch. With a unique drawing interface, players can paint their battle plans directly onto the map, using brush strokes to direct their armies, invoke powerful stratagems and conquer their foes! Defeat your friends and opponents from all around the world in an amazing online multiplayer mode."},{"t":"Avernum: Escape from the Pit","p":["Windows"],"r":"April 11"},{"t":"Awesomenauts","p":["macOS"],"g":"Platform, Strategy, Indie, MOBA","r":"December 7","l":"https://en.wikipedia.org/wiki/Awesomenauts","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2sld.jpg","s":"Two teams battle each other to take down the opposing sides turrets and base. There's multiple stages and some with hidden traps in the environment. Each team defends multiple lanes, and has to plan and coordinate properly to take down the other team."},{"t":"Azkend 2: The World Beneath","p":["iOS","Android","Windows","PlayStation 4","PlayStation Vita","Xbox One"],"d":"10tons Ltd","g":"Puzzle","r":"March 14, 2012","l":"https://en.wikipedia.org/wiki/Azkend_2:_The_World_Beneath","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co23ph.jpg","s":"Azkend 2: The World Beneath is a beautifully polished match-three adventure game set in an awe-inspiring underground world. Enjoy superbly smooth casual matching puzzle gameplay, an engaging storyline with voiceovers, and hidden object minigames."},{"t":"Babel Rising","p":["Windows"],"r":"August 7","l":"https://en.wikipedia.org/wiki/Babel_Rising"},{"t":"Bad Hotel","p":["iOS"],"d":"Lucky Frame","u":"Lucky Frame","g":"Tower defense","r":"August 14, 2012","l":"https://en.wikipedia.org/wiki/Bad_Hotel","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co30ej.jpg","s":"An insane hybrid of a tower defense game and a procedural music toy with tons of bullets (and healthy number of Wu-Tang references and credit crunch satire).\n\nThe hit game for iOS now available on Windows and Mac! You are a budding entrepreneur, whose hotel is rather unfortunately located within the territory of Tarnation Tadstock, the Texas Tyrant. Your only defense against Tadstock’s army of seagulls, rats, yetis, and more is to build your hotel as quickly and intelligently as possible, using an array of increasingly sophisticated weapons.\n\nThe beautiful artwork, quirky storyline, and frantic gameplay all work seamlessly together with a generative music system, which creates original music depending on the player’s actions and decisions. The player becomes a composer, creating complex musical structures to defend their hotel. A vast variety of music can be generated, from delicate beach chillout to country banjo techno."},{"t":"Bad Piggies","p":["iOS","Android","Windows","macOS"],"g":"Puzzle","r":"September 27","l":"https://en.wikipedia.org/wiki/Bad_Piggies","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co49p4.jpg","s":"Bad Piggies is a puzzle video game and a spin-off to Angry Birds. Unlike previous games in the series, in this entry the player controls the pigs, building devices that travel on land and air to find pieces of a map to find the Angry Birds' eggs The objective of the game is to build a contraption that transports the pig from a starting point to the finish line, usually indicated by a map. Such contraptions are made of wood and iron as well as other objects such as wheels, soda bottles, umbrellas (to increase air resistance), motors, fans, TNT, and balloons."},{"t":"Baka and Test","p":[],"l":"https://en.wikipedia.org/wiki/Baka_and_Test"},{"t":"Baldur's Gate: Enhanced Edition","p":["Windows","iOS"],"d":"Overhaul Games","u":"Atari , Beamdog","g":"RPG","r":"November 28","l":"https://www.igdb.com/games/baldur-s-gate-enhanced-edition","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7ugr.jpg","s":"Running on an upgraded and improved version of the Infinity Engine, Baldur's Gate: Enhanced Edition includes the entire Baldur's Gate adventure, the Tales of the Sword Coast expansion pack, and never-before-seen content including a new adventure and three new party members: the Calishite monk Rasaad yn Bashir, Neera the wild mage, and Dorn Il-Khan, the evil blackguard."},{"t":"Bang Bang Racing","p":["Xbox 360","Windows"],"r":"June 6","l":"https://en.wikipedia.org/wiki/Bang_Bang_Racing"},{"t":"Basketball Pro Management","p":["Windows"],"d":"Umix Studios","u":"Umix Studios","g":"Sports game, Business simulation, Sports Management","r":"January 12, 2012","l":"https://en.wikipedia.org/wiki/Basketball_Pro_Management"},{"t":"Bastion","p":["iOS"],"r":"August 29","l":"https://en.wikipedia.org/wiki/Bastion_(video_game)"},{"t":"Batman: Arkham City Armored Edition","p":["Wii U"],"r":"November 18"},{"t":"Batman: Arkham City Game of the Year Edition","p":["macOS"],"r":"December 13"},{"t":"Battle of the Bulge","p":["iOS","Android","macOS","Windows"],"d":"Shenandoah Studio","u":"Shenandoah Studio, Slitherine Software","g":"Computer wargame","r":"December 13, 2012","l":"https://en.wikipedia.org/wiki/Battle_of_the_Bulge_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22zh.jpg","s":"Battle of the Bulge is a fast-paced WW2 game where precise movement and detailed planning make the difference between a vain attempt and a brave operation."},{"t":"Battleloot Adventure","p":["iOS","Android","Windows Phone"],"u":"Digital Tales","g":"tactical role-playing, single-player video game","r":"March 2012","l":"https://en.wikipedia.org/wiki/Battleloot_Adventure","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4bno.jpg","s":"Battleloot Adventure blends comedy and turn-based combat in a role-playing adventure.\n\nKey features include pledging your allegiance to one of four cities: The Stalwart Citadel, The Shady Docks, The Magnificent Academy and The Sparkling Tower.\nRecruit an assortment of adventurers, each with their own perks and unique skills.\nCarefully choose your 3 ideal adventurers to face each danger ahead.\nUpgrade and customize your characters and their abilities."},{"t":"Battleship","p":["PlayStation 3","Xbox 360","Nintendo DS","Nintendo 3DS"],"r":"May 15","l":"https://en.wikipedia.org/wiki/Battleship_(2012_video_game)"},{"t":"Beach Buggy Blitz","p":["Android","iOS","BlackBerry OS"],"d":"Vector Unit","u":"Vector Unit","g":"Racing","l":"https://en.wikipedia.org/wiki/Beach_Buggy_Blitz","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobpxp.jpg","s":"Beach Buggy Blitz is built around an “infinite drive” mechanic that challenges you to drive as far as possible through lushly detailed, procedurally generated levels -- power-sliding through beaches and volcanoes, flying through the air off massive jumps, and smashing through totally destructible obstacles.\n\nCollect coins along the way to upgrade or paint your car, unlock new vehicles and drivers, even customize the game itself with new powerups and consumables."},{"t":"Beat Sneak Bandit","p":["iOS"],"r":"February 16","l":"https://en.wikipedia.org/wiki/Beat_Sneak_Bandit"},{"t":"Beat Up Anita Sarkeesian","p":[],"l":"https://en.wikipedia.org/wiki/Beat_Up_Anita_Sarkeesian"},{"t":"Beatmania IIDX 20: Tricoro","p":["Arcade"],"d":"Konami Corporation","u":"Konami Corporation","g":"Music","r":"September 19, 2012","l":"https://en.wikipedia.org/wiki/Beatmania_IIDX_20:_Tricoro"},{"t":"Bee Leader","p":["iOS","Windows Phone","Android","macOS","Windows"],"d":"Flightless","u":"Flightless","g":"Arcade","r":"May 24, 2012","l":"https://en.wikipedia.org/wiki/Bee_Leader","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobn7l.jpg","s":"The bees need you! Become a Bee Leader and help the bees fill their hives with honey."},{"t":"Ben 10: Galactic Racing","p":["PlayStation Vita"],"r":"February 22"},{"t":"Ben 10: Omniverse","p":["Wii U"],"r":"November 18"},{"t":"Ben Jordan: Paranormal Investigator","p":["Windows"],"d":"Grundislav Games","u":"Grundislav Games","g":"Point-and-click adventure","r":"August 8, 2012","l":"https://en.wikipedia.org/wiki/Ben_Jordan:_Paranormal_Investigator"},{"t":"Beyond the Labyrinth","p":["Nintendo 3DS"],"d":"tri-Ace","u":"Konami","g":"Action role-playing game, dungeon crawl","r":"January 19, 2012","l":"https://en.wikipedia.org/wiki/Beyond_the_Labyrinth","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaq2n.jpg","s":"Labyrinth no Kanata is a first-person RPG dungeon crawler for the Nintendo 3DS. The game was only released in Japan.\n\nThe game revolves around a group of players who have begun playing an online multiplayer game, only to find themselves thrust into a world completely different from theirs. They encounter a girl who has become trapped in this world's Labyrinth, and the two parties must work together to find a way out."},{"t":"Big Sky Infinity","p":["PlayStation 3","PlayStation Vita"],"r":"December 11"},{"t":"Binary Domain","p":["PlayStation 3","Xbox 360","Windows"],"g":"Shooter, Puzzle","r":"February 28","l":"https://en.wikipedia.org/wiki/Binary_Domain","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qu7.jpg","s":"The Machine Age has begun in the immersive and atmospheric squad-based shooter Binary Domain. Regain control of a futuristic Tokyo from an emerging robotic threat in the year 2080. The story starts when Dan Marshall and his squad are sent to bring the robotic community under control as they begin to infiltrate society and slowly take over undetected, leaving humans redundant in their wake. Fighting through the derelict lower levels of the city, players control an international peace-keeping squad that soon starts to question their surroundings and the choices they make. Are the robots becoming more human, or are humans becoming more like machines?\n\nThrilling encounters with these highly intelligent robotic enemies require you to think tactically, make challenging, real-time moral decisions and build up trust with your team mates in order to guide your squad to safety and success."},{"t":"Bingo Blitz","p":["Facebook","iOS","Android","Windows"],"d":"Playtika","u":"Playtika","g":"Social network game","l":"https://en.wikipedia.org/wiki/Bingo_Blitz"},{"t":"BioShock 2","p":["macOS"],"r":"March 29","l":"https://en.wikipedia.org/wiki/BioShock_2"},{"t":"Birds of Steel","p":["PlayStation 3","Xbox 360"],"r":"March 13","l":"https://en.wikipedia.org/wiki/Birds_of_Steel"},{"t":"Black Knight Sword","p":["PlayStation Network","Xbox 360"],"r":"December 11","l":"https://en.wikipedia.org/wiki/Black_Knight_Sword"},{"t":"Black Out!","p":["Atari Jaguar","Atari Jaguar CD"],"d":"Stormworks Interactive","u":"Stormworks Interactive","g":"Puzzle","r":"July 9, 2012","l":"https://en.wikipedia.org/wiki/Black_Out!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7i64.jpg"},{"t":"Blacklight: Retribution","p":["Windows"],"g":"Shooter","r":"April 3","l":"https://www.igdb.com/games/blacklight-retribution","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ud1.jpg","s":"Take firefights to a futuristic new level in Blacklight: Retribution, a free-to-play FPS. See through walls with the HRV, deploy mechanized Hardsuits, and customize your weapons to dominate the opposition.\n\nIn Blacklight, mastering the futuristic tech is half of victory. You'll need to carefully balance your loadout, from the extreme customization possible in designing your firearms, to the equipment you carry and the in-match bonuses you can unlock. The Hyper Reality Visor (HRV) allows you to look through walls and spot enemies, and attack from where they aren't expecting - but be careful, because you're vulnerable while using it.\n\nThe other half of victory? Raw skill, same as it's always been. Good hunting, Agent..."},{"t":"Blade & Soul","p":["Windows"],"g":"Role-playing (RPG)","l":"https://en.wikipedia.org/wiki/Blade_&_Soul","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wny.jpg","s":"Blade & Soul is a MMORPG currently in development by NCsoft's Team Bloodlust development team. The characters in this oriental style game are designed by the well-known illustrator Hyung-tae Kim."},{"t":"Blades of Time","p":["PlayStation 3","Xbox 360","Windows","macOS"],"g":"Shooter, Role-playing (RPG), Hack and slash/Beat 'em up, Adventure","r":"March 6","l":"https://en.wikipedia.org/wiki/Blades_of_Time","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24mi.jpg","s":"Ayumi, the gorgeous gun and sword-wielding treasure hunter, sets out on a journey to an ancient island in search of new adventures. While rich in bounty, the island is also filled with the magic of Chaos, being at the same time home to blood thirsty monsters."},{"t":"Blast-A-Way","p":["iOS"],"r":"August 30","l":"https://en.wikipedia.org/wiki/Blast-A-Way"},{"t":"BlazBlue: Chrono Phantasma","p":["Arcade"],"d":"Arc System Works","u":"Arc System Works, Aksys Games, PQube","g":"Fighting, Visual novel","r":"November 21, 2012","l":"https://en.wikipedia.org/wiki/BlazBlue:_Chrono_Phantasma","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2pkl.jpg","s":"BlazBlue: Chrono Phantasma, released in Japan as BlazBlue: Chronophantasma, is a 2D fighting game developed by Arc System Works. It is the third game of the Blazblue series, set after the events of BlazBlue: Continuum Shift. Besides normal rebalancing from Continuum Shift Extend, Chrono Phantasma features several revamped gameplay mechanics and introduces seven new characters to the roster. The character sprites have also been redrawn and several new songs were composed for the game. All previous musical themes were re-arranged. The storyline continues after events of Continuum Shift. A new mechanic called \"Overdrive\" has been added to the game, replacing the Gold Bursts from Continuum Shift."},{"t":"BlazBlue: Clone Phantasma","p":["Nintendo 3DS"],"d":"Arc System Works","u":"Arc System Works","g":"Fighting","r":"December 26, 2012","l":"https://en.wikipedia.org/wiki/BlazBlue:_Clone_Phantasma"},{"t":"BlazBlue: Continuum Shift Extend","p":["PlayStation 3","Xbox 360","PlayStation Vita"],"r":"February 14"},{"t":"Bleed","p":["Linux","Xbox 360","Xbox"],"d":"Bootdisk Revolution","g":"Platform","r":"December 12, 2012","l":"https://en.wikipedia.org/wiki/Bleed_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co232i.jpg","s":"Wryn is a girl with a big arsenal and big dreams and she wants to be the ultimate videogame hero! Help her take down the Greatest Heroes of All Time in an action-packed bid to claim the title for herself and show the world what a true hero looks like!\n\nBleed is an action-platformer focused on stylish, acrobatic dodging and fluid, challenging gameplay. There's no filler, just you and your skills against seven levels of enemies, obstacles, breakneck set-pieces and inventive bosses."},{"t":"Blocksworld","p":["iOS","Windows","macOS"],"d":"BoldaiAB, Linden Lab, Fortell Games Inc., Blocksworld LLC","u":"Linden Lab, BoldaiAB, Fortell Games","g":"Sandbox","r":"November 21, 2012","l":"https://en.wikipedia.org/wiki/Blocksworld"},{"t":"Bloodforge","p":["Xbox 360"],"r":"April 25","l":"https://en.wikipedia.org/wiki/Bloodforge"},{"t":"Bloody Vampire","p":["Nintendo 3DS"],"d":"Silver Star","u":"Agetec","g":"Platform-adventure, Metroidvania","r":"April 25, 2012","l":"https://en.wikipedia.org/wiki/Bloody_Vampire","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7ytl.jpg","s":"An eShop exclusive Nintendo 3DS action platformer"},{"t":"Borderlands 2","p":["PlayStation 3","Windows","Xbox 360","macOS"],"u":"2K","g":"Action, RPG","r":"September 18, 2012","l":"https://en.wikipedia.org/wiki/Borderlands_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9ba3.jpg","s":"The Ultimate Vault Hunter’s Upgrade lets you get the most out of the Borderlands 2 experience."},{"t":"Borderlands Legends","p":["iOS"],"d":"Gearbox Software","u":"2K","g":"Real-time strategy","r":"October 31, 2012","l":"https://en.wikipedia.org/wiki/Borderlands_Legends","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8i9n.jpg","s":"Borderlands Legends brings Gearbox's franchise to iOS and features the four characters from the original game in a top down arena-based game."},{"t":"Botanicula","p":["Linux","macOS","Windows","Android"],"d":"Amanita Design","u":"Amanita Design, Daedalic Entertainment","g":"Graphic adventure game","r":"April 19, 2012","l":"https://en.wikipedia.org/wiki/Botanicula","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24mj.jpg","s":"Humor-filled indie adventure game created by the makers of Machinarium.\n\nLike the previous games from Amanita Design, in Botanicula the player controls a protagonist (or multiple protagonists) while exploring the environment, solving puzzles and collecting items that are required for the obstacles that come in their way. The player is able to interact with other creatures and find easter eggs that are present in the lush environment. Like Machinarium, the game has no spoken or written dialogue."},{"t":"Boyfriend Maker","p":[],"l":"https://en.wikipedia.org/wiki/Boyfriend_Maker"},{"t":"Bratz: Fashion Boutique","p":["Nintendo 3DS","Nintendo DS"],"r":"October 30"},{"t":"Brave","p":["Windows","PlayStation 3","Xbox 360","Wii","PlayStation Vita","Nintendo DS","Nintendo 3DS"],"r":"June 19","l":"https://en.wikipedia.org/wiki/Brave_(2012_video_game)"},{"t":"Bravely Default","p":["Nintendo 3DS"],"d":"Silicon Studio, Cattle Call","u":"Square Enix, Nintendo","g":"Role-playing","r":"October 11, 2012","l":"https://en.wikipedia.org/wiki/Bravely_Default","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co25nj.jpg","s":"Bravely Default follows the story of main character Tiz, a humble shepherd and the lone survivor of a cataclysmic event, as he joins a group of loyal companions on a journey to restore balance to the world. The battle system is what differentiates Bravely Default from other RPGs. Here players can strategically choose when to initiate two complementary commands: Brave and Default. This innovative system encourages players to think carefully about strategy during every enemy encounter. Selecting \"Brave\" lets players increase the number of actions a character can take in a turn, while \"Default\" allows players to store actions for later use."},{"t":"Bravely Default: Praying Brage","p":["Browser"],"d":"NHN Hangame","u":"Square Enix","r":"November 1, 2012","l":"https://en.wikipedia.org/wiki/Bravely_Default:_Praying_Brage","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5uvt.jpg","s":"Bravely Default: Praying Brage was a free-to-play web browser game in the Bravely series that started its open beta phase on November 1, 2012. The game is set 200 years after the events of Bravely Default. The game has ended its service as of April 24, 2019."},{"t":"Broken Picture Telephone","p":[],"l":"https://en.wikipedia.org/wiki/Broken_Picture_Telephone"},{"t":"Brothers Conflict","p":[],"l":"https://en.wikipedia.org/wiki/Brothers_Conflict"},{"t":"Bubble Guppies","p":["Nintendo DS"],"r":"November 6","l":"https://en.wikipedia.org/wiki/Bubble_Guppies"},{"t":"Bubble Safari","p":["Browser","Facebook","iOS"],"d":"Zynga","g":"Puzzle, social network game","r":"May 9, 2012","l":"https://en.wikipedia.org/wiki/Bubble_Safari"},{"t":"Bug Princess 2","p":["iOS"],"r":"April 5","l":"https://en.wikipedia.org/wiki/Mushihime-sama_Futari"},{"t":"Bullet Run","p":["Windows"],"d":"ACONY","u":"Sony Online Entertainment","g":"First-person shooter","r":"July 31, 2012","l":"https://en.wikipedia.org/wiki/Bullet_Run","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/zxvqo3chosv7ls2x3wkb.jpg","s":"Set in the near future, Bullet Run is the hottest new reality TV game show. In Bullet Run it's not simply gaining the kill that wins you fame. Style and attitude, combined with a hair trigger and cat like reflexes will bring contestants the fame they so desperately desire. Stardom is at your fingertips. \n \nTime to step up, dress it up and take 'em out!"},{"t":"Burn the Rope","p":["PlayStation Vita"],"r":"December 18"},{"t":"Burnout Crash!","p":["iOS"],"r":"April 11","l":"https://en.wikipedia.org/wiki/Burnout_Crash!"},{"t":"Cabela's Dangerous Hunts 2013","p":["Wii U","PlayStation 3","Xbox 360","Windows","Wii"],"d":"Cauldron","u":"Activision","g":"Hunting, action, simulation","r":"October 23, 2012","l":"https://en.wikipedia.org/wiki/Cabela's_Dangerous_Hunts_2013","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5x8h.jpg","s":"In an epic story written by Andrew Kreisberg of Fringe, two brothers are torn apart after the death of their father at the hands of a grizzly bear. Ten years later, the estranged brothers reunite for the hunt of their lives. One beast tore them apart. Can another beast bring them back together?\n\nIn Cabela's Dangerous Hunts 2013 you get Deadlier Predators, Deadlier Hunts:\n\nSmarter and Deadlier Predators - The new Prowler animal AI engine simulates pack social hierarchies, coordinates complex group tactics and takes advantage of the surroundings to set up deadly ambushes.\n\nNew Maneater Co-op Mode - Two players can join together to take on wave after wave of increasingly deadly beasts in the all-new Maneater co-op mode."},{"t":"Cafeteria Nipponica","p":["Android","iOS"],"d":"Kairosoft","g":"Simulation","r":"April 2012","l":"https://en.wikipedia.org/wiki/Cafeteria_Nipponica","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4sl6.jpg","s":"In Cafeteria Nipponica you are the owner of a restaurant. Your job is to take your meager beginning resources and create the grandest restaurant with the best staff and largest customer base possible."},{"t":"Call of Cthulhu: The Wasted Land","p":["iOS"],"r":"January 30"},{"t":"Call of Duty: Black Ops II","p":["Windows","PlayStation 3","Xbox 360","Wii U"],"g":"Shooter","r":"November 13","l":"https://www.igdb.com/games/call-of-duty-black-ops-ii","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1wkv.jpg","s":"Pushing the boundaries of what fans have come to expect from the record-setting entertainment franchise, Call of Duty: Black Ops II propels players into a near future, 21st Century Cold War, where technology and weapons have converged to create a new generation of warfare between old and new foes. In this conflict, the mechanized creations of men reign supreme, facing off against each other as their creators stay safe and unconflicted, and in the process grow ever softer. In this scenario an important question will be asked: What happens when an enemy steals the keys to your war? To understand such a possible future, you must understand where you have been."},{"t":"Call of Duty: Black Ops: Declassified","p":["PlayStation Vita"],"r":"November 13"},{"t":"Canabalt","p":["PlayStation Portable"],"r":"April 3","l":"https://en.wikipedia.org/wiki/Canabalt"},{"t":"Candy Crush Saga","p":["iOS","Android"],"g":"Puzzle, Strategy, Arcade","r":"November 14","l":"https://en.wikipedia.org/wiki/Candy_Crush_Saga","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co25lo.jpg","s":"Candy Crush Saga is a free-to-play match-three puzzle video game released by King as a variation of their browser game Candy Crush. In the game, players complete levels by swapping colored pieces of candy on a game board to make a match of three or more of the same color, eliminating those candies from the board and replacing them with new ones, which could potentially create further matches. Boards have various goals that must be completed within a fixed number of moves, such as collecting a specific number of a type of candy."},{"t":"Capcom Digital Collection","p":["Xbox 360"],"r":"March 27","l":"https://en.wikipedia.org/wiki/Capcom_Digital_Collection"},{"t":"Captain Morgane and the Golden Turtle","p":["Windows","PlayStation 3","Wii","Nintendo DS"],"d":"Wizarbox","u":"Reef Entertainment","g":"Adventure","r":"March 16, 2012","l":"https://en.wikipedia.org/wiki/Captain_Morgane_and_the_Golden_Turtle","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8ibp.jpg","s":"Captain Morgane and the Golden Turtle is a pirate themed adventure game about a girl who goes on a quest to find the legendary \"Golden Turtle\". Make decisions, but remember - your actions have direct consequences for those depending on you."},{"t":"Carmageddon","p":["iOS"],"r":"October 17","l":"https://en.wikipedia.org/wiki/Carmageddon"},{"t":"Carrier Command: Gaea Mission","p":["Windows","Xbox 360"],"r":"October 2"},{"t":"Castle Crashers","p":["Windows"],"r":"September 26","l":"https://en.wikipedia.org/wiki/Castle_Crashers"},{"t":"Catch-22","p":["iOS","Android"],"d":"Mango Down","r":"September 25, 2012","l":"https://en.wikipedia.org/wiki/Catch-22_(video_game)"},{"t":"Cave Story","p":["Nintendo 3DS"],"u":"Nicalis","r":"October 4, 2012","l":"https://en.wikipedia.org/wiki/Cave_Story"},{"t":"Caverns of Minos","p":["iOS"],"r":"January 18","l":"https://en.wikipedia.org/wiki/Caverns_of_Minos"},{"t":"Chaos on Deponia","p":["Windows","macOS"],"d":"Daedalic Entertainment","u":"Daedalic Entertainment","g":"Graphic adventure, Point-and-click Adventure","r":"October 12, 2012","l":"https://en.wikipedia.org/wiki/Chaos_on_Deponia","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qqo.jpg","s":"With this long-expected sequel to the critically highly acclaimed and lavishly praised Deponia, the player enters round two. Chaos on Deponia turns out to be even wackier than its predecessor and instantly puts the player under its spell."},{"t":"Chaos Rings","p":["Android"],"r":"October 10","l":"https://en.wikipedia.org/wiki/Chaos_Rings"},{"t":"Chaos Rings II","p":["iOS"],"r":"March 15","l":"https://en.wikipedia.org/wiki/Chaos_Rings_II"},{"t":"Chasing Aurora","p":["Wii U"],"r":"November 18"},{"t":"ChefVille","p":["Browser"],"d":"Zynga","g":"Social simulation game","r":"August 2012","l":"https://en.wikipedia.org/wiki/ChefVille"},{"t":"Cherry Tree High Comedy Club","p":["Windows"],"r":"November 8","l":"https://en.wikipedia.org/wiki/Cherry_Tree_High_Comedy_Club"},{"t":"Chimpact","p":["iOS"],"r":"August 9"},{"t":"Chivalry: Medieval Warfare","p":["Windows"],"g":"Fighting, Hack and slash/Beat 'em up, Indie","r":"October 16","l":"https://www.igdb.com/games/chivalry-medieval-warfare","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qqc.jpg","s":"Chivalry: Medieval Warfare is a fast-paced online multiplayer action game which will have players turning in their guns and grenades for battle axes and swords. Chivalry: Medieval Warfare combines a sharp melee edge and familiar competitive gameplay along with the genuine look and feel of open-field combat in the Middle Ages. Players will use different attacks, blocks and counters insuring that combat is tactical, responsive and of course chaotic."},{"t":"Chocobo no Chocotto Nouen","p":["iOS","Android"],"g":"Simulator","l":"https://en.wikipedia.org/wiki/Chocobo_no_Chocotto_Nouen","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1vrz.jpg","s":"Chocobo no Chocotto Nouen is a farming simulation with Chocobo for GREE Social in Japan."},{"t":"Choplifter HD","p":["Windows"],"r":"January 10","l":"https://en.wikipedia.org/wiki/Choplifter_HD"},{"t":"ChronoBlade","p":["Facebook","iOS","Android"],"d":"nWay Games","u":"nWay Games","g":"ARPG","l":"https://en.wikipedia.org/wiki/ChronoBlade"},{"t":"Chronovolt","p":["PlayStation Vita"],"r":"December 31","l":"https://en.wikipedia.org/wiki/Chronovolt"},{"t":"Ciel Nosurge","p":["PlayStation Vita","PlayStation 4","Windows"],"d":"Gust","u":"Koei Tecmo","g":"Life simulation, social game","r":"April 26, 2012","l":"https://en.wikipedia.org/wiki/Ciel_Nosurge","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2xqa.jpg","s":"Set in a distant world on the verge of collapse, Ciel Nosurge follows the mysterious girl Ionasal as she attempts to recover her lost memories and communicate with a player from another dimension. Combining visual novel storytelling, life simulation elements and music-driven science fantasy worldbuilding, the game explores themes of connection, identity and reconstruction across worlds. Originally released episodically on PlayStation Vita, the story was expanded over multiple downloadable chapters and world packs."},{"t":"Cinders","p":["Windows","macOS"],"d":"MoaCube","u":"MoaCube","g":"Visual novel","r":"June 20, 2012","l":"https://en.wikipedia.org/wiki/Cinders_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co722b.jpg","s":"Cinders is a mature take on a classic fairytale with a heavy emphasis on player choices and role playing."},{"t":"CityVille 2","p":["Browser"],"d":"Zynga East","u":"Zynga","g":"City-building, construction and management simulation","r":"November 1, 2012","l":"https://en.wikipedia.org/wiki/CityVille_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocpdm.jpg","s":"The sequel of CityVille in 3D."},{"t":"Civilization V: Gods & Kings","p":["Windows","macOS"],"r":"June 19"},{"t":"Clan of Champions","p":["PlayStation 3","Windows","Xbox 360"],"r":"November 20","l":"https://en.wikipedia.org/wiki/Clan_of_Champions"},{"t":"Clash of Clans","p":["Android","iOS"],"g":"Real Time Strategy (RTS), Strategy","r":"August 2","l":"https://en.wikipedia.org/wiki/Clash_of_Clans","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1mb8.jpg","s":"Clash of Clans is an addictive mixture of strategic planning and competitive fast-paced combats. Raise an army of Barbarians, War Wizards, Dragons and other mighty fighters. Join a clan of players and rise through the ranks, or create your own Clan to contest ownership of the Realm."},{"t":"Clay Jam","p":["Mobile phone"],"d":"Fat Pebble","u":"Zynga","g":"Claymation","r":"November 29, 2012","l":"https://en.wikipedia.org/wiki/Clay_Jam","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co84on.jpg","s":"Save the land of Clay Jam from the fearsome Bully Beasts in this fun-packed action game. Guide Fat Pebble as he rolls down five weird and wonderful hills in a world made entirely from clay! Squash monsters on the way, and he'll grow and grow and GROW! Get all the way to the bottom of the hill and meet the nasty Bully Beasts. Can you collect enough clay to free the monsters and save Clay Jam?!"},{"t":"Cliff Diving","p":["PlayStation Vita"],"r":"February 21"},{"t":"CLOP","p":["Browser"],"d":"Bennett Foddy","g":"Sports","l":"https://en.wikipedia.org/wiki/CLOP","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4uer.jpg","s":"A spiritual successor to QWOP where Players control the individual limbs of a unicorn."},{"t":"Closure","p":["PlayStation Network","Windows","macOS"],"r":"March 27","l":"https://en.wikipedia.org/wiki/Closure_(video_game)"},{"t":"Code of Princess","p":["Nintendo 3DS"],"r":"October 9","l":"https://en.wikipedia.org/wiki/Code_of_Princess"},{"t":"Cognition: An Erica Reed Thriller","p":["Windows","macOS"],"d":"Phoenix Online Studios","u":"Phoenix Online Studios, Reverb Publishing","g":"Point-and-click adventure","r":"October 30, 2012","l":"https://en.wikipedia.org/wiki/Cognition:_An_Erica_Reed_Thriller","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2eig.jpg","s":"FBI agent Erica Reed has an uncanny talent: she can see the past and piece together how a crime unfolded. But not even this sixth sense could save her younger brother, Scott, from a brutal serial killer. Three years later, the investigation into Scott’s murder has gone cold -- but Erica’s work has only just begun.\n\nJump into Cognition: An Erica Reed Thriller, the exciting four-part series that brings Erica face to face with the deranged demons of her past. A serial killer is loose in Boston -- one who seems to be leaving deliberate clues that only Erica, with her unique post-cognitive abilities, can uncover. Is she finally on her way to solving Scott’s murder? Or, blinded by vengeance, is she falling into a trap that could cost Erica her life? And how does this new killer know her secret?\n\nDeveloped by Phoenix Online Studios (makers of the King’s Quest spin-off The Silver Lining), with contributions from veteran game designer Jane Jensen (Gabriel Knight, Gray Matter) and comic book artist Romano Molenaar (Batman, X-Men, The Darkness), Cognition is a thrilling adventure that grips you and won’t let go."},{"t":"Colors! 3D","p":["Nintendo 3DS"],"r":"April 5","l":"https://en.wikipedia.org/wiki/Colors!_3D"},{"t":"Combat Wings","p":["Windows","Xbox 360","PlayStation 3"],"d":"City Interactive Games","u":"City Interactive Games","g":"Combat flight simulation","l":"https://en.wikipedia.org/wiki/Combat_Wings"},{"t":"Command & Conquer: Tiberium Alliances","p":["Browser"],"d":"EA Phenomic","u":"Electronic Arts","g":"Massively multiplayer online real-time strategy","r":"May 24, 2012","l":"https://en.wikipedia.org/wiki/Command_&_Conquer:_Tiberium_Alliances","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20kg.jpg","s":"A free to play browser based MMO strategy game in the Command & Conquer franchise."},{"t":"Conception","p":["PlayStation Portable"],"d":"Chime","u":"Spike Chunsoft","g":"Role-playing, Dating sim","r":"April 26, 2012","l":"https://en.wikipedia.org/wiki/Conception_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9ueh.jpg","s":"Conception: Ore no Kodomo o Undekure! is a Japanese role-playing game and the first game in Spike Chunsoft's Conception series. The player's goal is to charm pure, innocent girls from Granvania National Star God Academy, raise their affection for Itsuki, then produce and take the \"Star Children\" to explore dungeons and battle \"impurities\"."},{"t":"Confrontation","p":["Windows"],"r":"April 5","l":"https://en.wikipedia.org/wiki/Confrontation_(video_game)"},{"t":"Cook, Serve, Delicious!","p":["Windows","macOS","Linux","iOS"],"d":"Vertigo Gaming","u":"Vertigo Gaming","g":"Simulation","r":"October 5, 2012","l":"https://en.wikipedia.org/wiki/Cook,_Serve,_Delicious!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24mn.jpg","s":"Cook, Serve, Delicious is a hardcore restaurant sim, one of the few in its genre that gives the players total control over where they want to take their restaurant."},{"t":"Corpse Party: Sweet Sachiko's Hysteric Birthday Bash","p":["PlayStation Portable"],"g":"Role-playing (RPG), Adventure","l":"https://en.wikipedia.org/wiki/Corpse_Party:_Sweet_Sachiko's_Hysteric_Birthday_Bash","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co26bq.jpg","s":"Corpse Party: Sweet Sachiko's Hysteric Birthday Bash is a different type of adventure in the Corpse Party series that stars the violent and murderous Sachiko Shinozaki, who has decided to invite her victims to Heavenly Host Elementary School to celebrate her birthday. However, this isn’t the type of party where the guests leave with a smile on their faces. Instead, Sachiko plans to force the students to participate in twisted games for her amusement. Will the students survive Sachiko’s celebration, or will they meet a Wrong End once again?"},{"t":"Cortex Command","p":["Windows","macOS","Linux"],"d":"Data Realms","u":"Data Realms","g":"Action","r":"September 28, 2012","l":"https://en.wikipedia.org/wiki/Cortex_Command","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2eiu.jpg","s":"In the world of Cortex Command, many humans have opted to amputate their entire natural bodies in order to prolong their lives and enable interstellar space travel. Their disembodied brains are hardly helpless, however, as they can remotely control all kinds of machines and craft through artificial interfaces.\n\nPlaying as one of these people's brains, you can quickly switch control between many different expendable bodies in order to complete otherwise dangerous tasks - all from the physical safety of your command bunker. Use these technological powers of telepathy to collect gold out of the fully destructible terrain, then purchase even more bodies and materiel with those newly acquired funds!\n\nYou can even program the crude A.I.s of your puppet army to complete simple tasks (patrolling, digging, etc.) while your attention and direct control is somewhere else. Use your accumulated forces to protect your brain, explore the world, and defeat your competition!"},{"t":"Counter-Strike: Global Offensive","p":["Windows","PlayStation Network","Xbox 360","macOS"],"g":"Shooter, Tactical","r":"August 21","l":"https://www.igdb.com/games/counter-strike-global-offensive","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coc32n.jpg","s":"Counter-Strike: Global Offensive is a team-based multiplayer first-person shooter developed by Valve and Hidden Path Entertainment. Two teams, Terrorists and Counter-Terrorists, compete in objective-based rounds across various game modes including bomb defusal, hostage rescue, and deathmatch. The game features an economy system where players purchase weapons and equipment at the start of each round based on performance in previous rounds. Competitive matchmaking, community servers, and a robust skin trading ecosystem support a large active player base."},{"t":"Counterfeit Monkey","p":["macOS","Windows"],"g":"Adventure","l":"https://en.wikipedia.org/wiki/Counterfeit_Monkey","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6ys9.jpg","s":"Anglophone Atlantis has been an independent nation since an April day in 1822, when a well-aimed shot from their depluralizing cannon reduced the British colonizing fleet to one ship.\n\nSince then, Atlantis has been the world's greatest center for linguistic manipulation, designing letter inserters, word synthesizers, the diminutive affixer, and a host of other tools for converting one thing to another. Inventors worldwide pay heavily for that technology, which is where a smuggler and industrial espionage agent such as yourself can really clean up.\n\nUnfortunately, the Bureau of Orthography has taken a serious interest in your activities lately. Your face has been recorded and your cover is blown.\n\nYour remaining assets: about eight more hours of a national holiday that's spreading the police thin; the most inconvenient damn disguise you've ever worn in your life; and one full-alphabet letter remover.\n\nGood luck getting off the island."},{"t":"Country Dance All Stars","p":["Xbox 360"],"r":"March 27"},{"t":"Crashmo","p":["Nintendo 3DS"],"r":"November 22","l":"https://en.wikipedia.org/wiki/Crashmo"},{"t":"Crazy Cars: Hit the Road","p":["Windows","iOS","Android"],"d":"Little World Entertainment","u":"Anuman","g":"Racing","r":"October 15, 2012","l":"https://en.wikipedia.org/wiki/Crazy_Cars:_Hit_the_Road"},{"t":"Crazy Machine Elements","p":["PlayStation Network"],"r":"January 10"},{"t":"Crazy Taxi","p":["iOS"],"r":"October 10","l":"https://en.wikipedia.org/wiki/Crazy_Taxi_(video_game)"},{"t":"Criminal Case","p":["Facebook","Browser"],"d":"Pretty Simple","g":"Puzzle","r":"November 15, 2012","l":"https://en.wikipedia.org/wiki/Criminal_Case_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co48vh.jpg","s":"Criminal Case - the #1 free hidden object game! Are you ready to solve murder cases?\nDownload now and discover who killed Rosa Wolf..."},{"t":"Criminal Minds","p":["Windows","macOS"],"d":"Legacy Games","u":"Legacy Games","g":"Mystery/Crime/Drama/Adventure","r":"April 19, 2012","l":"https://en.wikipedia.org/wiki/Criminal_Minds_(video_game)"},{"t":"Crimson Shroud","p":["Nintendo 3DS"],"d":"Level-5 , Nex Entertainment","u":"Level-5","g":"RPG","r":"December 13","l":"https://en.wikipedia.org/wiki/Crimson_Shroud"},{"t":"Critter Crunch","p":["Windows"],"r":"September 11","l":"https://en.wikipedia.org/wiki/Critter_Crunch"},{"t":"Crosswords DS","p":["Nintendo DS","Nintendo 3DS"],"d":"Nuevo Retro Games, Nintendo Software Technology","u":"Nintendo","g":"Puzzle","r":"October 1, 2012","l":"https://en.wikipedia.org/wiki/Crosswords_DS"},{"t":"Crosswords Plus","p":["Nintendo 3DS"],"r":"October 1","l":"https://en.wikipedia.org/wiki/Crosswords_Plus"},{"t":"Crusader Kings II","p":["Windows"],"g":"Role-playing (RPG), Simulator, Strategy","r":"February 14","l":"https://en.wikipedia.org/wiki/Crusader_Kings_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1mwa.jpg","s":"The Dark Ages might be drawing to a close, but Europe is still in turmoil. Petty lords vie against beleaguered kings who struggle to assert control over their fragmented realms. The Pope calls for a Crusade to protect the Christians in the Holy Land even as he refuses to relinquish control over the investiture of bishops - and their riches. Now is the time for greatness. Expand your demesne and secure the future of your dynasty. Fill your coffers, appoint vassals, root out traitors and heretics, introduce laws and interact with hundreds of nobles, each with their own agenda.\nA good lord will always need friends to support him. But beware, as loyal vassals can quickly turn to bitter rivals, and some might not be as reliable as they seem... Stand ready, and increase your prestige until the world whispers your name in awe. Do you have what it takes to become a Crusader King?\nCrusader Kings II explores one of the defining periods in world history in an experience crafted by the masters of Grand Strategy. Medieval Europe is brought to life in this epic game of knights, schemes, and thrones..."},{"t":"Crusader Kings II: Sunset Invasion","p":["Windows","macOS"],"d":"Paradox Development Studio","u":"Paradox Interactive","g":"Grand strategy","r":"November 15, 2012","l":"https://en.wikipedia.org/wiki/Crusader_Kings_II:_Sunset_Invasion"},{"t":"Crusader Kings II: Sword of Islam","p":[],"d":"Paradox Development Studio","u":"Paradox Interactive","g":"Grand strategy","r":"June 26, 2012","l":"https://en.wikipedia.org/wiki/Crusader_Kings_II:_Sword_of_Islam"},{"t":"Crush 3D","p":["Nintendo 3DS"],"r":"March 6","l":"https://en.wikipedia.org/wiki/Crush_3D"},{"t":"Cry of Fear","p":["Windows"],"d":"Team Psykskallar","u":"Team Psykskallar","g":"Survival horror, first-person shooter","l":"https://en.wikipedia.org/wiki/Cry_of_Fear","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6m51.jpg","s":"Cry of Fear is a single-player, horror modification for Half-Life 1 that brings you all the horrors you have always been afraid of.\nThis is a free total converstion of Half-Life 1, which means none of the assets from Half-Life 1 have been used in this mod or any files from other people, it is a totally unique experience. Everything is made exclusively by Team Psykskallar, the Cry of Fear developers."},{"t":"CSR Racing","p":["iOS","macOS","Android","Windows"],"d":"Boss Alien Ltd, Zynga","u":"NaturalMotion Games","g":"Racing","r":"June 28, 2012","l":"https://en.wikipedia.org/wiki/CSR_Racing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/kjr0puokurqoim5shlik.jpg","s":"CSR Racing is a racing game for mobile devices."},{"t":"Curiosity: What's Inside the Cube?","p":["iOS","Android"],"d":"22cans","u":"22cans","r":"November 6, 2012","l":"https://en.wikipedia.org/wiki/Curiosity:_What's_Inside_the_Cube%3F","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2f5u.jpg","s":"Curiosity – What's Inside the Cube? was an experimental video game by Peter Molyneux's studio 22Cans. Originally called Curiosity, the game was later renamed to avoid confusion with the Mars rover. The social experiment ended on 26 May 2013 and was won by Bryan Henderson from Edinburgh, Scotland."},{"t":"Cypher","p":["Windows","macOS"],"r":"August 31","l":"https://en.wikipedia.org/wiki/Cypher_(video_game)"},{"t":"Cytus","p":["iOS","Android","PlayStation Vita"],"d":"Rayark","u":"Rayark","g":"Rhythm game","r":"January 12, 2012","l":"https://en.wikipedia.org/wiki/Cytus","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1n4j.jpg","s":"200 songs and 400 variations, including many from famous composers around the world. Beautiful hand-drawn art style. Easy, intuitive Active Scan Line system and 3 types of notes. Different display modes allow player-friendly previewing of notes. Strong beat and rhythms provide satisfying feedback for taps. More than 9 difficulty levels for more fun and challenges. Various music genres: POP, JAZZ, TRANCE, HARDCORE, DRUM 'N BASS and much more."},{"t":"Da Capo III","p":[],"l":"https://en.wikipedia.org/wiki/Da_Capo_III"},{"t":"Da New Guys: Day of the Jackass","p":["Windows"],"d":"ICEBOX Studios","u":"Wadjet Eye Games","g":"Point-and-click adventure","r":"February 29, 2012","l":"https://en.wikipedia.org/wiki/Da_New_Guys:_Day_of_the_Jackass","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/bbndzmbcvwne8uo4ge7k.jpg","s":"In this adventure game from Icebox Studios and Wadjet Eye Games, Brain, the worst wrestler in Wrestle Zone, gets kidnapped after winning the championship belt and it's up to his friends to find him."},{"t":"Dahamkke Chachacha","p":["iOS","Android"],"d":"Turnon Games","u":"Netmarble","g":"Party","r":"December 31"},{"t":"Dance Central 3","p":["Xbox 360"],"r":"October 16","l":"https://en.wikipedia.org/wiki/Dance_Central_3"},{"t":"Danganronpa 2: Goodbye Despair","p":["PlayStation Portable"],"d":"Spike Chunsoft","u":"Spike Chunsoft","g":"Adventure, visual novel","r":"July 26, 2012","l":"https://en.wikipedia.org/wiki/Danganronpa_2:_Goodbye_Despair","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2h6j.jpg","s":"The follow up to Danganronpa: Trigger Happy Havoc. The main character, Hajime Hinata, a new 'Ultimate' student at Hope's Peak Academy. On their first day, Hajime and all of his classmates are taken on a field trip to the mysterious Jabberwock island by their anthropomorphic rabbit teacher, Usami. Usami explains that on this island the students are to have fun together and become friends to gather Hope Fragments. Usami's field trip does not go as planned when Monokuma appears and begins a new Killing Game. Anyone that wants to leave the island must commit a murder and get away with it. If the murderer is successful, he/she is allowed to leave the island, while everyone else is killed. When a murder occurs, the player investigates. After the investigations, a trial commences to determine who the culprit is."},{"t":"Dariusburst Second Prologue","p":["iOS"],"r":"February 10","l":"https://en.wikipedia.org/wiki/Dariusburst"},{"t":"Dark Scavenger","p":["Windows","macOS"],"d":"Psydra Games","u":"Psydra Games","g":"PCA","r":"July 12","l":"https://en.wikipedia.org/wiki/Dark_Scavenger"},{"t":"Dark Souls: Artorias of the Abyss","p":["Xbox 360"],"u":"Namco Bandai Games","r":"October 23, 2012"},{"t":"Dark Souls: Prepare to Die Edition","p":["Windows"],"r":"August 24"},{"t":"Darksiders II","p":["Windows","PlayStation 3","Xbox 360","Wii U"],"g":"Role-playing (RPG), Hack and slash/Beat 'em up, Adventure","r":"August 14","l":"https://en.wikipedia.org/wiki/Darksiders_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1wi5.jpg","s":"Become Death - The most feared of the legendary Four Horseman.\nEpic Universe – Unlike anything the player has seen before, delivered in the unique style of Joe Mad.\n\nPlayer Choice & Customization – Customize your experience with varied armor sets, weapons, and skill trees allowing players to create their own Death.\n\nExplore a vast open world, complete dozens of side quests and customize your Death with a full leveling system, skill trees and endless equipment combinations.\nDeath is a nimble and agile character capable of incredible acrobatic feats allowing the player to explore the world like never before."},{"t":"Darkstalkers 3","p":["PlayStation Network"],"r":"April 24","l":"https://en.wikipedia.org/wiki/Darkstalkers_3"},{"t":"Datura","p":["PlayStation 3"],"d":"Plastic","u":"Sony Computer Entertainment","g":"Adventure","r":"May 8, 2012","l":"https://en.wikipedia.org/wiki/Datura_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2n9r.jpg","s":"Explore the haunting world of Datura and embark on a voyage of mystery."},{"t":"Dead Block","p":["Windows"],"r":"January 26","l":"https://en.wikipedia.org/wiki/Dead_Block"},{"t":"Dead Hungry Diner","p":["Windows","macOS","iOS"],"d":"Black Market Games","u":"Black Market Games, Big Fish Games","g":"Puzzle, strategy","r":"April 23, 2012","l":"https://en.wikipedia.org/wiki/Dead_Hungry_Diner","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9u9r.jpg","s":"Dead Hungry Diner is all about big combos, spells, monsters fighting monsters and finding your flow within the monstrous mayhem!\nHelp Gabe and Gabby, patrons of “The Dead Hungry Diner”, as they feed the creatures of the night buckets and buckets of juicy Brain Berry goop!\n(Well... that’s the easy part!)\nDo you know what happens when you place werewolves near vampires?\nThey fight!!! And you don’t want fighting when you have so many other things to take care of..."},{"t":"Dead or Alive 5","p":["PlayStation 3","Xbox 360"],"g":"Fighting","r":"September 25","l":"https://en.wikipedia.org/wiki/Dead_or_Alive_5","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2pv9.jpg","s":"Dead or Alive 5 is a fighting game in the Dead or Alive series. It is the first Dead or Alive game to have a multi-platform release since Dead or Alive 2 as well as the series' first installment that was released for the PlayStation 3. Dead or Alive 5 features guest characters from Sega's Virtua Fighter fighting game series and several new gameplay mechanics, as well as improved graphics and a more realistic visual style than its predecessors. Its plot is set two years after the events of Dead or Alive 4, telling the interrelating stories of various characters in connection to the new DOA tournament and the continuing hunt for Kasumi's evil clone."},{"t":"Dead Trigger","p":["iOS","Android"],"d":"DECA Games","u":"DECA Games","g":"Shooter","r":"June 28, 2012","l":"https://en.wikipedia.org/wiki/Dead_Trigger","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobbj3.jpg","s":"“The world has collapsed.\n\nIn 2012 modern civilization is coming to an end. Global economics have been disrupted, money has lost its value. People have risen against the ignorant politicians who were just lining their pockets – and they didn't spare any of them.\n\nHowever, those who really ruled the world were prepared - and escaped. Suddenly billions of people died from a strange virus, while others turned into butcherly beasts with just one thought:\nTO KILL!\n\nOnly a few people on the planet have survived, at least until they run out of ammo... or learn how to stop them...”\n\nSmash hordes of bloodthirsty zombies * Secure vital supplies * Save other survivors * Protect the Safe Haven * Explore the city * and uncover the provoking truth in this intense FPS action game!"},{"t":"Deadlight","p":["Xbox 360","Windows"],"g":"Platform, Puzzle, Adventure, Indie","r":"August 1","l":"https://en.wikipedia.org/wiki/Deadlight_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wg7.jpg","s":"The world has ended. There is no hope. No new beginning. Only the survivors. DEADLIGHT follows the journey of Randall Wayne, a man searching for his family across Seattle during the aftermath of a 1980s event that has decimated life on earth. This visually stunning Cinematic Survival Platformer will challenge you to run, jump, climb, and struggle for your life as you look for answers and the ones you love."},{"t":"Dear Esther","p":["Windows","macOS"],"g":"Adventure, Indie","r":"February 15","l":"https://en.wikipedia.org/wiki/Dear_Esther","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2eez.jpg","s":"Two years in the making, the highly anticipated Indie remake of the cult mod Dear Esther arrives on PC. Dear Esther immerses you in a stunningly realised world, a remote and desolate island somewhere in the outer Hebrides. As you step forwards, a voice begins to read fragments of a letter: \"Dear Esther...\" - and so begins a journey through one of the most original first-person games of recent years. Abandoning traditional gameplay for a pure story-driven experience, Dear Esther fuses its beautiful environments with a breathtaking soundtrack to tell a powerful story of love, loss, guilt and redemption."},{"t":"Deep Black: Reloaded","p":["Windows"],"r":"March 1","l":"https://en.wikipedia.org/wiki/Deep_Black_(video_game)"},{"t":"Deer Drive Legends","p":["Nintendo 3DS"],"r":"May 27","l":"https://en.wikipedia.org/wiki/Deer_Drive_Legends"},{"t":"Defender's Quest","p":["Browser","Windows","PlayStation 4","Xbox One","PlayStation Vita"],"d":"Level Up Labs","u":"Level Up Labs","g":"Tower defense, role-playing game","r":"October 30, 2012","l":"https://en.wikipedia.org/wiki/Defender's_Quest"},{"t":"Defenders of Ardania","p":["Xbox 360","Windows"],"r":"March 14","l":"https://en.wikipedia.org/wiki/Defenders_of_Ardania"},{"t":"Demons' Score","p":["iOS","Android"],"r":"September 19","l":"https://en.wikipedia.org/wiki/Demons%27_Score"},{"t":"Den-noh Coil","p":[],"l":"https://en.wikipedia.org/wiki/Den-noh_Coil"},{"t":"Deponia","p":["Windows","macOS"],"d":"Daedalic Entertainment","u":"Daedalic Entertainment","g":"Graphic adventure","r":"January 27, 2012","l":"https://en.wikipedia.org/wiki/Deponia_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qqn.jpg","s":"Deponia is a fast-paced comedy of errors and one of the most unusual love stories in gaming history. The twist-filled story takes its off-beat characters all over trash planet Deponia, a unique game world in the style of Douglas Adams, Terry Pratchett and Matt Groening. From Kuvaq, an improvised village built inside a giant trash heap, to the swimming black market and the dark corners of the elevated planetary railways: The new adventure game from the makers of The Whispered World, Edna & Harvey: The Breakout and A New Beginning is brought to life with detailed hand-painted backgrounds in widescreen format and top-quality cartoon animation."},{"t":"Deus Ex: Human Revolution Ultimate Edition","p":["macOS"],"r":"April 26"},{"t":"Devil May Cry","p":["Xbox 360","PlayStation 3"],"d":"Capcom Production Studio 4","u":"Capcom","g":"Hack and slash/Beat 'em up, Adventure","r":"March 22, 2012","l":"https://www.igdb.com/games/devil-may-cry--1","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5tkk.jpg","s":"An HD remaster of Devil May Cry, first made available in \"Devil May Cry HD Collection.\"\n\nIn the first installment of the Devil May Cry series, the player controls Dante as he faces off against the resurrected Demon Emperor, Mundus. The game introduces Dante's abilities, like Devil Trigger which transforms him into a demon, swordplay, gun-slinging, and stylish combos, all of which have become a staple of the series."},{"t":"Devil May Cry 2","p":["PlayStation 3","Xbox 360"],"d":"Capcom Production Studio 1","u":"Capcom","g":"Hack and slash/Beat 'em up, Adventure","r":"March 22, 2012","l":"https://www.igdb.com/games/devil-may-cry-2--1","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5mud.jpg","s":"An HD remaster of Devil May Cry 2, first made available in \"Devil May Cry HD Collection.\"\n\nDevil May Cry 2 takes place many years after the first game. This installment introduces the ability to run along walls, the Rain Storm ability, and others, giving Dante even more freedom to defeat enemies in style. You can also play as the new character, Lucia, who uses speed as a weapon against enemies, as opposed to Dante who relies on power. The bonus mode, Bloody Palace, also makes its first appearance here."},{"t":"Devil May Cry 3: Dante's Awakening - Special Edition","p":["PlayStation 3","Xbox 360"],"d":"Capcom Production Studio 1","u":"Capcom","g":"Hack and slash/Beat 'em up, Adventure","r":"March 22, 2012","l":"https://www.igdb.com/games/devil-may-cry-3-dantes-awakening-special-edition--2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5mue.jpg","s":"An HD Remaster of Devil May Cry 3: Dante's Awakening - Special Edition, included in \"Devil May Cry HD Collection.\"\n\nDevil May Cry 3 takes place before the events of the first game. In this installment, you can choose different close-combat styles like Swordmaster and Gunslinger, and it's up to you which style you decide to develop and improve on. This Special Edition lets you play as Dante's brother Vergil."},{"t":"Devil May Cry: HD Collection","p":["PlayStation 3","Xbox 360"],"u":"Capcom","r":"April 3","l":"https://en.wikipedia.org/wiki/Devil_May_Cry"},{"t":"Devil's Attorney","p":["iOS"],"r":"October 11","l":"https://en.wikipedia.org/wiki/Devil%27s_Attorney"},{"t":"Diablo III","p":["Windows","macOS"],"g":"Role-playing (RPG), Hack and slash/Beat 'em up, Adventure","r":"May 15","l":"https://en.wikipedia.org/wiki/Diablo_III","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2l1u.jpg","s":"Diablo III is the third installment in Blizzard's franchise. The game, like its predecessors, is a dungeon crawler in which the player fights against hordes of enemies ranging from beasts and undead to actual demons. The game has four acts, two game modes (normal and hardcore) as well as four difficulty levels: Normal, Nightmare, Hell and Inferno. A new addition to Diablo III is the auction house, where items are exchanged for in-game gold or real money, also usable to purchase Blizzard merchandise. The game features a wide array of achievements earned upon meeting certain requirements."},{"t":"Diabolical Pitch","p":["Xbox 360"],"r":"April 4","l":"https://en.wikipedia.org/wiki/Diabolical_Pitch"},{"t":"Diabolik Lovers","p":[],"l":"https://en.wikipedia.org/wiki/Diabolik_Lovers"},{"t":"Diamond Trust of London","p":["Nintendo DS"],"d":"Jason Rohrer","u":"indiePub","g":"Turn-based strategy","r":"August 28, 2012","l":"https://en.wikipedia.org/wiki/Diamond_Trust_of_London","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobw7j.jpg","s":"A turn based strategy game funded via Kickstarter and released in 2012. Distribution was limited to Kickstarter backers and the website of the developer himself."},{"t":"Diggin' Dogs","p":["iOS"],"d":"Soap Creative","u":"Chillingo","g":"Puzzle","r":"February 9, 2012","l":"https://en.wikipedia.org/wiki/Diggin'_Dogs"},{"t":"Digimon Heroes!","p":["iOS"],"g":"Strategy, Turn-based strategy (TBS), Card & Board Game","l":"https://en.wikipedia.org/wiki/Digimon_Heroes!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3gkb.jpg","s":"Digimon Heroes! is a mobile match-3 card battle game set in the expansive Digimon universe. Players collect and evolve digital monsters known as Digimon to build powerful teams and engage in strategic battles. Through strategic deck-building and tactical gameplay, they embark on quests, battle against other players in PvP matches, and participate in special events to earn rewards and strengthen their Digimon."},{"t":"Digimon World Re:Digitize","p":["PlayStation Portable"],"d":"tri-Crescendo","u":"Bandai Namco Games","g":"Role-playing","r":"July 19, 2012","l":"https://en.wikipedia.org/wiki/Digimon_World_Re:Digitize","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2nkn.jpg","s":"In the game, the player follows and controls \"Taiga\", a 16-year-old male protagonist who is transported to the digital world of Digimon, which in his universe is merely an online game. In the universe of Digimon, people raise creatures collectively referred to as Digimon. Players raise the Digimon through stages of growth that determine his personality, the five stages being \"Baby\", \"Child\", \"Adult\", \"Perfect\" and \"Ultimate\". Digimon evolve over time by gaining stats and other factors. Digimon can get hungry, sick, injured or die and need care to recover."},{"t":"Dillon's Rolling Western","p":["Nintendo 3DS"],"r":"February 22","l":"https://en.wikipedia.org/wiki/Dillon%27s_Rolling_Western"},{"t":"Dino Storm","p":["Windows"],"d":"Splitscreen Games","u":"Splitscreen Games","g":"MMORPG","l":"https://en.wikipedia.org/wiki/Dino_Storm","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co30dr.jpg","s":"Dino Storm is a free-to-play browser MMORPG frosm Splitscreen Studios. This highly unique game brings players into an American Western setting, but with a genre-bending twist: you will play as a cowboy armed with a laser gun who rides a dinosaur."},{"t":"Dirt: Showdown","p":["Windows","PlayStation 3","Xbox 360"],"g":"Racing, Sport","r":"May 23","l":"https://www.igdb.com/games/dirt-showdown","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2gdp.jpg","s":"Race, crash and hoon your way through a world tour of motorised mayhem in DiRT Showdown! Crowd atmosphere, social gameplay and accessibility are all ramped up in this turbo- injected shot of driving delirium. Smash down the accelerator and earn the adulation of frenzied crowds at hyper-energised events at iconic locations. Trick, speed and smash your way to victory, then do it again."},{"t":"Disgaea 3: Absence of Detention","p":["PlayStation Vita"],"r":"April 17"},{"t":"Dishonored","p":["Windows","PlayStation 3","Xbox 360"],"u":"Bethesda Softworks","g":"Action, Adventure","r":"October 9, 2012","l":"https://en.wikipedia.org/wiki/Dishonored","i":"images/steam-205100.jpg","s":"Dishonored is an immersive first-person action game that casts you as a supernatural assassin driven by revenge. With Dishonored’s flexible combat system, creatively eliminate your targets as you combine the supernatural abilities, weapons and unusual gadgets at your disposal."},{"t":"Disney Princess: My Fairytale Adventure","p":["Nintendo 3DS","Wii","Windows"],"r":"September 14"},{"t":"District 187: Sin Streets","p":["Windows"],"d":"Netmarble","g":"First-person shooter","r":"November 20, 2012","l":"https://en.wikipedia.org/wiki/District_187:_Sin_Streets","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2g7z.jpg","s":"Gangsters and cops collide in this free-to-play first-person shooter."},{"t":"DJMax Ray","p":["iOS","Android"],"d":"Pentavision","u":"Neowiz Internet","g":"Music","r":"September 28, 2012","l":"https://en.wikipedia.org/wiki/DJMax_Ray","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/eemfncnzlekayuyb3ihe.jpg","s":"DJ Max Ray is the mobile version of Pentavision's popular rhythm game series."},{"t":"DJMax Technika Tune","p":["PlayStation Vita"],"d":"Pentavision, Neowiz Mobile","u":"Pentavision, Pentavision Global, CyberFront","g":"Music video game","r":"September 20, 2012","l":"https://en.wikipedia.org/wiki/DJMax_Technika_Tune","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co60q6.jpg","s":"DJMax Technika Tune is the 16th game in the DJMax series and is an adaptation of the DJMax Technika arcade game series, containing 67 songs and 4 game modes (Star Mixing, Pop Mixing, Club Mixing and Freestyle Mixing).\nTechnika Tune by default uses a control scheme where you use both the front touchscreen and rear touchpad, unlike other Technika games that can only use a single touch screen."},{"t":"Doc Clock: The Toasted Sandwich of Time","p":["PlayStation Network"],"r":"May 1"},{"t":"Doctor Who: The Eternity Clock","p":["PlayStation Network","PlayStation Vita"],"r":"May 23"},{"t":"Doctor Who: Worlds in Time","p":["Browser"],"d":"Three Rings Design","u":"SEGA / BBC Worldwide","g":"MMORPG","r":"March 12, 2012","l":"https://en.wikipedia.org/wiki/Doctor_Who:_Worlds_in_Time","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co67ex.jpg","s":"This free to play MMO will allow players to go into the TARDIS and help the Time lord defend civilizations from Infamous Doctor Who enemies."},{"t":"DoDonPachi SaiDaiOuJou","p":["Arcade"],"d":"Cave, exA-Arcadia, Live Wire","u":"Cave, exA-Arcadia, Live Wire","g":"Bullet Hell","r":"April 20, 2012","l":"https://en.wikipedia.org/wiki/DoDonPachi_SaiDaiOuJou","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2pxp.jpg","s":"DoDonPachi SaiDaiOuJou is a vertical scrolling shoot 'em up arcade game released by Cave in 2012. It's the sixth chapter in CAVE's DonPachi series. A Japanese region-free release was released on May 30, 2013."},{"t":"Dogfight 1942","p":["Windows","PlayStation 3","Xbox 360"],"d":"City Interactive Games","u":"City Interactive Games","g":"Combat flight simulation, Action","r":"September 5, 2012","l":"https://en.wikipedia.org/wiki/Dogfight_1942","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3ouc.jpg","s":"Piloting a wide range of aircraft, players engage in aerial dogfights and dangerous fighter missions across the major theaters of war during WWII."},{"t":"Dokuro","p":["PlayStation Vita"],"d":"Game Arts","u":"GungHo Online Entertainment","g":"Puzzle","r":"July 5, 2012","l":"https://en.wikipedia.org/wiki/Dokuro_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co23h2.jpg","s":"This charming, chalk-art puzzler tests your wits and tugs at your hearstrings as the bony underdog Dokuro strives to solve and swashbuckle his way through the Dark Lord's castle to save the Princess."},{"t":"Doom 3: BFG Edition","p":["Windows","Xbox 360","PlayStation 3"],"r":"October 16","l":"https://en.wikipedia.org/wiki/Doom_3_BFG_Edition"},{"t":"Double Dragon Neon","p":["PlayStation Network","Xbox 360"],"g":"Fighting, Hack and slash/Beat 'em up, Indie","r":"September 11","l":"https://en.wikipedia.org/wiki/Double_Dragon_Neon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2pya.jpg","s":"Twin brothers Billy and Jimmy have been kicking butt and taking names for 25 years. Join them in this bodacious re-imagining of the classic beat 'em up that started it all, Double Dragon Neon. Battle through glass-jawed goons, deadly teleporting geishas, scientific abominations, and more as you hunt down the evil Skullmageddon and save the love of your life, Marion."},{"t":"Double Fine Happy Action Theater","p":["Xbox 360"],"r":"February 1","l":"https://en.wikipedia.org/wiki/Double_Fine_Happy_Action_Theater"},{"t":"Dracu-riot!","p":["Windows"],"d":"Yuzu Soft","u":"Yuzu Soft","g":"Visual novel, eroge","r":"March 30, 2012","l":"https://en.wikipedia.org/wiki/Dracu-riot!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2fdg.jpg","s":"The story begins with Mutsura Yuuto accompanying his friend on a holiday to Aqua Eden, an artificial island city where gambling and the sex industry are legal.\n\nHowever, his holiday plans are laid to waste after he gets involved in a kidnapping; to make matters worse, he ends up getting turned into a vampire.\n\nAs a vampire, he can no longer leave Aqua Eden; so with nowhere else to go, he decides to enroll in a special school for vampires on the island — and thus, his new night life begins!"},{"t":"Dragon Ball Z Budokai: HD Collection","p":["PlayStation 3","Xbox 360"],"r":"November 6"},{"t":"Dragon Ball Z: For Kinect","p":["Xbox 360"],"r":"October 9"},{"t":"Dragon City","p":["Facebook"],"d":"Socialpoint","u":"Socialpoint","g":"Social network game","r":"May 2012","l":"https://en.wikipedia.org/wiki/Dragon_City","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2sj0.jpg","s":"Build yourself a magical city and fill it with buildings, habitats, and dragons! Feed your dragons and make them evolve into strong beasts! You'll be able to train them and teach them new skills. Collect over 600 dragons of different elements and rarities to complete the Dragon Book. You can become the top collector in the game! Battle against other players in the Dragon Leagues and face exciting challenges in the tournaments to win lots of rewards!"},{"t":"Dragon Coins","p":["iOS","Android"],"d":"Sega","u":"Sega","g":"Puzzle, role-playing","l":"https://en.wikipedia.org/wiki/Dragon_Coins"},{"t":"Dragon Quest X","p":["Wii"],"d":"Square Enix","u":"Square Enix","g":"Massively multiplayer online role-playing","r":"August 2, 2012","l":"https://en.wikipedia.org/wiki/Dragon_Quest_X"},{"t":"Dragon's Dogma","p":["PlayStation 3","Xbox 360"],"g":"Role-playing (RPG), Hack and slash/Beat 'em up, Adventure","r":"May 22","l":"https://en.wikipedia.org/wiki/Dragon%27s_Dogma","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8zm7.jpg","s":"Set in a huge open world, Dragon’s Dogma: Dark Arisen presents a rewarding action combat experience. Players embark on an epic adventure in a rich, living world with three AI companions, known as Pawns. These partners fight independently, demonstrating prowess and ability that they have developed based on traits learnt from each player. PC users can share these Pawns online and reap rewards of treasure, tips and strategy hints for taking down the terrifying enemies. Pawns can also be borrowed when specific skills are needed to complete various challenging quests."},{"t":"Dragon's Lair","p":["Xbox 360"],"r":"May 18","l":"https://en.wikipedia.org/wiki/Dragon%27s_Lair"},{"t":"DragonBox","p":["iOS","Android"],"d":"WeWantToKnow AS","u":"WeWantToKnow AS","g":"Educational game","r":"May 9, 2012","l":"https://en.wikipedia.org/wiki/DragonBox"},{"t":"Dramatical Murder","p":[],"l":"https://en.wikipedia.org/wiki/Dramatical_Murder"},{"t":"Draw Something","p":["Android","iOS","Windows Phone"],"g":"Puzzle","l":"https://en.wikipedia.org/wiki/Draw_Something","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1s86.jpg","s":"Draw Something, the most popular social drawing and guessing game! Experience for yourself the laugh-out-loud game your friends are raving about!"},{"t":"Drawception","p":["Browser"],"g":"Indie","l":"https://en.wikipedia.org/wiki/Drawception","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9ldz.jpg","s":"A game where players use their imagination and drawing skills to play a game similar to \"Telephone\" where every other person has to draw what the person says to them."},{"t":"Dream of Pixels","p":["iOS","Android"],"r":"November 14","l":"https://en.wikipedia.org/wiki/Dream_of_Pixels"},{"t":"Dream PetHouse","p":["iOS","Android"],"d":"Zynga","u":"Zynga","g":"Simulation video game","r":"February 2, 2012","l":"https://en.wikipedia.org/wiki/Dream_PetHouse","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9t2v.jpg","s":"Do you love animals? Then here's your chance to create the biggest, happiest home for hundreds of irresistibly cute pets in Dream PetHouse by Zynga! Collect the world's cutest animals and care for them in your own unique tree, staffed by Chipper and his group of adorable chipmunk friends!"},{"t":"Dungelot","p":["Browser"],"d":"Red Winter Software","g":"Roguelike","r":"December 8, 2012","l":"https://en.wikipedia.org/wiki/Dungelot","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/lusdyxngpbgd85dfzo7h.jpg","s":"Explore floor after floor of a dungeon in this minesweeper styled roguelike."},{"t":"Dungeon Defenders","p":["macOS"],"r":"March 15","l":"https://en.wikipedia.org/wiki/Dungeon_Defenders"},{"t":"Dungeon Hunter: Alliance","p":["PlayStation Vita"],"r":"February 22"},{"t":"Dungeon Village","p":["Android","iOS"],"d":"Kairosoft","g":"Simulation","r":"March 2, 2012","l":"https://en.wikipedia.org/wiki/Dungeon_Village","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2t3g.jpg","s":"Welcome to an epic RPG world in which the town you build can grow from humble hamlet into a mecca for the land's most ambitious adventurers!\n\nThe enterprising warriors that stop by your blossoming burg will defeat monsters and earn you money. Conquering dungeons and clearing out hordes of monsters will bag you loot to stock your shops. And if your hamlet flourishes, adventurers will want to set up house and settle down!\n\nBuild training facilities like Combat Schools and Magic Labs to hone your heroic denizens' skills and boost your village's Popularity. The more faces that flock to your cause, the bigger the baddies you can beat!\n\nAn all-new \"Cauldron\" feature also allows you to test your alchemic expertise. Toss items obtained from quests or shops into the Cauldron and your armory might receive a rare addition.\n\nNo dungeon is too deep! Make your village the crown estate of this bold RPG narrative!"},{"t":"Dungeons & Dragons: Daggerdale","p":["PlayStation Network"],"r":"May 22"},{"t":"Dust Racing 2D","p":["Windows","Linux"],"d":"Jussi Lind","u":"Jussi Lind","g":"Racing video game","l":"https://en.wikipedia.org/wiki/Dust_Racing_2D"},{"t":"Dust: An Elysian Tail","p":["Xbox 360"],"g":"Platform, Role-playing (RPG), Hack and slash/Beat 'em up, Adventure, Indie","r":"August 15","l":"https://www.igdb.com/games/dust-an-elysian-tail","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ish.jpg","s":"immerse yourself in a gorgeous hand-painted world on a search for your true identity. As the mysterious warrior, Dust, your action-packed journey will take you from peaceful glades to snowy mountaintops and beyond. At your disposal is the mythical Blade of Ahrah, capable of turning its wielder into an unstoppable force of nature, and the blade's diminutive guardian, Fidget. Battle dozens of enemies at once with an easy-to-learn, difficult-to-master combat system, take on a variety of quests from friendly villagers, discover ancient secrets and powerful upgrades hidden throughout the massive, open world, and uncover the story of an ancient civilization on the brink of extinction as you fight to uncover your own past."},{"t":"Dustforce","p":["Windows"],"r":"January 17","l":"https://en.wikipedia.org/wiki/Dustforce"},{"t":"Dyad","p":["PlayStation Network"],"r":"July 17","l":"https://en.wikipedia.org/wiki/Dyad_(video_game)"},{"t":"Dynasty Warriors Next","p":["PlayStation Vita"],"r":"February 22","l":"https://en.wikipedia.org/wiki/Dynasty_Warriors#Ports_on_other_systems"},{"t":"Dys4ia","p":["Browser"],"u":"Newgrounds","g":"Autobiography","r":"March 9, 2012","l":"https://en.wikipedia.org/wiki/Dys4ia","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4pmf.jpg","s":"Dys4ia is an abstract, autobiographical Adobe Flash video game that Anna Anthropy, also known as Auntie Pixelante, developed to recount her experiences of gender dysphoria and hormone replacement therapy."},{"t":"E.X. Troopers","p":["Nintendo 3DS","PlayStation 3"],"d":"Capcom, HexaDrive","u":"Capcom","g":"Action, Third-person shooter","r":"November 22, 2012","l":"https://en.wikipedia.org/wiki/E.X._Troopers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ic9.jpg","s":"An offshoot of the Lost Planet franchise, EX Troopers is an action game focused as much on character dynamics in a pilot school as it is on alien-blasting action."},{"t":"Ecolibrium","p":["PlayStation Vita"],"d":"StormBASIC Games","u":"Sony Computer Entertainment","g":"Simulation","r":"September 12, 2012","l":"https://en.wikipedia.org/wiki/Ecolibrium","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1leq.jpg","s":"A free-to-play Sci-Fi ecology simulator for PlayStation Vita. Controls a virtual ecosystem in which to grow and care for flora and fauna by manipulating four variables - Water, Minerals, Vegetation, and Meat - in order to create a balanced ecosystem."},{"t":"Electric City: The Revolt","p":[],"l":"https://en.wikipedia.org/wiki/Electric_City:_The_Revolt"},{"t":"Elemental: Fallen Enchantress","p":["Windows"],"r":"October 23"},{"t":"Elf Defense Eng","p":["iOS"],"d":"Jellyoasis","u":"Jellyoasis","g":"Tower defense","r":"February 1, 2012","l":"https://en.wikipedia.org/wiki/Elf_Defense_Eng"},{"t":"Emperors SaGa","p":["Android","iOS"],"d":"Square Enix, AltPlus","u":"Square Enix","g":"Role-playing","r":"September 18, 2012","l":"https://en.wikipedia.org/wiki/Emperors_SaGa"},{"t":"Endgame: Syria","p":["Browser","Android"],"d":"GameTheNews","g":"Trading card game newsgame","r":"December 12, 2012","l":"https://en.wikipedia.org/wiki/Endgame:_Syria"},{"t":"Endless Space","p":["Windows","macOS"],"d":"Amplitude Studios","u":"Iceberg Interactive","g":"Turn-based strategy, 4X","r":"July 4, 2012","l":"https://en.wikipedia.org/wiki/Endless_Space","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wci.jpg","s":"This galaxy is ancient, and its first intelligent life was the civilization we call the Endless. Long before our eyes gazed upon the stars they flew between them, though all that remains of this people is what we call Dust. A substance found scattered, or in forgotten temples, it once gave powers to admirals and galactic governors. The galaxy will belong to the faction that can take control of the Dust and uncover its secrets…"},{"t":"Ensemble Girls!","p":["Android","iOS"],"d":"Happy Elements K. K.","g":"Collectible card game, visual novel","l":"https://en.wikipedia.org/wiki/Ensemble_Girls!"},{"t":"Epic Mickey 2: The Power of Two","p":["PlayStation 3","Xbox 360","Wii","Wii U"],"r":"November 18"},{"t":"Epic Mickey: Power of Illusion","p":["Nintendo 3DS"],"r":"November 18"},{"t":"EpicMealTime","p":["Android","iOS"],"d":"Molecube","u":"Epic Meal Time","r":"July 25, 2012","l":"https://en.wikipedia.org/wiki/EpicMealTime_(video_game)"},{"t":"Escape Plan","p":["PlayStation Vita"],"r":"February 22","l":"https://en.wikipedia.org/wiki/Escape_Plan_(video_game)"},{"t":"ESPN Sports Connection","p":["Wii U"],"r":"November 18","l":"https://en.wikipedia.org/wiki/ESPN_Sports_Connection"},{"t":"Ether Vapor Remaster","p":["Windows"],"r":"September 27","l":"https://en.wikipedia.org/wiki/Nyu_Media"},{"t":"Etrian Odyssey IV","p":["Nintendo 3DS"],"d":"Atlus","u":"Atlus, Atlus USA, NIS America","g":"Role-playing, Dungeon crawler","r":"July 5, 2012","l":"https://en.wikipedia.org/wiki/Etrian_Odyssey_IV"},{"t":"Euro Truck Simulator 2","p":["Windows"],"g":"Racing, Simulator","r":"October 19","l":"https://en.wikipedia.org/wiki/Euro_Truck_Simulator_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7et5.jpg","s":"Euro Truck Simulator 2 is a vehicle simulation game and a direct sequel to the 2008 game Euro Truck Simulator. Travel across Europe as king of the road, a trucker who delivers important cargo across impressive distances! With dozens of cities to explore from the UK, Belgium, Germany, Italy, the Netherlands, Poland, and many more, your endurance, skill and speed will all be pushed to their limits. If you’ve got what it takes to be part of an elite trucking force, get behind the wheel and prove it!"},{"t":"Eve Online: Retribution","p":["Windows"],"r":"December 4","l":"https://en.wikipedia.org/wiki/Eve_Online"},{"t":"EverQuest II: Chains of Eternity","p":[],"l":"https://en.wikipedia.org/wiki/EverQuest_II:_Chains_of_Eternity"},{"t":"EverQuest: Rain of Fear","p":[],"l":"https://en.wikipedia.org/wiki/EverQuest:_Rain_of_Fear"},{"t":"Eyewire","p":["Browser"],"d":"Sebastian Seung of Princeton University","g":"Puzzle, citizen science","r":"December 10, 2012","l":"https://en.wikipedia.org/wiki/Eyewire"},{"t":"F1 2011","p":["PlayStation Vita"],"r":"February 15","l":"https://en.wikipedia.org/wiki/F1_2011_(video_game)"},{"t":"F1 2012","p":["Windows","PlayStation 3","Xbox 360","macOS"],"g":"Racing, Simulator, Sport, Strategy","r":"September 18","l":"https://en.wikipedia.org/wiki/F1_2012_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3zi4.jpg","s":"As well as the new young driver test mode, F1 2012 features a new \"Champions Mode\", in which the six World Champions competing in the 2012 season — Kimi Räikkönen, Lewis Hamilton, Jenson Button, Sebastian Vettel, Fernando Alonso and Michael Schumacher — will be styled after traditional end-of-level video gaming bosses, with the player challenged to beat them while racing in conditions that suit each driver.\nAnother new mode introduced, is the \"Season Challenge\" mode. Feedback given to Codemasters was that players only played the game when they had a few hours to play. In response, Codemasters brought in this mode so that players could simply play for a short amount of time. In this mode the player will start as a team lower down the field, and over a ten race season the player will move teams mid-season, depending on their ability to beat rival drivers and objectives.\nCodemasters also introduced \"One-Shot Qualifying\", whereby a player has a single lap to qualify for the race. The three stage knock out session is still an option, however the single 20 minute session is no longer available in career mode. There is no longer an option to include all three practice sessions in a race weekend, but instead only a single hour session is available."},{"t":"F1 Race Stars","p":["Windows","PlayStation 3","Xbox 360"],"r":"November 13","l":"https://en.wikipedia.org/wiki/F1_Race_Stars"},{"t":"Fable Heroes","p":["Xbox 360"],"r":"May 2","l":"https://en.wikipedia.org/wiki/Fable_Heroes"},{"t":"Fable: The Journey","p":["Xbox 360"],"r":"October 9"},{"t":"Fairway Solitaire","p":["Windows","macOS","iOS","Android","Windows Phone"],"d":"Big Fish Studios, Babaroga","u":"Big Fish Games","g":"Card","r":"February 15, 2012","l":"https://en.wikipedia.org/wiki/Fairway_Solitaire"},{"t":"Fairy Bloom Freesia","p":["Windows"],"r":"October 17","l":"https://en.wikipedia.org/wiki/Nyu_Media"},{"t":"Family Guy Online","p":[],"d":"Roadhouse Interactive, A.C.R.O.N.Y.M. Games","u":"20th Century Fox","g":"MMORPG","r":"April 17, 2012","l":"https://en.wikipedia.org/wiki/Family_Guy_Online"},{"t":"Family Guy: Back to the Multiverse","p":["Windows","PlayStation 3","Xbox 360"],"r":"November 20"},{"t":"Family Party: 30 Great Games Obstacle Arcade","p":["Wii U"],"r":"December 4"},{"t":"Fantasy Life","p":["Nintendo 3DS"],"d":"Level-5","u":"Nintendo, Level-5","g":"Role-playing, life simulation","r":"December 27, 2012","l":"https://en.wikipedia.org/wiki/Fantasy_Life","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob8fp.jpg","s":"Embark on the adventure of your dream life as you craft, cast, fish, mine, battle and explore like never before. With the innovative Life system, your choices don’t just upgrade characters—they help shape your journey. Explore a huge fantasy landscape beside surly dark paladins, slick pirate captains, regal princesses, and others who share your taste for the unknown."},{"t":"Far Cry 3","p":["Xbox 360","PlayStation 3","Windows"],"d":"Ubisoft Montreal","u":"Ubisoft","g":"FPS","r":"December 4, 2012","l":"https://en.wikipedia.org/wiki/Far_Cry_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1vpd.jpg","s":"Explore an island playground as stunningly beautiful as it is diverse – from mountain ranges to swampy grasslands and white sandy beaches. Fight your way through the island’s towns, temples, river ports and more.\n\nEncounter a diverse and realistic cast of characters, including one of Far Cry’s most notorious villains: Vaas Montenegro. Dive into this deep and enriching story where morals are questionable and hope is all but abandoned."},{"t":"Farming Simulator 2012","p":["Nintendo 3DS","iOS"],"d":"Giants Software, Astragon","u":"Excalibur Publishing, Focus Home Interactive, Astragon, Giants Software","g":"Simulation","r":"March 30, 2012","l":"https://en.wikipedia.org/wiki/Farming_Simulator_2012","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7ntz.jpg","s":"An installment of the popular farming simulation franchise for handhelds and mobile devices."},{"t":"Farming Simulator 2013","p":["Windows"],"d":"Giants Software","u":"Focus Home Interactive","g":"Simulation","r":"October 25, 2012","l":"https://en.wikipedia.org/wiki/Farming_Simulator_2013","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2smb.jpg","s":"Animal husbandry, crops, sales… It's up to you to manage and grow your own farm in a huge, totally new world!"},{"t":"Feed Me Oil","p":["Android"],"r":"July 3","l":"https://en.wikipedia.org/wiki/Feed_Me_Oil"},{"t":"Ferrari GT 3: World Track","p":["BlackBerry OS","Mobile phone"],"d":"Gameloft","u":"Gameloft","g":"Racing","r":"May 25, 2012","l":"https://en.wikipedia.org/wiki/Ferrari_GT_3:_World_Track"},{"t":"Fez","p":["Xbox 360"],"g":"Platform, Puzzle, Adventure, Indie","r":"April 13","l":"https://en.wikipedia.org/wiki/Fez_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rd9.jpg","s":"Gomez is a 2D creature living in a 2D world. Or is he? When the existence of a mysterious 3rd dimension is revealed to him, Gomez is sent out on a journey that will take him to the very end of time and space. Use your ability to navigate 3D structures from 4 distinct classic 2D perspectives. Explore a serene and beautiful open-ended world full of secrets, puzzles and hidden treasures. Unearth the mysteries of the past and discover the truth about reality and perception. Change your perspective and look at the world in a different way."},{"t":"Fibble","p":["iOS","Android"],"d":"Crytek Budapest","u":"Crytek","g":"Puzzle","r":"March 29, 2012","l":"https://en.wikipedia.org/wiki/Fibble"},{"t":"Fibrillation","p":["Windows"],"d":"Egor Rezenov","g":"First person, horror","l":"https://en.wikipedia.org/wiki/Fibrillation_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/vch12bixsz4oot5rs6ux.jpg","s":"Fibrillation is a first person philosophic horror with elements of mysticism for a runthrough in one breath. It is a small game with a budget of 180 USD and development time of just a little over 3 weeks. One game session takes about 40 minutes. You’ve got only one chance to play through the whole game with no savings."},{"t":"Fieldrunners 2","p":["iOS"],"r":"July 19","l":"https://en.wikipedia.org/wiki/Fieldrunners_2"},{"t":"FIFA 13","p":["Xbox 360","Windows","PlayStation 3","Wii","PlayStation Vita","PlayStation Portable","PlayStation 2","iOS"],"u":"EA Sports","r":"September 25, 2012","l":"https://en.wikipedia.org/wiki/FIFA_13"},{"t":"FIFA Football","p":["PlayStation Vita"],"r":"February 22","l":"https://en.wikipedia.org/wiki/FIFA_12"},{"t":"FIFA Online 3","p":["Windows","iOS","Android"],"d":"Electronic Arts, EA Spearhead","u":"Nexon, Tencent Games, Garena","g":"Sports","r":"December 18, 2012","l":"https://en.wikipedia.org/wiki/FIFA_Online_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5yii.jpg","s":"FIFA Online 3 is a free-to-play massively multiplayer online football game which was announced on 13 August 2012 and entered the 1st closed beta on 20 September 2012 to 23 September of that same year in South Korea. On December 18, 2012, it was released in South Korea."},{"t":"FIFA Soccer 13","p":["Wii U"],"g":"Simulator, Sport","r":"November 18","l":"https://en.wikipedia.org/wiki/FIFA_13","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co206y.jpg","s":"FIFA 13 captures the drama and unpredictability of real-world football. The game creates a true battle for possession across the entire pitch, delivers freedom and creativity in attack, and connects fans to the heartbeat of the sport - and to each other - through EA SPORTS Football Club. FIFA 13 features five breakthrough gameplay innovations which revolutionize artificial intelligence, dribbling, ball control and physical play, as well as engaging online features and live services.\n\nFIFA 13 with Kinect enables you to use voice commands to manage your club’s line-up and tactics without pausing the game, shout directions on the pitch in Be A Pro, and forces you to temper the way you talk to officials."},{"t":"FIFA Street","p":["PlayStation 3","Xbox 360"],"g":"Sport","r":"March 13","l":"https://en.wikipedia.org/wiki/FIFA_Street_(2012_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2090.jpg","s":"FIFA Street is the most authentic street football game ever created, developed by award-winning FIFA creative director Gary Paterson, and inspired by street footballers around the world."},{"t":"Fighting Vipers","p":["PlayStation Network","Xbox 360"],"r":"November 27","l":"https://en.wikipedia.org/wiki/Fighting_Vipers"},{"t":"Final Fantasy Airborne Brigade","p":["Android","iOS"],"r":"December 14","l":"https://en.wikipedia.org/wiki/Final_Fantasy_Airborne_Brigade"},{"t":"Final Fantasy Artniks","p":["Mobile phone"],"u":"Square Enix","g":"Social role-playing","r":"November 30, 2012","l":"https://en.wikipedia.org/wiki/Final_Fantasy_Artniks"},{"t":"Final Fantasy Dimensions","p":["Android","iOS"],"r":"August 31","l":"https://en.wikipedia.org/wiki/Final_Fantasy_Dimensions"},{"t":"Final Fantasy III","p":["Android","PlayStation Portable"],"r":"June 27","l":"https://en.wikipedia.org/wiki/Final_Fantasy_III"},{"t":"Final Fantasy IV","p":["iOS"],"r":"December 20","l":"https://en.wikipedia.org/wiki/Final_Fantasy_IV"},{"t":"Final Fantasy XIII-2","p":["PlayStation 3","Xbox 360"],"r":"January 31","l":"https://en.wikipedia.org/wiki/Final_Fantasy_XIII-2"},{"t":"Finding Nemo: Escape to the Big Blue Special Edition","p":["Nintendo 3DS"],"r":"September 11"},{"t":"Fire Emblem Awakening","p":["Nintendo 3DS"],"u":"Nintendo","g":"Role-playing (RPG), Strategy, Turn-based strategy (TBS), Tactical","r":"April 19, 2012","l":"https://en.wikipedia.org/wiki/Fire_Emblem_Awakening","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobcko.jpg","s":"Armies clash as the world burns. As an inevitable war draws ever closer, you must stand with Chrom and his forces--knights, mages, archers, and more--commanding them against the armies of kingdoms, empires, and the dead themselves.\n\nPlan your strategery. Move your troops on the battlefield, then choose their weapon and attack. Using the new Pair Up and Dual systems, support your attacks with the help of nearby allies and watch their skills and relationships grow."},{"t":"Fire Pro Wrestling","p":["Xbox 360"],"d":"Spike Chunsoft, Microsoft Game Studios Japan","u":"Microsoft Game Studios","g":"Sports","r":"September 21, 2012","l":"https://en.wikipedia.org/wiki/Fire_Pro_Wrestling_(2012_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2lha.jpg","s":"Your Avatar, in a game of pro-wrestling. Fire Pro Wrestling is a dream come true game that lets your Xbox 360 Avatar fight like a real wrestler. Grow your Avatar, collect moves, costume, fight your friends offline and online, you'll have plenty to do before rising to your wrestling stardom."},{"t":"Fish Heroes","p":["iOS","Android"],"d":"Craneballs Studio","g":"Arcade video game","r":"June 21, 2012","l":"https://en.wikipedia.org/wiki/Fish_Heroes"},{"t":"Five A Day","p":["iOS"],"u":"Llamasoft","g":"Multidirectional shooter","l":"https://en.wikipedia.org/wiki/Five_A_Day_(video_game)"},{"t":"Five-O Poker","p":[],"l":"https://en.wikipedia.org/wiki/Five-O_Poker"},{"t":"Flatspace","p":[],"l":"https://en.wikipedia.org/wiki/Flatspace"},{"t":"Flow Free","p":["Windows Phone","iOS","Android"],"d":"Big Duck Games LLC, Noodlecake Studios","u":"Big Duck Games LLC","g":"Puzzle","r":"June 7, 2012","l":"https://en.wikipedia.org/wiki/Flow_Free","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rmq.jpg","s":"Flow Free is a simple yet addictive puzzle game.\n\nConnect matching colors with pipe to create a Flow. Pair all colors, and cover the entire board to solve each puzzle. But watch out, pipes will break if they cross or overlap!\n\nFree play through hundreds of levels, or race against the clock in Time Trial mode. Gameplay ranges from simple and relaxed, to challenging and frenetic, and everywhere in between. How you play is up to you. So, give Flow Free a try, and experience \"mind like water\"!"},{"t":"Fluidity: Spin Cycle","p":["Nintendo 3DS"],"r":"December 27"},{"t":"Football Manager 2013","p":["Windows","macOS"],"g":"Sport, Strategy","r":"November 2","l":"https://en.wikipedia.org/wiki/Football_Manager_2013","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2k78.jpg","s":"Football Manager 2013 (often abbreviated to Football Manager 13, or more commonly FM13) is a 2012 football management simulation video game developed by Sports Interactive and published by Sega. It was released on Microsoft Windows and OS X on 2 November 2012. Football Manager Handheld 2013 was subsequently published for PlayStation Portable on 30 November, and for iOS and Android on 13 December."},{"t":"Football Manager Handheld 2013","p":["PlayStation Portable"],"r":"November 30","l":"https://en.wikipedia.org/wiki/Football_Manager_2013"},{"t":"Forge","p":["Windows"],"d":"Dark Vale Games","g":"Shooter","r":"December 4, 2012","l":"https://en.wikipedia.org/wiki/Forge_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2q6h.jpg","s":"Forge is an online, class based multiplayer shooter set in a distinct fantasy universe. Forge features only the best aspects of MMO and FPS class based combat to provide a multiplayer gameplay experience unlike anything you've played before.\n\nA malicious being named The Devourer has swallowed the great pantheon of gods. Seeking escape, the trapped gods have deceived great warriors, zealous adherents and placed them on a faceless world called FORGE, designed sacrifice the weakest of these warriors in order to grow their own power. Choosing one of five unique warrior classes, the player must battle head-to-head with other players in a bid to free their god from the clutches of The Devourer. Armed with a set of powerful and unique abilities as well as a powerful and deadly ally, each warrior must overcome the varied challenges of Forge where every kill is a sacrifice and every sacrifice brings them one step closer to freedom."},{"t":"Forge of Empires","p":["Browser","iOS","Android"],"d":"InnoGames","u":"InnoGames","g":"Strategy, citybuilding","r":"April 17, 2012","l":"https://en.wikipedia.org/wiki/Forge_of_Empires","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ngx.jpg","s":"In the browser game Forge of Empires you can build your own city and experience all of history from its perspective - from the stone age on through the centuries. Explore new technologies that ring in a new era. Leave a mark with unique, contemporary buildings and establish a gigantic metropolis that is unparalleled anywhere. Increase your empire with sophisticated strategic campaigns and skilled actions in Forge of Empires. Create your own world: Forge your Empire!\n\nThe strategy game Forge of Empires takes you through the different eras - explore new building types and technologies to continue developing your settlement. Meet the challenges of the single-player campaigns until you rule an entire continent, or compete against other players in the multiplayer mode. In the browser game Forge of Empires, dedicate yourself to research and develop more advanced battle units, innovative products and spectacular buildings. Passionate builders will have many opportunities to develop and beautify their cities in this strategy game. Good economic skills are essential in Forge of Empires to finance the growth of your empire with your residents’ tax money.\n\nBut not everything is peaceful in Forge of Empires. Fight exciting battles, use a variety of units and incorporate the individual features of the terrain in order to win. On the battle field you can either take on the computer or give other players a lesson in battle strategy. Steer the fate of your empire: Forge of Empires!"},{"t":"Forsaken World","p":["Windows"],"d":"Perfect World Entertainment","g":"MMORPG","l":"https://en.wikipedia.org/wiki/Forsaken_World","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cn2ywdklutkntndsald0.jpg","s":"Unite against the dark forces that threaten the world of Eyrda in Forsaken World. Choose between seven distinct races including the Stonemen, Elves, Dwarves, Humans, the Kindred, Lycan and Demon, each with their own in-depth narrative and history. Roam through an ever-changing land, discover an advanced guild system and immerse yourself in a dark, fantasy world."},{"t":"Fortune Street Smart","p":["iOS"],"r":"May 31"},{"t":"Forza Horizon","p":["Xbox 360"],"g":"Racing","r":"October 23","l":"https://en.wikipedia.org/wiki/Forza_Horizon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co228y.jpg","s":"Forza Horizon is an action racing game set on the epic open roads of Colorado with a thrilling music festival backdrop. Combining stunning graphics and cutting-edge music with legendary Forza authenticity and a superb collection of cars to drive, Forza Horizon is an open-world automotive playground that puts a spotlight on speed, style, and the freedom of the open road. This is where cars belong!"},{"t":"Fractured Soul","p":["Nintendo 3DS"],"r":"September 13"},{"t":"Freeze!","p":["iOS","Android"],"d":"Frozen Gun Games","u":"Frozen Gun Games","g":"Puzzle","r":"November 2012","l":"https://en.wikipedia.org/wiki/Freeze!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co48nb.jpg","s":"Freeze!\n\nIt was a wonderful day for our anonymous hero, at least until the moment when he was torn from his loved ones by a viciously sharp grappling hook.\n\nLocked in a cramped cell on a planet far, far away, our hero could give in to despair and abandon himself to his fate. But with your help he can overcome gravity, turn worlds, and even – escape!\n\nSolving the rotating, physics-based puzzles is easy; just use your finger to continuously turn the cell in both directions around our hero. Of course you also have to make clever use of the Freeze! button, which can overcome gravity. Sound simple? It is – at first...\n\nFreeze! offers completely new and yet immediately intuitive game mechanics, delightfully gloomy graphics from the internationally renowned pop-up designer and illustrator Jonas Schenk, and a very sinister soundtrack from noted Swiss electronic/trance musician Karl Lukas."},{"t":"Frog Fractions","p":["Browser"],"d":"Twinbeard Studios","g":"Edutainment","r":"October 25, 2012","l":"https://en.wikipedia.org/wiki/Frog_Fractions","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22hc.jpg","s":"Frog Fractions is a 2012 browser game developed by Twinbeard Studios, a company composed primarily of founder Jim Crawford. The game, released on October 25, 2012, has been described as a spoof of the edutainment game genre. In the game, the player begins by controlling a frog to eat bugs and defend fruit. Later on, the player may spend points on upgrades to improve their frog's abilities. The game does not actually teach the player about fractions; the player's score is given in fractions, but no knowledge of them is necessary to play."},{"t":"Frogger: Hyper Arcade Edition","p":["PlayStation Network"],"r":"July 10"},{"t":"FTL: Faster Than Light","p":["Windows","Linux","macOS"],"g":"Role-playing (RPG), Simulator, Strategy, Indie","r":"September 14","l":"https://www.igdb.com/games/ftl-faster-than-light","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9chw.jpg","s":"FTL: Faster Than Light is a single-player strategy game with roguelike design. The player commands a spaceship from a top-down view, managing systems such as weapons, engines, shields, and life support while recruiting crew and upgrading the vessel. The ship travels across procedurally generated sectors, jumping between beacons that present random events, stores, and enemy encounters. Combat plays out in real time with the option to pause and issue orders. Losing the ship or its crew ends the run and requires starting over, giving each playthrough a different layout and set of challenges."},{"t":"Fun! Fun! Minigolf TOUCH!","p":["Nintendo 3DS"],"r":"March 8","l":"https://en.wikipedia.org/wiki/Fun!_Fun!_Minigolf"},{"t":"Funky Barn","p":["Nintendo 3DS","Wii U"],"d":"Tantalus Media","u":"Ubisoft, 505 Games","g":"Simulation","r":"April 3, 2012","l":"https://en.wikipedia.org/wiki/Funky_Barn","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6uk6.jpg","s":"It’s Farming! but not as you know it... Grab your Wii U GamePad and create a beautiful farmland full of animals, crops, trees and more… then develop it into the craziest, most offbeat farm imaginable, overflowing with the whackiest contraptions and goofiest gizmos you and your animals have ever seen!"},{"t":"Gaku Ou: The Royal Seven Stars","p":[],"l":"https://en.wikipedia.org/wiki/Gaku_Ou:_The_Royal_Seven_Stars"},{"t":"Game Dev Tycoon","p":["Windows","macOS","Linux","iOS","Android"],"d":"Greenheart Games","u":"Greenheart Games","g":"Business simulation","r":"December 10, 2012","l":"https://en.wikipedia.org/wiki/Game_Dev_Tycoon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaug7.jpg","s":"In Game Dev Tycoon you replay the history of the gaming industry by starting your own video game development company in the 80s. Create best selling games. Research new technologies and invent new game types. Become the leader of the market and gain worldwide fans."},{"t":"Game of Thrones","p":["Windows","PlayStation 3","Xbox 360"],"g":"Role-playing (RPG), Adventure","r":"May 15","l":"https://en.wikipedia.org/wiki/Game_of_Thrones_(2012_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2duu.jpg","s":"Experience an amazing adventure in one of the most complete and fascinating universes in medieval-fantasy literature. Game of Thrones is a great Role Playing Game that puts you at the core of a thrilling plot, where your fate will be guided by vengeance, allegiance and honor.\n\nPlay as two very different heroes across the two main quests leading you to the heart of mythical locations from Westeros. Amidst a background of conspiracy and betrayal, try to survive the orchestrated machinations around the Iron Throne.\n\nDevelop your characters, learn powerful skills, and participate in tactical and spectacular battles; sharpen your diplomacy skills to sometimes favor speech over violence. But more than anything, beware... all your actions may have heavy consequences on your adventure!"},{"t":"Game Party Champions","p":["Wii U"],"r":"November 18","l":"https://en.wikipedia.org/wiki/Game_Party_Champions"},{"t":"Gasketball","p":["iOS"],"d":"Mikengreg","u":"Mikengreg","g":"Puzzle","r":"August 9, 2012","l":"https://en.wikipedia.org/wiki/Gasketball","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/j6l1x5kjhpnhszqqdjdt.jpg","s":"Gasketball is a shot matching basketball game similar to H.O.R.S.E. Challenge your friends online with shots of your own creation. Master over 100 single player levels in 4 unique worlds. Grab a friend and play one-on-one on the same iPad."},{"t":"Gateways","p":["Windows","macOS","Linux","iOS","Xbox 360"],"d":"Smudged Cat Games","u":"Smudged Cat Games","g":"Platform-adventure, Metroidvania","r":"September 13, 2012","l":"https://en.wikipedia.org/wiki/Gateways_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co25cn.jpg","s":"Gateways is a 2D platform game set in the lab of an inventor called Ed following an outbreak of a number of his more \"creative\" experiments. Can you help him escape the lab?\n\nAlongside the traditional platform elements such as jumping on enemies heads, spikes and moving platforms are the gateway guns. The gateway guns allow you to place two gateways on the walls, floors and ceilings of the lab so that when you pass through one you emerge out of the other. As progress is made through the game different types of gateway gun are introduced with different effects. After the basic gun, you acquire a gun that creates two gateways of different sizes, passing through one way shrinks Ed to half his size and the other way makes Ed grow to twice his size. Then you find a gun where one gateway doesn't just connect to the others location but also its time, allowing Ed to travel back in time and encounter earlier versions of himself. Finally, the last gun manipulates gravity so passing through allows Ed to walk along walls and on ceilings.\n\nGateways takes place on a single sprawling map rammed with puzzles and challenges. As power ups are acquired more and more of the map opens up containing more power ups and secrets. In addition to the gateway guns Ed will also find a torch letting him light up the darker areas of the map and a mirror which can be used to deflect lasers."},{"t":"Gemini Wars","p":["Windows","macOS"],"d":"Camel101","u":"Iceberg Interactive","g":"Real-time strategy","r":"June 8, 2012","l":"https://en.wikipedia.org/wiki/Gemini_Wars","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4183.jpg","s":"Decades have passed since war erupted between the United Space Federation and the alliance of Free Worlds. A bloody conflict that seemed to have reached a stalemate is now about to change, when a third faction suddenly appears.\n\nTake control of a fleet commander returned from exile, rise through the ranks of the United Space Federation forces and join an epic war across the stars. Start with a small group of frigates, and climb your way to controlling battleships, carriers and planetary bases, in huge space battles and boarding actions.\n\nBuild space stations and orbital facilities to fortify your position, build your fleet, extract minerals and research upgrades. Execute boarding actions using marine special forces, and bombard your enemies with orbital long range cannons."},{"t":"Gems with Friends","p":["iOS","Android"],"d":"Zynga","g":"Puzzle","r":"September 6, 2012","l":"https://en.wikipedia.org/wiki/Gems_with_Friends","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7vdc.jpg","s":"Gems with Friends is a free, tile-matching video game for mobile devices by Zynga. It's the sixth entry in Zynga's 'With Friends' series of games with a global release. The game was taken offline on March 26, 2018."},{"t":"Gene Effect","p":["iOS"],"d":"Lighstorm 3D","r":"May 2012","l":"https://en.wikipedia.org/wiki/Gene_Effect"},{"t":"Gensō Suikoden: Tsumugareshi Hyakunen no Toki","p":["PlayStation Portable"],"d":"Konami","u":"Konami","g":"Role-playing game","r":"February 9, 2012","l":"https://en.wikipedia.org/wiki/Gens%C5%8D_Suikoden:_Tsumugareshi_Hyakunen_no_Toki"},{"t":"Gerbil Physics","p":["Android","Windows Phone"],"d":"Pencel Games","u":"Microsoft Studios","g":"Puzzle","r":"March 14, 2012","l":"https://en.wikipedia.org/wiki/Gerbil_Physics"},{"t":"Gettysburg: Armored Warfare","p":["Windows"],"r":"March 27"},{"t":"Ghost Trick: Phantom Detective","p":["iOS"],"u":"Capcom","r":"February 2"},{"t":"Ghost Whisperer","p":["Windows","macOS"],"d":"Legacy Games","u":"Legacy Games","g":"Hidden object","r":"August 7, 2012","l":"https://en.wikipedia.org/wiki/Ghost_Whisperer_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/y3lpknz4tkprwcrhxjhk.jpg","s":"Ghost Whisperer consists of 2 different stories centered around the characters and themes raised in the hit television series. In Ghost Whisperer, players will take on the role of Melinda Gordon (played by Jennifer Love Hewitt on the television series) as she responds to the pleas for help from several different spirits who have unresolved issues that must be addressed before the ghosts are able to cross over to the other side. Other characters from the series (Melinda’s husband Jim, business partner and friend Delia, Delia’s son Ned, and ghost listener Eli) also play prominent roles in the game."},{"t":"Ghostbusters: Paranormal Blast","p":["iOS"],"r":"August 3"},{"t":"Giana Sisters: Twisted Dreams","p":["Windows"],"g":"Platform, Puzzle, Adventure, Indie","r":"October 23","l":"https://www.igdb.com/games/giana-sisters-twisted-dreams","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2iqi.jpg","s":"Giana Sisters: Twisted Dreams is a blistering hardcore platformer with contrasting worlds. Warp Giana’s vivid dreams to alter your abilities and destroy the twisted creatures lurking within. Giana Sisters: Twisted Dreams combines the challenge of retro era platforming with graphics that pack a visual punch and tight controls.\n\nFluidly morph between two dynamically different dream worlds to solve puzzles and combat grueling enemies. Players will have to intertwine sweet Giana's twirling jump attack with Punk Giana's hammering dash attack to survive the dualling dimensions."},{"t":"Girl Friend Beta","p":["Android","iOS"],"g":"Simulator","l":"https://en.wikipedia.org/wiki/Girl_Friend_Beta","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co60r8.jpg","s":"Girl Friend Beta is a Japanese smartphone dating simulator. It features over 100 different virtual girls, each with a unique voice actress. The player progresses their relationship with the virtual girlfriend by taking her on dates. The game is free-to-play, however the player pays real-world money to gain premium services. The game features various events that occur, including battle events when bad guys appear. The player can engage in club activities and school class events to solicit romance and increase intimacy with female students. There is a card-based system within the game, where the player collects different cards of varying rarity; each card has different attributes, such as attack and defense costs. Cards can be enhanced by engaging in a part-time job."},{"t":"Girls Like Robots","p":["Windows","macOS","Linux","iOS"],"d":"Popcannibal","u":"Adult Swim, Popcannibal, Unity Japan","g":"Puzzle","r":"October 11, 2012","l":"https://en.wikipedia.org/wiki/Girls_Like_Robots","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wo9.jpg","s":"Their faces are the playing pieces. The rules are their emotions!\n\nRidiculously charming puzzles, wrapped around an epic tale of love and danger, topped off with an authentic old-time stringband soundtrack!\n\nThe goal is to put every one next to their friends.\n\nBut you can't please everybody all the time. Sometimes you gotta break hearts to save the day. And the day definitely needs saving: Volcanoes, exploding chickens, planetary invasion and a boy who just wants to dance with a girl."},{"t":"God of Blades","p":["Android","iOS","Ouya","macOS","Windows"],"d":"White Whale Games","g":"Side-scroller","r":"September 27, 2012","l":"https://en.wikipedia.org/wiki/God_of_Blades","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/e96xfjwshvae8pt1fhfy.jpg","s":"Multi-platform physics-based sword-fighting action-adventure."},{"t":"God of War Saga","p":["PlayStation 3"],"r":"August 28","l":"https://en.wikipedia.org/wiki/God_of_War_Saga"},{"t":"Gon: Baku Baku Baku Baku Adventure","p":["Nintendo 3DS"],"d":"Inti Creates","u":"Namco Bandai Games","g":"Action-adventure, platformer","r":"June 14, 2012","l":"https://en.wikipedia.org/wiki/Gon:_Baku_Baku_Baku_Baku_Adventure"},{"t":"Gotham City Impostors","p":["Windows","PlayStation Network","Xbox 360"],"g":"Shooter","r":"February 7","l":"https://en.wikipedia.org/wiki/Gotham_City_Impostors","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2jhq.jpg","s":"Gotham City Impostors is a first-person shooter multiplayer-only video game set in the universe of DC Comics' Batman. Developed by Monolith Productions and published by Warner Bros. Interactive Entertainment, the downloadable game is played from the perspective of two teams each trying to kill the other: one with people dressed like Batman and the other with people dressed like his archenemy, The Joker. The game is a six versus six first-person shooter multiplayer game featuring customizable characters. Players take on the role of either amateur vigilantes (the Bats) or villains (the Jokerz). The game features a range of both traditional and imagined weapons."},{"t":"Grand Slam Tennis 2","p":["PlayStation 3","Xbox 360"],"r":"February 14","l":"https://en.wikipedia.org/wiki/Grand_Slam_Tennis_2"},{"t":"Grand Theft Auto III","p":["PlayStation Network"],"r":"September 25","l":"https://en.wikipedia.org/wiki/Grand_Theft_Auto_III"},{"t":"Grand Theft Auto: San Andreas","p":["PlayStation Network"],"r":"December 11"},{"t":"Grand Theft Auto: Vice City 10th Anniversary Edition","p":["iOS","Android"],"r":"December 6"},{"t":"Granny Smith","p":["Android","iOS"],"d":"Mediocre","u":"Mediocre","g":"Platformer","r":"August 30, 2012","l":"https://en.wikipedia.org/wiki/Granny_Smith_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6qci.jpg","s":"Granny Smith is a fast-paced racing platformer filled with spectacular crashes and amazing stunts. Jump, glide, swing and smash your way through 57 hand-crafted levels in four distinct settings. Just be sure to land on your feet!"},{"t":"Gravity Rush","p":["PlayStation Vita"],"g":"Role-playing (RPG), Adventure","r":"June 12","l":"https://en.wikipedia.org/wiki/Gravity_Rush","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5tgy.jpg","s":"Gain a new perspective as you take on the role of Kat, a strong-willed girl seeking the means to protect her future in a world that’s crumbling to pieces. Tilt and move the PlayStation Vita System, taking gravity into your own hands to deliver devastating attacks, uncover the secrets to your past and explore a mysterious world."},{"t":"Great Big War Game","p":["Android","iOS","Windows"],"d":"Rubicon Developments","u":"Rubicon Developments","g":"Turn-based strategy","r":"July 18, 2012","l":"https://en.wikipedia.org/wiki/Great_Big_War_Game","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/mngib3qfswmj1rubbnlm.jpg","s":"Taking military \"advice\" from the ridiculous generalissimo, can you battle your way through this truly massive, content-packed military campaign? Plan your missions, deploy your forces, try not to fall off the sofa laughing! You've plenty of units to play with, covering land, sea and airborne combat. Be warned though, these funny cartoon troops are not exactly the right stuff."},{"t":"Grezzo 2","p":["Windows"],"d":"Giochi Penosi","g":"First-person shooter","l":"https://en.wikipedia.org/wiki/Grezzo_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3p7e.jpg","s":"Grezzo 2 is a first-person shooter video game developed by Italian game designer Nicola Piro and released in 2012. The game is a total conversion modification of the 1993 video game Doom and its development began in the early 2000s, with the version called Grezzo 1, when Nicola Piro attended high school.\n\nThe plot follows the adventure of pagan farmer Piro which, annoyed and disgusted by Christianity, plans to kill Jesus Christ to prevent the rise of his religious phenomenon. Gameplay requires the player to face various levels, defeating enemies and bosses and using a wide range of weapons. Many well-known personalities of the culture of Italy appear in the game, as well as references to extremely satirized social, political and religious issues of the country.\n\nFollowing the 2012 release, Grezzo 2 received significant attention, both inside and outside of its country of origin, due to its extremely blasphemous, vulgar and violent content."},{"t":"Gridrunner iOS","p":["iOS"],"r":"February 24","l":"https://en.wikipedia.org/wiki/Gridrunner_iOS"},{"t":"Groove Coaster Zero","p":["iOS"],"r":"November 20","l":"https://en.wikipedia.org/wiki/Groove_Coaster"},{"t":"Growlanser Wayfarer of Time","p":["PlayStation Portable"],"r":"July 31","l":"https://en.wikipedia.org/wiki/Growlanser_Wayfarer_of_Time"},{"t":"Guardian Cross","p":["iOS"],"d":"Square Enix","u":"Square Enix","g":"Card Game, role-playing game","r":"September 13, 2012","l":"https://en.wikipedia.org/wiki/Guardian_Cross","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9jxc.jpg","s":"A fantasy card battle game for iOS and Android."},{"t":"Guardians of Middle-earth","p":["PlayStation Network","Xbox 360"],"r":"December 4","l":"https://en.wikipedia.org/wiki/Guardians_of_Middle-earth"},{"t":"Guild Wars 2","p":["Windows"],"u":"NCsoft","g":"Adventure, Massively Multiplayer, RPG, Free To Play","r":"August 28, 2012","l":"https://en.wikipedia.org/wiki/Guild_Wars_2","i":"images/steam-1284210.jpg","s":"Guild Wars 2 is an award-winning online roleplaying game with fast-paced action combat, deep character customization, and no subscription fee required. Choose from an arsenal of professions and weapons, explore a vast open world, compete in PVP modes and more. Join over 16 million players now!"},{"t":"Guilty Gear XX Accent Core Plus","p":["Xbox 360"],"r":"October 24","l":"https://en.wikipedia.org/wiki/Guilty_Gear_X2_updated_versions#Guilty_Gear_XX_Accent_Core_Plus"},{"t":"Guilty Gear XX Accent Core Plus R","p":["Arcade"],"d":"Arc System Works","u":"Arc System Works","g":"Fighting, Arcade","r":"September 20, 2012","l":"https://www.igdb.com/games/guilty-gear-xx-accent-core-plus-r","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2h0r.jpg","s":"Ultimate battle action, and the epitome of the GUILTY GEAR XX series now on Steam!\nBonus soundtracks included!"},{"t":"Guilty Gear XX Λ Core Plus","p":["PlayStation Network"],"r":"December 4","l":"https://en.wikipedia.org/wiki/Guilty_Gear_XX#Λ_Core_Plus"},{"t":"Gungnir","p":["PlayStation Portable"],"r":"June 12","l":"https://en.wikipedia.org/wiki/Gungnir_(video_game)"},{"t":"Gunlord","p":["Dreamcast","Neo Geo AES","PlayStation 4"],"d":"NG:Dev.Team","u":"NG:Dev.Team","g":"Run and gun","r":"March 26, 2012","l":"https://en.wikipedia.org/wiki/Gunlord","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/r4k1r7tuwyakl7jkydd4.jpg","s":"After the space pilot Vanessa Gaiden defeated the Evil Empire in the events of the game Last Hope, she got missing on her way back and wasn't heard of anymore. Vanessa's husband, Gordian Gaiden, sets out to search for her. Meanwhile, a new evil has appeared in the galaxy: a planet lord called \"The Master\", who can create and control evil beings made of steel, and uses his power to terrorize the galaxy. On his search, Gordian comes across the evil presence of The Master and sets out in his Gunlord suit for the planet Kairos II."},{"t":"Guns of Icarus Online","p":["Windows","macOS"],"g":"Shooter, Simulator, Tactical, Adventure, Indie","r":"October 29","l":"https://en.wikipedia.org/wiki/Guns_of_Icarus#Guns_of_Icarus_Online","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2smn.jpg","s":"Guns of Icarus Online is a team-based multiplayer online airship combat game. Captain or serve as crew aboard an airship with your friends and fly into battle against other ships in a steam/dieselpunk-inspired, post-apocalyptic world. Each player takes on one of the three roles aboard the ship—Captain, Gunner, or Engineer—and must work together to take down enemies and keep the ship flying. The game is all about teamwork, tactics, and fast-paced action."},{"t":"Haganai","p":[],"l":"https://en.wikipedia.org/wiki/Haganai"},{"t":"Half-Minute Hero","p":["Windows"],"r":"September 27","l":"https://en.wikipedia.org/wiki/Half-Minute_Hero"},{"t":"Halo 4","p":["Xbox 360"],"g":"Shooter","r":"November 6","l":"https://en.wikipedia.org/wiki/Halo_4","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1xhf.jpg","s":"Halo 4 marks the start of an epic new saga within the award-winning Halo universe. The Master Chief returns in this award-winning first-person shooter developed by 343 Industries. Shipwrecked on a mysterious world, faced with new enemies and deadly technology, the Chief returns to battle against an ancient evil bent on vengeance and annihilation...the universe will never be the same."},{"t":"Hana Awase","p":[],"l":"https://en.wikipedia.org/wiki/Hana_Awase"},{"t":"Happy Wars","p":["Xbox 360"],"d":"Toylogic","u":"Toylogic","g":"Action, tactical role-playing","r":"October 7, 2012","l":"https://en.wikipedia.org/wiki/Happy_Wars","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2smp.jpg","s":"Happy Wars is an action-packed massive online multiplayer game where you can play together with as many as 30 players in one online session. And, it’s free-to-play. Team up with players all over the world and go crazy in wacky melees in a fantastic realm of heated sieges and big magical battles. Get premium items of beautiful graphic quality through Happy Cards and other means to power up your character. Charge through battlefields with your own personalized character."},{"t":"Harry Potter for Kinect","p":["Xbox 360"],"d":"Eurocom","u":"Warner Bros. Interactive Entertainment","g":"Action","r":"October 9, 2012","l":"https://en.wikipedia.org/wiki/Harry_Potter_for_Kinect","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20e9.jpg","s":"For the first time, create a witch or wizard character in your likeness that will become part of the gameplay through Kinect's scanning technology.\nExperience unforgettable moments from all eight films - from having your wand choose you at Ollivanders and being Sorted as a first-year student at Hogwarts, to battling You-Know-Who in a climactic wizard battle\nCast spells at your opponents by performing the proper casting maneuvers and calling out spell names utilizing Kinect's controller-free and voice recognition capabilities.\nHone your casting, brewing and duelling skills (among others) in class to unlock even more lessons and challenges\nChallenge a friend in competitive mini-games, or join forces against a mutual opponent in co-op games."},{"t":"Harvest Moon 3D: A New Beginning","p":["Nintendo 3DS"],"d":"Marvelous AQL","u":"Marvelous AQL, Natsume Inc., Marvelous Europe","g":"Farming simulation, role-playing game","r":"February 23, 2012","l":"https://en.wikipedia.org/wiki/Harvest_Moon_3D:_A_New_Beginning","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2xkq.jpg","s":"Harvest Moon: A New Beginning is a farming simulation game for the Nintendo 3DS video game console. As the new farmer in town, it is your job to use your farm and its resources to revitalize a once-popular town. You can grow crops and raise animals, as well as interact with villagers and possibly get married."},{"t":"Harvest Moon: A New Beginning","p":["Nintendo 3DS"],"r":"November 6"},{"t":"Hatoful Boyfriend: Holiday Star","p":["Windows"],"r":"December 25"},{"t":"Hatsune Miku and Future Stars: Project Mirai","p":["Nintendo 3DS"],"d":"Sega","u":"Sega","g":"Rhythm game","r":"March 8, 2012","l":"https://en.wikipedia.org/wiki/Hatsune_Miku_and_Future_Stars:_Project_Mirai","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ty8.jpg","s":"Hatsune Miku and Future Stars: Project Mirai is a rhythm game and a spin-off of the Hatsune Miku: Project DIVA series of Vocaloid rhythm games. Like the original the game primarily makes use of Vocaloids, a series of singing synthesizer software, and the songs created using these vocaloids most notably the virtual-diva Vocaloid Hatsune Miku. The game features different character designs than the main games and the characters appear as their Nendoroid-style, Super deformed versions. For the game's primary gameplay, its music mode, it uses what it calls the \"Chance Circle System\". Buttons will appear around the border of a circle, and a pointer will appear from the center of the circle extending all the way outside the circle's border. It will then turn in a clockwise or counter-clockwise manner according to the song and when the pointer passes the button, the player has to press the face button on the 3DS. Similar to the series, the player's time accuracy will also be rated on a similar scale and manner that will be displayed on the bottom of the screen. In addition the game does not feature the Edit Mode of the Project DIVA series, while the DIVA Room Mode is replaced by the game's My Room mode whereby players similarly get to interact with their modules in a room."},{"t":"Hatsuyuki Sakura","p":["Windows"],"g":"Simulator, Adventure, Visual Novel","l":"https://en.wikipedia.org/wiki/Hatsuyuki_Sakura","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobwta.jpg","s":"The original 18+ version of the visual novel released on PC in Japan.\nPart of the developers Four Seasons series of Visual novels that also had manga and light novel adaptions based on them."},{"t":"Haunt","p":["Xbox 360"],"r":"January 18","l":"https://en.wikipedia.org/wiki/Haunt_(video_game)"},{"t":"Haunting at Cliffhouse","p":["Windows"],"d":"Cindy Pondillo","g":"PCA","r":"October 14","l":"https://en.wikipedia.org/wiki/Haunting_at_Cliffhouse"},{"t":"Hawken","p":["Windows"],"d":"Adhesive Games, Hawken Entertainment, Inc.","u":"Meteor Entertainment, 505 Games","g":"Vehicular combat, first-person shooter","r":"December 12, 2012","l":"https://en.wikipedia.org/wiki/Hawken_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wmg.jpg","s":"War is a Machine Pilot hulking death machines and use massive weaponry to destroy your foes in fast-paced FPS gameplay.\n\nHawken is a multiplayer first person shooter that places you inside a mechanized war machine on the battlefield of a dystopian world. With tactical, fast-paced gameplay in customizable and upgradable mechs across multiple competitive modes, Hawken is explosively fun."},{"t":"Hay Day","p":["Android","iOS"],"d":"Supercell","u":"Supercell","g":"Simulation","r":"June 21, 2012","l":"https://en.wikipedia.org/wiki/Hay_Day","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2hxl.jpg","s":"Hay Day is a totally new farming experience with smooth gestural controls lovingly handcrafted for your Android and iOS devices."},{"t":"He-Man: The Most Powerful Game in the Universe","p":["iOS"],"r":"October 25"},{"t":"Hell Yeah! Wrath of the Dead Rabbit","p":["PlayStation Network","Xbox 360","Windows"],"g":"Platform, Puzzle, Strategy, Quiz/Trivia, Adventure, Arcade","r":"September 25","l":"https://en.wikipedia.org/wiki/Hell_Yeah!_Wrath_of_the_Dead_Rabbit","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2fd3.jpg","s":"Ash, a skeletal rabbit and the prince of Hell, has inherited the role of ruler of Hell from his father. After a photographer takes a picture of Ash playing with a rubber duck in the bathtub, Ash sets out to kill the 100 monsters that have seen the photo, to restore his image. The world of Hell Yeah! Wrath of the Dead Rabbit has several zones with different visual styles, including \"haunted caves, science labs, casinos and spaceships full of talking animals\". The player navigates these zones by traveling on a large buzz-saw-like circular blade that can cut through the environment, can fire a variety of projectile weapons, and is equipped with a jetpack. Ash is assisted in his quest by his butler, Nestor, a top hat-wearing Octopus."},{"t":"Hero of the Kingdom","p":["Windows"],"d":"Lonely Troops","u":"Lonely Troops","g":"Point-and-click, Role-playing (RPG), Adventure, Indie","r":"December 20, 2012","l":"https://www.igdb.com/games/hero-of-the-kingdom","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1xnx.jpg","s":"Hero of the Kingdom is casual role-playing game at its best; take to the road and explore a vast and beautiful country full of danger and surprises. Meet and interact with characters to gain knowledge and insight giving you valuable clues. Defend against and attack the enemy, and take it upon yourself to complete quests of varying difficulty. To survive, you must find ways to earn gold by mastering your skills and bartering. You can even collect herbs, hunt for animals, and go fishing."},{"t":"Heroes of Ruin","p":["Nintendo 3DS"],"r":"June 17","l":"https://en.wikipedia.org/wiki/Heroes_of_Ruin"},{"t":"Heroes Phantasia","p":["PlayStation Portable"],"d":"Witchcraft","u":"Bandai Namco Games","g":"Role-playing","r":"January 19, 2012","l":"https://en.wikipedia.org/wiki/Heroes_Phantasia","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4n2e.jpg","s":"Heroes Phantasia is a game released for the PlayStation Portable, where the player can control a great variety of characters from 10 different anime series of the last 10 years, as well as some original characters."},{"t":"Hidden Chronicles","p":["Facebook"],"d":"Zynga","g":"Hidden Object Social Game","l":"https://en.wikipedia.org/wiki/Hidden_Chronicles"},{"t":"Hidden Runaway","p":["iOS","Windows"],"d":"Pendulo Studios","u":"BulkyPix","g":"Hidden object","r":"October 18, 2012","l":"https://en.wikipedia.org/wiki/Hidden_Runaway","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocsxa.jpg","s":"Play once again as the two mythics heroes of the Runaway series !For the 10th anniversary of the mythic, million-selling PC adventure game Runaway: a Road Adventure, Pendulo Studios, in association with BulkyPix, proudly presents Hidden Runaway, a brand-new episode starring Brian and Gina.Our two heroes no longer live together -- in fact, they hate each other… but they have to tell the story of their first adventure, from the very first time they met, to a producer who wants to make a Hollywood blockbuster out of it.Will Gina and Brian realize they still have feelings for each other while reliving their first encounter?"},{"t":"Hill Climb Racing","p":["Android","iOS"],"d":"Fingersoft","u":"Fingersoft","g":"Racing","r":"September 22, 2012","l":"https://en.wikipedia.org/wiki/Hill_Climb_Racing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co69yv.jpg","s":"A 2D physics-based racing game where players control a driver named Bill Newton across hilly terrains using simple gas and brake controls. The goal is to travel as far as possible through progressively difficult stages while collecting coins for vehicle upgrades and managing a limited fuel supply. While airborne, the controls rotate the vehicle, allowing players to perform stunts for bonus coins. The game features a variety of unlockable vehicles and stages, and uses a freemium model. Its success led to a sequel in 2016, and the franchise surpassed one billion downloads in 2018."},{"t":"History Legends of War: Patton","p":["PlayStation 3","Xbox 360","Windows"],"r":"November 6"},{"t":"Hitman: Absolution","p":["Windows","PlayStation 3","Xbox 360"],"g":"Shooter, Tactical, Adventure","r":"November 20","l":"https://www.igdb.com/games/hitman-absolution","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qrc.jpg","s":"Hitman: Absolution follows the Original Assassin undertaking his most personal contract to date. Betrayed by the Agency and hunted by the police, Agent 47 finds himself pursuing redemption in a corrupt and twisted world.\n\nShowcasing Io-Interactive’s new proprietary Glacier 2 technology, the game has been built from the ground up, boasting a cinematic story, distinctive art direction and highly original game design, Hitman Absolution combines much loved classic gameplay with completely new gameplay features for the Hitman franchise."},{"t":"Hitman: Sniper Challenge","p":["Windows","PlayStation 3","Xbox 360"],"d":"IO Interactive","u":"Square Enix, Feral Interactive","g":"Shooter, Tactical","r":"May 15, 2012","l":"https://www.igdb.com/games/hitman-sniper-challenge","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co42hs.jpg","s":"Get ready to pull the trigger on a completely new chapter in the award-winning Hitman series.\n\nBe the ultimate assassin in the Hitman Sniper Challenge by testing your reactions, focus and skill in a stand-alone hit available only for Hitman Absolution pre-purchases. Unlock weapons and upgrades that can be carried over into Hitman: Absolution and compare your scores with other players around the globe using online leaderboards.\n\nHitman: Sniper Challenge is a stand alone preview for Hitman: Absolution, which was exclusive to copies pre-ordered from GameStop or Steam. Now, it comes with the standard retail copy of Hitman HD Trilogy and the Hitman Collection on Steam, or if the Hitman: Absolution - Elite Edition is bought."},{"t":"Home","p":["Windows"],"g":"Puzzle, Adventure, Indie, Visual Novel","r":"June 1","l":"https://www.igdb.com/games/home","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1mhv.jpg","s":"Home is a unique horror adventure set in a beautifully-realized pixel world. It’s a murder mystery with a twist—because you decide what ultimately happens."},{"t":"Horn","p":["iOS","Android"],"d":"Phosphor Studios","u":"Zynga","r":"August 16, 2012","l":"https://en.wikipedia.org/wiki/Horn_(video_game)"},{"t":"Hot Shots Golf: World Invitational","p":["PlayStation Vita"],"r":"February 22","l":"https://en.wikipedia.org/wiki/Everybody%27s_Golf_6"},{"t":"Hotel Transylvania","p":["Nintendo 3DS","Nintendo DS"],"r":"September 18","l":"https://en.wikipedia.org/wiki/Hotel_Transylvania"},{"t":"Hotline Miami","p":["Windows"],"g":"Shooter, Indie, Arcade","r":"October 23","l":"https://en.wikipedia.org/wiki/Hotline_Miami","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1vqp.jpg","s":"A top-down slasher/shooter with unlockable gameplay-altering masks and weapons, featuring a neon-flavoured electronic aesthetic, in which a hitman receives anonymous calls ordering him to travel to certain residences and crime dens and massacre those within, as he stumbles through unreal visions and inconsistencies without any answers to how, why or who."},{"t":"Howling Dogs","p":["Browser"],"g":"Adventure","l":"https://en.wikipedia.org/wiki/Howling_Dogs","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4qta.jpg","s":"Howling Dogs is an interactive fiction made in TWINE by Porpentine. Trapped in a small area with limited supplies, the player can temporarily visit other worlds through some sort of virtual reality visor."},{"t":"Hugo Troll Race","p":["Android","iOS","Windows","Windows Phone"],"d":"Hugo Games","u":"Krea Medie, Software Pyramide","g":"Endless runner","r":"July 10, 2012","l":"https://en.wikipedia.org/wiki/Hugo_Troll_Race"},{"t":"Hungry Giraffe","p":["iOS"],"r":"November 14","l":"https://en.wikipedia.org/wiki/Hungry_Giraffe"},{"t":"Hungry Shark Evolution","p":["Android","iOS"],"d":"Future Games of London","u":"Ubisoft Entertainment","g":"Arcade","r":"October 24, 2012","l":"https://www.igdb.com/games/hungry-shark-evolution","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3w1b.jpg","s":"A game for tablets and smartphones where you experience life as a shark, earning money and a high score by eating fish and unaware swimmers and creating combo chains."},{"t":"Hustle Kings","p":["PlayStation Vita"],"r":"February 22","l":"https://en.wikipedia.org/wiki/Hustle_Kings"},{"t":"Hybrid","p":["Xbox 360"],"r":"August 8","l":"https://en.wikipedia.org/wiki/Hybrid_(video_game)"},{"t":"Hyperdimension Neptunia Mk2","p":["PlayStation 3"],"r":"February 28","l":"https://en.wikipedia.org/wiki/Hyperdimension_Neptunia_Mk2"},{"t":"I Am Alive","p":["Xbox 360","PlayStation Network","Windows"],"g":"Platform, Adventure","r":"March 7","l":"https://en.wikipedia.org/wiki/I_Am_Alive","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2sn0.jpg","s":"I Am Alive casts the player as a lone survivor in a believable, dark and insecure post-apocalyptic world. One year after the Event, a worldwide cataclysmic event that wiped most of the human race, a man struggles for survival in a desolate city as he tries to reunite with his long-lost wife and daughter."},{"t":"I Get This Call Every Day","p":["Windows","macOS"],"r":"December 21","l":"https://en.wikipedia.org/wiki/I_Get_This_Call_Every_Day"},{"t":"Ib","p":["Windows"],"g":"Puzzle, Adventure, Indie","r":"February 27","l":"https://en.wikipedia.org/wiki/Ib_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7gy2.jpg","s":"Ib is a freeware adventure video game with elements of psychological horror released in 2012 for Microsoft Windows by the Japanese artist kouri, running on RPG Maker 2000. Players control the titular character from a top-down perspective with the goal of escaping an eldritch art museum.\n\nThe game has been credited with helping popularize its engine's use in developing games without role-playing elements."},{"t":"Ice Age: Continental Drift – Arctic Games","p":["Nintendo 3DS","Nintendo DS","PlayStation 3","Wii","Windows","Xbox 360"],"d":"Behaviour Interactive","u":"Activision Publishing","g":"Action-adventure","r":"June 29, 2012","l":"https://en.wikipedia.org/wiki/Ice_Age:_Continental_Drift_%E2%80%93_Arctic_Games"},{"t":"Ico","p":["PlayStation 3"],"d":"Team Ico","u":"Sony Computer Entertainment","g":"Platform, Puzzle, Adventure","r":"January 12, 2012","l":"https://www.igdb.com/games/ico--1","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7221.jpg","s":"Experience the wonder and magic of one of the most beloved video games of all time, now available with full HD graphics, 7.1 surround sound, and stereoscopic 3D support.\n\nA young boy is locked away deep in a castle after horns started growing out of his head. After breaking free from his confines, he rescues a mysterious girl from her cage. Together they must escape the dangers of the castle and fend off the shadow creatures haunting their every move.\n\nICO is a harrowing and emotional adventure unlike any other. Experience one of the most highly acclaimed video games of all time."},{"t":"If My Heart Had Wings","p":["Windows"],"d":"Pulltop","u":"Pulltop, Mages., MoeNovel","g":"Visual novel","r":"May 25, 2012","l":"https://en.wikipedia.org/wiki/If_My_Heart_Had_Wings_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co43hn.jpg","s":"This game is an animated visual novel based on a youthful, dream filled high school life story. This game portrays the player as Aoi, the protagonist, and brings the player through the feat of building the glider that will realise their dreams, while bonding with the female characters."},{"t":"Ima Sugu Oniichan ni Imōto da tte Iitai!","p":[],"l":"https://en.wikipedia.org/wiki/Ima_Sugu_Oniichan_ni_Im%C5%8Dto_da_tte_Iitai!"},{"t":"Imscared","p":["Windows","Android"],"d":"Ivan Zanotti","u":"Ivan Zanotti's MyMadnessWorks","g":"Horror, Adventure","r":"October 12, 2012","l":"https://en.wikipedia.org/wiki/Imscared"},{"t":"Inazuma Eleven GO 2: Chrono Stone","p":["Nintendo 3DS"],"d":"Level-5","u":"Level-5, Nintendo","g":"Role-playing, sports","r":"December 13, 2012","l":"https://en.wikipedia.org/wiki/Inazuma_Eleven_GO_2:_Chrono_Stone"},{"t":"Incoboto","p":["iOS"],"d":"Fluttermind","u":"Fluttermind","g":"Puzzle, platformer","r":"March 1, 2012","l":"https://en.wikipedia.org/wiki/Incoboto"},{"t":"Incredipede","p":["Windows","macOS","Android","iOS","Browser"],"g":"Puzzle","r":"October 25, 2012","l":"https://en.wikipedia.org/wiki/Incredipede","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1tz4.jpg","s":"Incredipede is a puzzle game that celebrates the vast diversity of life in the world. The game follows Quozzle, a lone Incredipede on a quest to rescue her sisters. She has a unique ability to grow new arms and legs wherever she needs them, transforming into a snake, a spider, a horse, a monkey - anything you can imagine. You can give her antlers or a tail, use nature as a blueprint or strike out in weird new directions. Control Quozzle as she learns to swing through the trees, climb sheer cliffs, dance over rivers of lava, and even soar through the air on thermal winds.\n\nIncredipede was made by a small team headed by Colin Northway, author of Fantastic Contraption. It was written while traveling in over a dozen countries including Honduras, Turkey, Japan, and Costa Rica."},{"t":"Indestructible","p":["iOS","Android"],"d":"Glu Mobile","g":"Vehicular combat","l":"https://en.wikipedia.org/wiki/Indestructible_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9ugm.jpg","s":"Grab the wheel, load up your guns, hit the road and leave the mangled wrecks of your victories in the dust as you battle to become the best in the exciting vehicular combat game Indestructible!\n\nAre you sick of all those boring, repetitive farming games? Then blow some %^&* up in this fully 3D, online multiplayer action game!"},{"t":"Infamous Collection","p":[],"l":"https://en.wikipedia.org/wiki/Infamous_Collection"},{"t":"Infestation: Survivor Stories","p":["Windows"],"d":"Hammerpoint Interactive","u":"OP Productions","g":"Survival horror","r":"December 17, 2012","l":"https://en.wikipedia.org/wiki/Infestation:_Survivor_Stories","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co92a8.jpg","s":"Infestation: Survivor Stories is a zombie survival horror MMO. Based five years in the future following a horrendous viral outbreak of apocalyptic proportions that destroyed 95% of the world’s population, you must survive against all odds. Scavenge, defend yourself, band with others, or die in the process – your life is in your own hands."},{"t":"Insanely Twisted Shadow Planet","p":["Windows"],"r":"April 17","l":"https://en.wikipedia.org/wiki/Insanely_Twisted_Shadow_Planet"},{"t":"Into the Dead","p":["iOS"],"d":"PikPok","u":"PikPok","g":"Survival horror","r":"December 6, 2012","l":"https://en.wikipedia.org/wiki/Into_the_Dead","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coa299.jpg","s":"In a world overrun with the Dead, you have survived… but for how long?\n\nIn a world overrun with the Dead, you have survived… but for how long?\n\nInto the Dead throws you into the gruesome world of the zombie apocalypse where there are no second chances. Do what you have to in order to stay alive, keep moving as fast as you can, and protect yourself by any means necessary. When the Dead are rising, run!"},{"t":"Inversion","p":["PlayStation 3","Xbox 360","Windows"],"g":"Shooter","r":"June 5","l":"https://en.wikipedia.org/wiki/Inversion_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co28gf.jpg","s":"Inversion is a third-person co-op shooter that combines hard-hitting, adrenaline-pumping action with a revolutionary gravity manipulation engine. Featuring the Grappler weapon, players will be able to manipulate gravity for their own purposes."},{"t":"Iron Brigade","p":["Windows"],"r":"August 13","l":"https://en.wikipedia.org/wiki/Iron_Brigade_(video_game)"},{"t":"Iron Front: Liberation 1944","p":["Windows"],"d":"X1 Software, AWAR","u":"Deep Silver","g":"Tactical shooter","r":"May 25, 2012","l":"https://en.wikipedia.org/wiki/Iron_Front:_Liberation_1944","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4gvj.jpg","s":"Command your own troops, man authentic weaponry and take to the sky in deadly warplanes."},{"t":"Iron Sky: Invasion","p":["Android","macOS","Windows","PlayStation 3","Xbox 360"],"d":"Reality Pump","u":"TopWare Interactive","g":"Space simulation","r":"December 12, 2012","l":"https://en.wikipedia.org/wiki/Iron_Sky:_Invasion","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2duj.jpg","s":"“Iron Sky: Invasion” is a space fighter simulator, calling to mind such classics as the legendary... You-Know-Which series - further enhanced with strategy and RPG elements. The core of the gameplay is based on ship-to-ship dogfights, combined with assaults on giant spaceships (such as the Siegfried-Class Zeppelins), as well as tactical thinking and resource management.\n\nThe game is set in outer space, where the players must defend the Earth from the invasion of the Moon Nazis. The players control spaceships to freely roam the space and attack Nazi vessels; various weapons and equipment are at their disposal, from laser cannons and missiles to handy drones and satellites which can be launched from certain ships. The vessels are also equipped with military countermeasures, to protect them from enemy fire.\n\nThe players can access a tactical map of outer space to spot the positions of Nazi forces or any ongoing battles, and thus instantly know where to fly. The ultimate goal is to destroy the secret Nazi base hidden on the Dark Side of the Moon and to keep the Earth safe from the invading spacecraft.\n\nBeing based on the cult movie, the “Iron Sky: Invasion” comes with a touch of politics as well: various nations will offer unique missions, yet to accept or refuse them is up to the player. Some missions tempt the players with special rewards, such as precious upgrades or even brand new ships.\n\nThe players can dock at an allied space station to recharge weapons, purchase upgrades or even switch ships. Almost all spaceships that appear in the film can be controlled in game (except for the largest one), including the South-Korean scout ship “Zerg”, the Australian bomber “Dundee”, or the UK fighter “Spitfire”. The availability of some will depend on the completion of certain missions.\n\nThe ships’ sub-systems can be further upgrade in the hangar: for example, upgrading the offensive systems will increase the number of weapons and boost their power, while an engine upgrade will improve the ship’s speed and range of interception. Upgrades require special resources, which can be scavenged from destroyed enemy units or found in outer space."},{"t":"IT Manager: Duels","p":[],"d":"Intel","u":"Intel","g":"Strategy","r":"July 2012","l":"https://en.wikipedia.org/wiki/IT_Manager:_Duels"},{"t":"J.U.L.I.A.","p":["Windows","macOS","Linux"],"d":"CBE Software","u":"Lace International","g":"Adventure, puzzle","r":"March 2, 2012","l":"https://en.wikipedia.org/wiki/J.U.L.I.A.","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobmx1.jpg","s":"This game was later remade though a crowdfunding effort and released under the title \"J.U.L.I.A.: Among the Stars\"."},{"t":"Jack Lumber","p":["iOS"],"d":"Owlchemy Labs","u":"Sega, Owlchemy Labs","g":"Arcade, action","r":"August 16, 2012","l":"https://en.wikipedia.org/wiki/Jack_Lumber","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co23vk.jpg","s":"A tree killed his granny and now he is out for revenge. Meet Jack Lumber, the supernatural lumberjack who hates trees, loves animals, and hates trees. Did we say that twice? The guy really hates trees, and boy does he have an axe to grind.\n\nUse the supernatural powers of Jack Lumber to massacre the forest in this time-warping, line-drawing, log-slicing, pun-filled lumberjacking mashup! Bust out your flannel to muster the strength and burlyness to solve the skill and logic puzzles (flannel not actually required).\n\nFight the forest and make Granny proud! Eff trees!"},{"t":"Jagged Alliance: Back in Action","p":["Windows"],"r":"February 9"},{"t":"Jagged Alliance: Crossfire","p":["Windows"],"r":"August 24"},{"t":"Jak and Daxter Collection","p":["PlayStation 3"],"r":"February 7","l":"https://en.wikipedia.org/wiki/Jak_and_Daxter_Collection"},{"t":"Jet Set Radio","p":["Windows","Xbox 360","Android","iOS","PlayStation Vita","PlayStation 3"],"d":"BlitWorks","u":"Sega","g":"Platform, Sport, Arcade","r":"September 18, 2012","l":"https://www.igdb.com/games/jet-set-radio","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2dzv.jpg","s":"Tag, grind, and trick to the beat in SEGA’s hit game Jet Set Radio!\n\nFight for control of Tokyo-to, mark your turf with graffiti, tag walls, billboards, and even rival gang members! Perform tricks and flips on magnetically driven in-line skates, but watch out for the local police force!"},{"t":"Jet Set Radio HD","p":["PlayStation Network","Windows","Xbox 360","PlayStation Vita","iOS","Android"],"r":"September 18","l":"https://en.wikipedia.org/wiki/Jet_Set_Radio_HD"},{"t":"Jewelpet: Magical Dance in Style Deco!","p":["Nintendo 3DS"],"d":"FuRyu","u":"FuRyu","g":"Rhythmic, Music","r":"November 8, 2012","l":"https://en.wikipedia.org/wiki/Jewelpet:_Magical_Dance_in_Style_Deco!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6cg5.jpg"},{"t":"Joe Danger 2: The Movie","p":["Xbox 360","PlayStation Network"],"r":"September 14"},{"t":"Johnny Hotshot","p":["Nintendo 3DS"],"d":"UFO Interactive Games","u":"UFO Interactive Games","g":"Shoot 'em up","r":"November 8, 2012","l":"https://en.wikipedia.org/wiki/Johnny_Hotshot","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6cgh.jpg","s":"YEEEEEEE-HAAAAAAA! Johnny HotShot is an arcade action unlike any other!"},{"t":"Johnny Impossible","p":["Nintendo 3DS"],"d":"UFO Interactive Games","u":"UFO Interactive Games","g":"Platformer","r":"December 27, 2012","l":"https://en.wikipedia.org/wiki/Johnny_Impossible","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6cgg.jpg","s":"2D Stealth platformer for the 3DS eShop."},{"t":"Johnny Kung Fu","p":["Nintendo 3DS"],"d":"UFO Interactive Games","u":"UFO Interactive Games","g":"Platformer","r":"July 12, 2012","l":"https://en.wikipedia.org/wiki/Johnny_Kung_Fu"},{"t":"Jojo's Bizarre Adventure HD","p":["PlayStation Network","Xbox 360"],"r":"August 21","l":"https://en.wikipedia.org/wiki/JoJo%27s_Bizarre_Adventure_(video_game)"},{"t":"Journey","p":["PlayStation 3","PlayStation Network"],"u":"Sony Computer Entertainment","g":"Platform, Adventure, Indie","r":"March 13, 2012","l":"https://en.wikipedia.org/wiki/Journey_(2012_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob9lk.jpg","s":"A third-person adventure game in which the player, controlling a robed figure, makes a pilgrimage through a desert landscape to a rugged mountain with a beacon of light in the distance while uncovering the history of their people, rescuing and cooperating with friendly creatures, avoiding predatory ones and communicating with other travelers."},{"t":"Journey of Jesus: The Calling","p":["Browser"],"d":"Lightside Games","u":"Lightside Games","r":"May 15, 2012","l":"https://en.wikipedia.org/wiki/Journey_of_Jesus:_The_Calling"},{"t":"Joy Ride Turbo","p":["Xbox 360"],"r":"May 23","l":"https://en.wikipedia.org/wiki/Joy_Ride_Turbo"},{"t":"Judge Dee: The City God Case","p":["PlayStation Network"],"r":"December 11"},{"t":"Juniper's Knot","p":["Windows","macOS","Linux"],"d":"Dischan Media","u":"Dischan Media","g":"Visual novel","r":"April 13, 2012","l":"https://en.wikipedia.org/wiki/Juniper's_Knot","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co27zr.jpg","s":"Juniper's Knot is a short (~30 mins) kinetic novel about the meeting of a demon and a boy. A kinetic novel is a game that uses text, sound, and illustrations to tell a story."},{"t":"Jurassic Park Builder","p":["iOS"],"r":"July 23","l":"https://en.wikipedia.org/wiki/Jurassic_Park_Builder"},{"t":"Jurassic Park: The Game - Episode 3: The Depths","p":["iOS"],"r":"January 22"},{"t":"Just Dance 4","p":["Wii","PlayStation 3","Xbox 360","Wii U"],"g":"Music","r":"October 9","l":"https://en.wikipedia.org/wiki/Just_Dance_4","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1xf6.jpg","s":"Just Dance 4 features more than 40 new tracks, ranging from chart-topping Billboard hits to classic dance party tracks. Whether it's pop, Hip-Hop, rock, R&B, country or funk, there is something for everyone to dance to."},{"t":"Just Dance Wii 2","p":["Wii"],"d":"Ubisoft Paris","u":"Nintendo","g":"Music, rhythm","r":"July 26, 2012","l":"https://en.wikipedia.org/wiki/Just_Dance_Wii_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1xgc.jpg","s":"The second Japanese Just Dance game published and edited by Nintendo but developed by Ubisoft Paris. It was released on 26 July 2012, only for the Wii."},{"t":"Just Dance: Best Of","p":["Xbox 360","Wii"],"r":"June 26"},{"t":"Just Dance: Disney Party","p":["Xbox 360","Wii"],"d":"Land Ho!","u":"Ubisoft","g":"Music, Rhythm, Dance","r":"October 23, 2012","l":"https://en.wikipedia.org/wiki/Just_Dance:_Disney_Party","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1xg9.jpg","s":"Just Dance and Disney are working in collaboration to create the greatest dance game for the whole family – Just Dance: Disney Party on Wii and Kinect for Xbox 360. Dance like a star to songs from beloved Disney favorites and Disney Channel’s hottest shows. Family favorite songs, fun dances and kid-friendly gameplay, children of all ages can Just Dance along with friends."},{"t":"Just Dance: Greatest Hits","p":["Wii","Xbox 360"],"d":"Ubisoft Paris, Ubisoft Montreal","u":"Ubisoft","g":"Music, rhythm","r":"March 29, 2012","l":"https://en.wikipedia.org/wiki/Just_Dance:_Greatest_Hits","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6953.jpg","s":"Just Dance: Greatest Hits is part of the Just Dance video game series published by Ubisoft. The game includes songs from Just Dance, Just Dance 2, Just Dance: Summer Party, and Just Dance 3, with 25 songs in the Wii PAL (Europe) counterpart (Best Of) and 35 songs in the NTSC (North America) Wii and Xbox 360 version (Greatest Hits). It is only available on the NTSC Wii and the Xbox 360."},{"t":"Kanye Zone","p":["Browser"],"d":"Otter Spice Productions","g":"Action","r":"March 9, 2012","l":"https://en.wikipedia.org/wiki/Kanye_Zone","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7b5l.jpg","s":"Kanye Zone is a high-score based parody game where you try to stop Kanye West from getting into his zone."},{"t":"Karateka","p":["Xbox 360","PlayStation 3"],"r":"November 7","l":"https://en.wikipedia.org/wiki/Karateka_(video_game)"},{"t":"Katawa Shoujo","p":["Windows"],"d":"Four Leaf Studios","u":"Four Leaf Studios","g":"Visual novel","r":"January 4","l":"https://en.wikipedia.org/wiki/Katawa_Shoujo","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7k1l.jpg","s":"Katawa Shoujo is a bishoujo-style visual novel set in the fictional Yamaku High School for disabled children, located somewhere in modern Japan. Hisao Nakai, a normal boy living a normal life, has his life turned upside down when a congenital heart defect forces him to move to a new school after a long hospitalization. Despite his difficulties, Hisao is able to find friends—and perhaps love, if he plays his cards right. There are five main paths corresponding to the 5 main female characters, each path following the storyline pertaining to that character."},{"t":"Ketzal's Corridors","p":["Nintendo 3DS"],"r":"April 12","l":"https://en.wikipedia.org/wiki/Ketzal%27s_Corridors"},{"t":"Kid Icarus: Uprising","p":["Nintendo 3DS"],"g":"Shooter, Hack and slash/Beat 'em up","r":"March 23","l":"https://www.igdb.com/games/kid-icarus-uprising","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob9me.jpg","s":"One of the most beloved franchises in Nintendos long history makes its glorious return in spectacular 3D! Pit of Kid Icarus fame is back in a new game designed specifically for the Nintendo 3DS system, by Masahiro Sakurai, creator of the Kirby and Super Smash Bros. franchises, and his development team at Project Sora.\n\nKid Icarus: Uprising is a fast-paced and action-packed blend of aerial and ground-based shooting built on elegantly intuitive and streamlined play control. This follow-up to the original Kid Icarus released for the Nintendo Entertainment System in 1987 has been at the top of gamers wish lists for years.\n\nBoasting gameplay that is easy to pick up but incredibly deep, the game is sure to satisfy novice gamers as well as fans who have been clamouring for a new installment in the franchise.\n\nThe hero, Pit, teams up with Palutena, the goddess of light, who bestows on him the miracle of flight for limited stretches. With this gift, Pit soars through the skies, shooting down swarms of enemies, then alights and engages in frantic ground-based battles against Medusas underworld army.\n\nFind and collect numerous weapons and items that offer bonuses and ability boosts. Players can choose weapons before they send Pit into battle, giving them countless layers of strategies in each level.\n\nPlayers can choose between a basic Blade, basic Claws and a basic Orbitar weapon. Blades are well-balanced, Claws have limited reach but increase running speed and the Orbitars can shoot two shots that grow in power over distance."},{"t":"Kidō Senshi Gundam SEED Battle Destiny","p":["PlayStation Vita"],"d":"Artdink","u":"Namco Bandai Games","g":"Combat, Mecha, Science Fiction","r":"June 7, 2012","l":"https://en.wikipedia.org/wiki/Kid%C5%8D_Senshi_Gundam_SEED_Battle_Destiny","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7zpq.jpg","s":"Become a pilot in the world of Mobile Suit Gundam SEED! Engage in thrilling, action-packed Gundam battles, complete missions, and tune up your newly acquired Mobile Suits!"},{"t":"Kiki Trick","p":["Wii"],"d":"Nintendo SPD","u":"Nintendo","g":"Music, party","r":"January 19, 2012","l":"https://en.wikipedia.org/wiki/Kiki_Trick","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6uwl.jpg","s":"Kiki Trick is best described as a sound-based collection of mini-games. It has an eclectic art design fusing a blend of paper cut outs, hand drawn visuals, and digital photography and video featuring Japanese actors."},{"t":"Killzone HD","p":["PlayStation Network"],"r":"October 23","l":"https://en.wikipedia.org/wiki/Killzone"},{"t":"Kindred Spirits on the Roof","p":[],"l":"https://en.wikipedia.org/wiki/Kindred_Spirits_on_the_Roof"},{"t":"Kinect Nat Geo TV","p":["Xbox 360"],"d":"Relentless Software, SkyBox Labs","u":"Microsoft Studios","r":"September 18, 2012","l":"https://en.wikipedia.org/wiki/Kinect_Nat_Geo_TV","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22pr.jpg","s":"A ground-breaking interactive experience developed as part of Microsoft \\\"playful learning\\\" initiative, Kinect Nat Geo TV uses Kinect to combine motion-control with augmented reality. It mixes high-quality National Geographic television shows with fun-packed Xbox 360 Kinect motion-controlled game play.With Kinect Nat Geo TV, you\\'re not only gaming and you\\'re not only watching TV -- living rooms are turned into animal habitats and players into a variety of animals! And all along, players are inspired to learn and care about the planet. Kinect Nat Geo goes beyond what a TV show can do: it is a totally immersive experience for parents and kids."},{"t":"Kinect Party","p":["Xbox 360"],"r":"December 18","l":"https://en.wikipedia.org/wiki/Kinect_Party"},{"t":"Kinect Rush: A Disney-Pixar Adventure","p":["Xbox 360"],"r":"March 20"},{"t":"Kinect Sesame Street TV","p":["Xbox 360","Windows"],"d":"Soho Productions","u":"Microsoft Studios","g":"Edutainment","r":"September 18, 2012","l":"https://en.wikipedia.org/wiki/Kinect_Sesame_Street_TV","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22qy.jpg","s":"With Kinect Sesame Street TV, children are invited to experience the world of Sesame Street alongside their favorite characters such as Big Bird, Grover, Cookie Monster and Elmo like never before. The magic of Kinect for Xbox 360 lets you share in the experience through visual and physical interactions with characters of Sesame Street, placing you in the Sesame Street experience."},{"t":"Kinect Star Wars","p":["Xbox 360"],"r":"April 3","l":"https://en.wikipedia.org/wiki/Kinect_Star_Wars"},{"t":"King Arthur II: The Role-playing Wargame","p":["Windows"],"r":"January 27"},{"t":"King's Bounty: Warriors of the North","p":["Windows"],"d":"1C-Softclub","u":"1C Company","g":"Tactical role-playing","r":"October 26, 2012","l":"https://en.wikipedia.org/wiki/King's_Bounty:_Warriors_of_the_North","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co44is.jpg","s":"King’s Bounty: Warriors of the North is the next chapter in the cult RPG/adventure saga. The new tale takes place in the familiar world of Endoria featured in the previous games, but begins in the Viking lands, which the celebrated hero Bill Gilbert never visited during his famous quest in King’s Bounty: The Legend.\n\nThe Mighty Olaf, son of the Konung of Northlings, has dedicated his life to battling the undead who have infested the northern lands of Endoria. He seeks to liberate the snowy wastes, dwarven dungeons, and the very heart of Endoria, the kingdom of Darion itself, from the dark grip of necromancy. On his quest towards immortal glory he will encounter cunning foes and new friends, hard battles and amazing adventures."},{"t":"Kingdom Conquest II","p":["iOS","Android"],"d":"Sega","u":"Sega","g":"Massively-multiplayer, Strategy","r":"December 12, 2012","l":"https://en.wikipedia.org/wiki/Kingdom_Conquest_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2p7e.jpg","s":"It is a time of war and chaos. Begin with nothing and end with a kingdom. SEGA’s Kingdom Conquest II is the epic free-to-play strategy game for conquerors.Dominate real players online. Unite the strong and crush the weak until final victory is declared. You decide who joins your cause or submits to your will. Kingdom Conquest II blends the best elements of card battling, real time strategy, MMORPGs, and 3D dungeon battles to deliver a massive and addictive fantasy war game like no other."},{"t":"Kingdom Hearts 3D: Dream Drop Distance","p":["Nintendo 3DS"],"g":"Role-playing (RPG)","r":"July 31","l":"https://www.igdb.com/games/kingdom-hearts-3d-dream-drop-distance","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co318g.jpg","s":"Kingdom Hearts 3D: Dream Drop Distance is the seventh game in the Kingdom Hearts series. It was originally developed for the Nintendo 3DS hand-held system. It is a direct sequel to Kingdom Hearts II, Kingdom Hearts coded, and the epilogue of Kingdom Hearts Birth by Sleep.\n\nUtilizing the 3DS's high-spec graphics processing, the game's graphics are near on-par with those of the PS2 titles, and make use of the system's 3D technology to add immersion when falling from high places and flying far distances. The 3D effect is used more for \"going into the screen\" rather than things popping out."},{"t":"Kingdoms of Amalur: Reckoning","p":["Windows","PlayStation 3","Xbox 360"],"g":"Role-playing (RPG), Hack and slash/Beat 'em up","r":"February 7","l":"https://www.igdb.com/games/kingdoms-of-amalur-reckoning","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co25rk.jpg","s":"Kingdoms of Amalur: Reckoning is an epic, open-world role-playing game set in Amalur, a mysterious and magical new fantasy world created by New York Times best-selling author R. A. Salvatore. Brought to life visually through the trademark visceral style of renowned artist and Spawn creator Todd McFarlane, Reckoning brings a new level of intense action combat to the RPG genre."},{"t":"Kirby's Dream Collection: Special Edition","p":["Wii"],"r":"September 16","l":"https://en.wikipedia.org/wiki/Kirby%27s_Dream_Collection"},{"t":"Kitten Sanctuary","p":["iOS","Android","Windows","macOS"],"d":"Clockwork Pixels","g":"Puzzle, Strategy","r":"March 27, 2012","l":"https://en.wikipedia.org/wiki/Kitten_Sanctuary","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/xsd2lmfwnueuivp4xx9t.jpg","s":"A match-3 pet simulation game in which aliens have trapped kittens in special cages with scrumptious treats. Free trapped kittens and keep them safe in your kitten sanctuaries."},{"t":"Knights of Pen & Paper","p":["iOS","Android"],"d":"Behold Studios","u":"Paradox Interactive, Seaven Studio","g":"Role-playing game","r":"October 30, 2012","l":"https://en.wikipedia.org/wiki/Knights_of_Pen_&_Paper"},{"t":"Knytt Underground","p":["PlayStation 3","PlayStation Vita"],"r":"December 18","l":"https://en.wikipedia.org/wiki/Knytt_Underground"},{"t":"Kung Fu Strike: The Warrior's Rise","p":["Xbox 360"],"r":"September 5"},{"t":"Kyūkōsha no Shōjo","p":["Nintendo 3DS"],"d":"Arc System Works","u":"Arc System Works","g":"Adventure","r":"August 1, 2012","l":"https://en.wikipedia.org/wiki/Ky%C5%ABk%C5%8Dsha_no_Sh%C5%8Djo"},{"t":"La-Mulana","p":["Windows","Wii"],"r":"July 13","l":"https://en.wikipedia.org/wiki/La-Mulana"},{"t":"Lad","p":["iOS","Android"],"d":"Keith Curtis","u":"Keith Curtis","g":"Puzzle","r":"September 12, 2012","l":"https://en.wikipedia.org/wiki/Lad_(video_game)"},{"t":"Lagrange: The Flower of Rin-ne","p":[],"l":"https://en.wikipedia.org/wiki/Lagrange:_The_Flower_of_Rin-ne"},{"t":"Lalaloopsy: Carnival of Friends","p":["Nintendo 3DS"],"r":"September 25","l":"https://en.wikipedia.org/wiki/Lalaloopsy"},{"t":"LBX: Little Battlers eXperience","p":["Nintendo 3DS"],"d":"Level-5, Climax Entertainment","u":"Level-5, Nintendo","g":"Action role-playing game","r":"July 5, 2012","l":"https://en.wikipedia.org/wiki/LBX:_Little_Battlers_eXperience","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobrsc.jpg","s":"Play as Van Yamano, a young boy who comes upon a unique LBX – a complex, customizable, palm-sized robot. Use it – and team up with familiar characters from the hit TV series – to take down the evil corporation known as the New Dawn Raisers."},{"t":"Legasista","p":["PlayStation Network"],"r":"August 21","l":"https://en.wikipedia.org/wiki/Legasista"},{"t":"Legend of Grimrock","p":["Windows"],"g":"Puzzle, Role-playing (RPG), Adventure, Indie","r":"April 11","l":"https://en.wikipedia.org/wiki/Legend_of_Grimrock","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1mpw.jpg","s":"What is Legend of Grimrock?\n\nOld-school dungeon crawling game inspired by Dungeon Master, Eye of the Beholder and Ultima Underworld.\nExplore a vast dungeon riddled with hidden switches, pressure plates, sliding walls, trapdoors and more.\nDiscover secrets, cast spells with runes and craft potions with herbs.\nFight murderous monsters and seek lost artifacts in ancient tombs.\nCreate a party of four characters and customize them with different races, classes, skills and traits.\n\nLegend of Grimrock is a dungeon crawling role playing game with an oldschool heart but a modern execution. A group of prisoners are sentenced to certain death by exiling them to the secluded Mount Grimrock for vile crimes they may or may not have committed. Unbeknownst to their captors, the mountain is riddled with ancient tunnels, dungeons and tombs built by crumbled civilizations long perished now. If they ever wish to see daylight again and reclaim their freedom the ragtag group of prisoners must form a team and descend through the mountain, level by level.\n\nThe game brings back the oldschool challenge with highly tactical real-time combat and grid-based movement, devious hidden switches and secrets as well as deadly traps and horrible monsters. Legend of Grimrock puts an emphasis on puzzles and exploration and the wits and perception of the player are more important tools than even the sharpest of swords could be. And if you are a hardened dungeon crawling veteran and you crave an extra challenge, you can arm yourself with a stack of grid paper and turn on the Oldschool Mode which disables the luxury of the automap! Are you ready to venture forth and unravel the mysteries of Mount Grimrock?"},{"t":"Legends of Pegasus","p":["Windows"],"d":"NovaCore Studios","u":"Kalypso Media","g":"4X, Real-time strategy, Turn-based strategy","r":"August 10, 2012","l":"https://en.wikipedia.org/wiki/Legends_of_Pegasus","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cbg10lr4atmqcjhsvsti.jpg","s":"Legends of Pegasus takes you on an epic journey into 3D space, mixing real-time and turn-based strategy. Expand your civilization by colonizing new planets, building factories, laboratories and shipyards, researching new technologies and designing new spaceships. Command massive fleets in tactically challenging, visually astounding real-time battles!\n\nSave mankind in a massive, 40 hour single player campaign! Fight multiplayer battles against up to seven opponents via internet or local area network! The spectacular 3D graphics don’t just bring life to marvelous planets, but also to the stunningly detailed spaceships you can freely design thanks to an intuitive ship editor."},{"t":"Lego Batman 2: DC Super Heroes","p":["Windows","PlayStation 3","Xbox 360","Wii","PlayStation Vita","Nintendo 3DS"],"g":"Platform, Hack and slash/Beat 'em up, Adventure","r":"June 19","l":"https://www.igdb.com/games/lego-batman-2-dc-super-heroes","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2j0q.jpg","s":"The Dynamic Duo of Batman and Robin join other famous super heroes from the DC Universe including Superman, Wonder Woman and Green Lantern to save Gotham City from destruction at the hands of the notorious villains Lex Luthor and the Joker."},{"t":"Lego Harry Potter: Years 5–7","p":["PlayStation Vita"],"r":"March 6"},{"t":"Lego Juniors Create & Cruise","p":["iOS","Android","Windows"],"d":"Funday Factory","g":"Arcade","l":"https://en.wikipedia.org/wiki/Lego_Juniors_Create_&_Cruise","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2p6q.jpg","s":"Little Kids 4/7 can create their lego vehicles and run them on the roads, getting bonus pieces when picking points on the way."},{"t":"LEGO The Lord of the Rings: The Video Game","p":["PlayStation Vita","Nintendo 3DS","Nintendo DS","Windows","PlayStation 3","Xbox 360","Wii"],"r":"October 30","l":"https://en.wikipedia.org/wiki/Lego_The_Lord_of_the_Rings_(video_game)"},{"t":"Letterpress","p":["iOS"],"r":"October 24","l":"https://en.wikipedia.org/wiki/Letterpress_(video_game)"},{"t":"Liberation Maiden","p":["Nintendo 3DS"],"r":"October 25","l":"https://en.wikipedia.org/wiki/Guild_(video_game_series)"},{"t":"Life in the Dorms","p":["Xbox 360","Steam"],"d":"Moment Games","g":"Point-and-click adventure","l":"https://en.wikipedia.org/wiki/Life_in_the_Dorms"},{"t":"Life Weaver","p":["Windows"],"d":"BGG Productions","u":"BGG Productions","g":"Action, Survival Horror","r":"January 10, 2012","l":"https://en.wikipedia.org/wiki/Life_Weaver"},{"t":"Light the Flower","p":["iOS"],"d":"Tribeflame","u":"Chillingo","g":"Puzzle game","r":"March 22, 2012","l":"https://en.wikipedia.org/wiki/Light_the_Flower"},{"t":"Lisa: The First","p":["Windows"],"g":"Role-playing (RPG), Adventure, Indie","l":"https://en.wikipedia.org/wiki/Lisa:_The_First","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocxl9.jpg","s":"Lisa: The First is a Yume-Nikki style exploration game. It was made in RPG Maker 2003 and released on October 9th, 2012. It is the predecessor to Lisa: The Painful. It is an exploration of Lisa Armstrong's mind as she tries to cope with the burden of being abused by her father Marty before committing suicide."},{"t":"Little Deviants","p":["PlayStation Vita"],"r":"February 15","l":"https://en.wikipedia.org/wiki/Little_Deviants"},{"t":"Little Inferno","p":["Wii U","Windows"],"g":"Puzzle, Simulator, Adventure, Indie","r":"November 18","l":"https://en.wikipedia.org/wiki/Little_Inferno","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co253v.jpg","s":"Congratulations on your new Little Inferno Entertainment Fireplace! Throw your toys into your fire, and play with them as they burn. Stay warm in there. It's getting cold outside! Burn flaming logs, screaming robots, credit cards, batteries, exploding fish, unstable nuclear devices, and tiny galaxies. An adventure that takes place almost entirely in front of a fireplace - about looking up up up out of the chimney, and the cold world just on the other side of the wall."},{"t":"LittleBigPlanet fan remake of Final Fantasy VII","p":[],"d":"Jamie Colliver","g":"Role-playing","l":"https://en.wikipedia.org/wiki/LittleBigPlanet_fan_remake_of_Final_Fantasy_VII"},{"t":"LittleBigPlanet Karting","p":["PlayStation 3"],"g":"Racing, Arcade","r":"November 6","l":"https://en.wikipedia.org/wiki/LittleBigPlanet_Karting","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2f3a.jpg","s":"Give full throttle to your imagination and join Sackboy and Sackgirl on the starting grid for a kart racing adventure like no other. Fire up your engines, jump behind the steering wheel and take on your friends and foes in breathtakingly unpredictable battles through an ever-changing world of content. Are you ready?\n\nLittleBigPlanet Karting combines the excitement and fun of a racing game with the ability to create any race you can imagine. Take advantage of simple and powerful creation tools to easily build your own tracks, design unique power-ups or customise your karts. Want to race a boxing glove through a land made of cheese? And then fire pizzas from your kart? You got it. Just watch out for those skull shaped hovercrafts. And flaming snakes. And whatever else is out there...\n\nBattle your friends online via PlayStation Network or in the same room using the split-screen mode, complete challenges or dive into the community to discover new player-created courses. No two tracks are ever the same, so you will never run out of new places to do battle. Race the unexpected and leave the real world in the dust!"},{"t":"LittleBigPlanet PS Vita","p":["PlayStation Vita"],"r":"September 25","l":"https://en.wikipedia.org/wiki/LittleBigPlanet_PS_Vita"},{"t":"Lode Runner Classic","p":[],"l":"https://en.wikipedia.org/wiki/Lode_Runner_Classic"},{"t":"Lollipop Chainsaw","p":["PlayStation 3","Xbox 360"],"d":"Grasshopper Manufacture","u":"Warner Bros. Interactive Entertainment","g":"Hack and slash","r":"June 15","l":"https://en.wikipedia.org/wiki/Lollipop_Chainsaw","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3kr3.jpg","s":"Lollipop Chainsaw is the 'un-deadly' story of sweet and killer zombie hunter Juliet Starling and her quest to uncover the root of a colossal zombie outbreak. With her wickedly awesome chainsaw in hand, Juliet slices, dices and splits her way through hordes of the undead, but soon realizes the horde is only the opening act to a festival of zombie rock lords determined to kill the chainsaw wielding cheerleader."},{"t":"Lollipop Chainsaw (US)","p":["PlayStation 3","Xbox 360"],"d":"Grasshopper Manufacture","u":"Warner Bros. Interactive Entertainment","g":"Hack and slash","r":"June 12","l":"https://en.wikipedia.org/wiki/Lollipop_Chainsaw"},{"t":"London 2012","p":["Windows","PlayStation 3","Xbox 360"],"r":"June 26","l":"https://en.wikipedia.org/wiki/London_2012_(video_game)"},{"t":"Lone Survivor","p":["Windows"],"g":"Puzzle, Adventure","r":"April 23","l":"https://en.wikipedia.org/wiki/Lone_Survivor_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2gyd.jpg","s":"From the creator of Soul Brother and Soundless Mountain II, comes an original and adult Psychological Horror.\n\nThe masked protagonist must escape from a city ravaged by disease, by any means. Starving and exhausted, he has begun to question how much of what he sees is even real.\n\nA new kind of adventure where the choice of how to survive is up to you. Sneak through without firing a single shot, or kill everything in your path. Eat and sleep well, or resort to drugs to keep going. Search for survivors, or try to escape the city alone. Look after your mental health, or descend into madness..."},{"t":"Long Live the Queen","p":["Windows"],"g":"Role-playing (RPG), Simulator, Strategy, Adventure, Indie, Visual Novel","r":"June 2","l":"https://en.wikipedia.org/wiki/Long_Live_the_Queen_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6jce.jpg","s":"Rule the world or die trying! Being a Princess is not an easy job. Being a Queen is even harder. Especially when you're only fourteen years old, and the reason you've inherited the throne is that your royal mother has just met an untimely end. Now power is up for grabs."},{"t":"Loren the Amazon Princess","p":["Linux","macOS","Windows"],"d":"Winter Wolves","u":"Winter Wolves","g":"Role-playing, visual novel","r":"April 30, 2012","l":"https://en.wikipedia.org/wiki/Loren_the_Amazon_Princess","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co45f6.jpg","s":"Loren The Amazon Princess is a fantasy visual novel with RPG elements. The player reads through the story and occasionally has to fight against fantasy monsters."},{"t":"LostWinds 2: Winter of the Melodias","p":["iOS"],"r":"May 9"},{"t":"Lucius","p":["Windows"],"d":"Shiver Games","u":"Lace Mamba Global, Shiver Games","g":"Horror, adventure","r":"October 26, 2012","l":"https://en.wikipedia.org/wiki/Lucius_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2iqn.jpg","s":"“Here is wisdom. Let him that hath understanding count the number of the Beast: for it is the number of a man; and his number is Six hundred threescore and six.” - Revelation 13:18\n\nWhen little Lucius was born on the devilishly significant date of June 6th, 1966, no one expected him to be anything other than a normal little boy. His childhood, spent in a luxurious manor, was as normal as every kid’s childhood years - well, except for the extreme wealth of his parents, as Lucius grew up with everything he desired and more. Everything went to Hell, in a manner of speaking, when Lucius turned 6. The Devil, who is his real father, manifests himself in his dreams the night before his birthday revealing to Lucius his true heritage. It’s up to Lucius to bring Hell on Earth using any and all means necessary.\n\nOrchestrate deadly accidents, using items, tools, and hell’s powers such as telekinesis and mind control. By combining classic adventure gameplay with the freedom and openness of a 3D world, you’ll have to use your wits and ensure no one knows of your fiendish mission until it’s too late!"},{"t":"Lumines: Electronic Symphony","p":["PlayStation Vita"],"r":"February 22"},{"t":"Lunar: Silver Star Story Touch","p":[],"l":"https://en.wikipedia.org/wiki/Lunar:_Silver_Star_Story_Touch"},{"t":"Luxor Evolved","p":["Windows","iOS","PlayStation 4","Xbox One"],"d":"MumboJumbo, Olde Skuul","u":"MumboJumbo, Accelerate Games","g":"Puzzle","r":"March 1, 2012","l":"https://en.wikipedia.org/wiki/Luxor_Evolved","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8pnq.jpg","s":"Step into a time warp and experience Luxor like never before in Luxor Evolved, a commanding new vision for the #1 marble shooting game."},{"t":"M.A.V.","p":["Windows"],"d":"Bombdog Studios","u":"Bombdog Studios","g":"Mech simulator","l":"https://en.wikipedia.org/wiki/M.A.V._(video_game)"},{"t":"Machinarium","p":["PlayStation 3"],"r":"October 9","l":"https://en.wikipedia.org/wiki/Machinarium"},{"t":"Machines at War 3","p":["Windows","macOS"],"d":"Isotope 244","g":"Real-time strategy","r":"September 21, 2012","l":"https://en.wikipedia.org/wiki/Machines_at_War_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co47oc.jpg","s":"Real time strategy game featuring over 130 different types of units and technologies, 21 campaign missions with characters and an intriguing story, unlimited random map skirmishes with many customizable settings, network multiplayer to challenge your friends, and so much more in this RTS."},{"t":"Mad Acorn","p":["iOS"],"d":"APD Inc.","g":"Rhythm","r":"June 4, 2012","l":"https://en.wikipedia.org/wiki/Mad_Acorn"},{"t":"Mad Father","p":["Windows","Steam"],"d":"Sen","u":"Miscreant's Room","g":"Survival horror, role-playing, puzzle","r":"December 10, 2012","l":"https://en.wikipedia.org/wiki/Mad_Father","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2f5y.jpg","s":"Mad Father is a horror-puzzle game that follows the experiences of a young German girl by the name of Aya Drevis."},{"t":"Mad Riders","p":["PlayStation Network","Windows","Xbox 360"],"r":"May 29","l":"https://en.wikipedia.org/wiki/Mad_Riders"},{"t":"Madagascar 3: The Video Game","p":["Nintendo 3DS","Nintendo DS","PlayStation 3","Wii","Xbox 360"],"r":"June 5"},{"t":"Madagascar: Join the Circus!","p":["iOS"],"r":"June 4"},{"t":"Madden NFL 13","p":["PlayStation 3","Xbox 360","Wii","PlayStation Vita"],"r":"August 28","l":"https://en.wikipedia.org/wiki/Madden_NFL_13"},{"t":"Magic: The Gathering – Duels of the Planeswalkers 2013","p":["Windows","PlayStation Network","Xbox 360","iOS"],"g":"Strategy, Turn-based strategy (TBS), Tactical, Card & Board Game","r":"June 20","l":"https://www.igdb.com/games/magic-the-gathering-duels-of-the-planeswalkers-2013","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/uqzcexfghnshgovzddux.jpg","s":"Play with friends or AI as you travel across fantastic planes to take on new encounters & opponents. Magic 2013 features ten customizable decks, individual records, new items & more!"},{"t":"Magical Drop V","p":["Windows"],"d":"Golgoth Studio","u":"UTV Ignition Entertainment","g":"Puzzle","r":"November 15, 2012","l":"https://en.wikipedia.org/wiki/Magical_Drop_V","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3u80.jpg","s":"Magical Drop Is Back!!! Yes, the cult-classic returns with all the fast-paced action you expect from the franchise, mixed with modern visuals and multi-player online experiences.\n\nThe sixth Magical Drop game was developed by French independent studio Golgoth and published by UTV Ignition for Steam in 2012. Xbox Live Arcade and PlayStation Network ports were announced, but ultimately never materialized. The game features a much smaller selection of characters, omits items, and removes Puzzle Mode; however, it adds new online gameplay modes. Characters from the cancelled Data East puzzle game Ghostlop are introduced; these three characters use Ghostlop gameplay instead of traditional Magical Drop mechanics."},{"t":"Magicka: The Other Side of the Coin","p":["Windows"],"r":"June 19","l":"https://en.wikipedia.org/wiki/Magicka#Expansions,_DLC_and_new_content"},{"t":"Maison de Maou","p":["Xbox 360"],"r":"September 25"},{"t":"Major League Baseball 2K12","p":["Windows","PlayStation 3","Xbox 360","Wii","PlayStation 2","PlayStation Portable","Nintendo DS"],"r":"March 6","l":"https://en.wikipedia.org/wiki/Major_League_Baseball_2K12"},{"t":"Maldita Castilla","p":["Windows","Linux","Ouya"],"d":"Locomalito","g":"Platform","l":"https://en.wikipedia.org/wiki/Maldita_Castilla","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7t1d.jpg","s":"Cursed is an action platformer with a compendium of myths from medieval Spain and the spirit of a mid-to-late '80s arcade game.\n\nRun, jump and throw your weapons as you move through decadent medieval landscapes full of dangers and monsters. Learn about each situation and enemy pattern in order to progress. Open chests and hit hidden spots for bonuses, weapons and equippable objects. Find the five Moura's tears to unlock the true final chapter and discover a bunch of secrets to reach different endings."},{"t":"Malevolence: The Sword of Ahkranox","p":["Windows"],"d":"Visual Outbreak","u":"Visual Outbreak","g":"Action role-playing, Dungeon crawl","r":"December 21, 2012","l":"https://en.wikipedia.org/wiki/Malevolence:_The_Sword_of_Ahkranox"},{"t":"Malicious","p":["PlayStation 3"],"r":"July 24","l":"https://en.wikipedia.org/wiki/Malicious_(video_game)"},{"t":"Man vs. Machine","p":[],"d":"MuchDifferent","g":"First-person shooter","l":"https://en.wikipedia.org/wiki/Man_vs._Machine_(video_game)"},{"t":"Manos: The Hands of Fate","p":["iOS","Android","Windows"],"d":"FreakZone","u":"FreakZone","g":"Platform","r":"July 26, 2012","l":"https://en.wikipedia.org/wiki/Manos:_The_Hands_of_Fate_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5j47.jpg","s":"Retro platforming action in this adaptation of a terrible movie."},{"t":"Mari0","p":["Windows","macOS","Linux"],"d":"Maurice Guégan","u":"Stabyourself.net","g":"Platform, puzzle","r":"March 3, 2012","l":"https://en.wikipedia.org/wiki/Mari0","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22jz.jpg","s":"Mari0 is a fan-made video game that combines elements of the video games Super Mario Bros and Portal. The game was developed by Maurice Guégan of Stabyourself.net, who has previously worked on parody games such as Not Tetris. Mari0 was developed with the LÖVE framework, and is cross-platform. The game was released on March 3, 2012 for Windows, Mac OS X, and Linux under a Creative Commons license (BY-NC-SA). The source code is also available to download.\nThe core game of Mari0 plays directly from the 8-bit Super Mario Bros. 2D platform game, where the player controls Mario via the keyboard, running and jumping through levels, avoiding or jumping on enemies to defeat them, while collecting coins to earn points towards their score. The game adds the concept of the \"portal gun\" from the Portal series; the player can click with the mouse device on two separate surfaces on the level to create a portal between them. This can be used for a number of gameplay options, often using vertical momentum entering one portal to \"fling\" the Mario character horizontally out of the other portal, but will also affect enemies and other game elements in similar manners.\nThe core game uses the level designs from the original Super Mario Bros. as well as sets of test chambers inspired by Portal '​s Aperture Science, but a level editor, along with different graphic sets and shaders are provided to create new content. Up to four players can cooperatively play in the game. Online multiplayer is to be released in a future version."},{"t":"Mario & Sonic at the London 2012 Olympic Games","p":["Nintendo 3DS"],"r":"February 14","l":"https://en.wikipedia.org/wiki/Mario_%26_Sonic_at_the_London_2012_Olympic_Games"},{"t":"Mario Party 9","p":["Wii"],"g":"Puzzle, Adventure, Card & Board Game","r":"March 11","l":"https://en.wikipedia.org/wiki/Mario_Party_9","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2241.jpg","s":"Grab your friends and family and captain the crew to victory!\n\nThe party is back and bigger than ever in the Mario Party 9 game for Wii, featuring all-new ways to play! For the first time in the franchise, boss battles crash the party and challenge players to compete to defeat a common enemy. In addition, players now travel across stages together in a vehicle towards a common goal - overcoming obstacles, battling bosses, and collecting Mini Stars stolen by Bowser and his minions. Featuring 80 new minigames, adventurous new stages, and all-new ways to play that blend cooperative and competitive action for up to four players*, Mario Party 9 is the perfect way to get the party started.\n\n-For the first time in the Mario Party franchise, each stage culminates in a Boss Battle. Collectively, players must combine their strength to defeat classic foes such as Bowser and King Boo while still playing competitively to boost their own individual scores.\n\n-In another first for the series, players ride across stages together in special vehicles. Players take turns as Captain of the vehicle by hitting Dice Blocks to move the party forward, hoping to land on lucky spaces. The vehicles also help to streamline game play and keep everyone involved in the action.\n\n-Unique Captain Events on each stage give players a new way to change the shape of the game.\n\n-In Mario Party 9, each themed stage has a clear destination point but with multiple paths along the way, so no two games will play the same. From Toad Road to Boo’s Horror Castle, players will encounter a wide variety of familiar Mario franchise elements in new environments that can be enjoyed solo or with friends.\n\n-Includes 80 outrageous new minigames that find players making pizzas, escaping haunted mansions, and racing snowmobiles.\n\n-No time to play through an entire stage? New minigame modes let players enjoy the action in smaller chunks of time. They can hone their skills at any minigame in Free Play mode or try the Extras mode that includes Goomba Bowling and the puzzle-based Castle Clearout.\n\n-Every time they play, players can earn Party Points that are used to unlock special items and features.\n\n* Additional accessories are required for multiplayer game play and are sold separately."},{"t":"Mario Tennis Open","p":["Nintendo 3DS"],"r":"May 20","l":"https://en.wikipedia.org/wiki/Mario_Tennis_Open"},{"t":"Mark of the Ninja","p":["Windows","Xbox 360"],"u":"Microsoft Studios","g":"Action, Adventure, Indie","r":"October 16, 2012","l":"https://en.wikipedia.org/wiki/Mark_of_the_Ninja","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2sfv.jpg","s":"In Mark of the Ninja, you'll know what it is to truly be a ninja. You must be silent, agile and clever to outwit your opponents in a world of gorgeous scenery and flowing animation. Marked with cursed tattoos giving you heightened senses, every situation presents you with options."},{"t":"Marvel Avengers Alliance","p":["Facebook","iOS","Android"],"d":"Offbeat Creations","u":"Playdom","g":"Role-playing","r":"March 1, 2012","l":"https://en.wikipedia.org/wiki/Marvel_Avengers_Alliance"},{"t":"Marvel Avengers: Battle for Earth","p":["Xbox 360","Wii U"],"r":"October 30"},{"t":"Marvel vs. Capcom 2: New Age of Heroes","p":["iOS"],"r":"April 25"},{"t":"Marvel vs. Capcom Origins","p":["PlayStation Network","Xbox 360"],"r":"September 25","l":"https://en.wikipedia.org/wiki/Marvel_vs._Capcom_(series)#Marvel_vs._Capcom_Origins"},{"t":"Mass Effect 3","p":["Xbox 360","PlayStation 3","Windows"],"u":"Electronic Arts","g":"Shooter, Role-playing (RPG), Strategy, Adventure","r":"March 6, 2012","l":"https://en.wikipedia.org/wiki/Mass_Effect_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1x7q.jpg","s":"Mass Effect 3 is an action role-playing game in which Commander Shepard leads a final campaign against the Reapers, a machine race that has invaded Earth and is conquering civilizations across the galaxy. Players recruit squad members from various species and classes, forge alliances, and make choices that determine which characters survive. Combat features squad-based tactics with combinable biotic and tech powers, blind fire, and enhanced melee attacks.\n\nThe game includes a cooperative multiplayer mode where up to four players fight waves of enemies to liberate conflict zones. Progress in multiplayer contributes to war preparedness in the single-player campaign. New and returning squad members join Shepard's team, including soldier James Vega and EDI, an AI in a physical body."},{"t":"Mass Effect 3: From Ashes","p":["Windows","Xbox 360","PlayStation 3","Wii U"],"d":"BioWare","u":"Electronic Arts","g":"Action role-playing, third-person shooter","r":"March 6, 2012","l":"https://en.wikipedia.org/wiki/Mass_Effect_3:_From_Ashes"},{"t":"Mass Effect 3: Leviathan","p":["Windows","PlayStation 3","Xbox 360"],"d":"BioWare","u":"Electronic Arts","g":"Action role-playing, third-person shooter","r":"August 28, 2012","l":"https://en.wikipedia.org/wiki/Mass_Effect_3:_Leviathan"},{"t":"Mass Effect 3: Omega","p":["Windows","PlayStation 3","Xbox 360"],"d":"BioWare","u":"Electronic Arts","g":"Action role-playing, third-person shooter","r":"November 27, 2012","l":"https://en.wikipedia.org/wiki/Mass_Effect_3:_Omega"},{"t":"Mass Effect 3: Special Edition","p":["Wii U"],"r":"November 18","l":"https://en.wikipedia.org/wiki/Mass_Effect_3"},{"t":"Mass Effect Infiltrator","p":["iOS","Android"],"r":"March 6","l":"https://en.wikipedia.org/wiki/Mass_Effect_Infiltrator"},{"t":"Mass Effect Trilogy","p":[],"l":"https://en.wikipedia.org/wiki/Mass_Effect_Trilogy"},{"t":"Max Payne 3","p":["PlayStation 3","Xbox 360","Windows"],"g":"Shooter","r":"May 15","l":"https://en.wikipedia.org/wiki/Max_Payne_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2mjo.jpg","s":"Max Payne 3 is a third-person shooter in which the player assumes the role of its titular character, Max Payne. A new feature to the series, introduced in Max Payne 3, is the cover system, which allows players to gain a tactical advantage, and avoid taking damage from enemies. To progress through the linear story, players take on enemies throughout levels. The game features interactive cutscenes which transition seamlessly into continuing gameplay; there are no loading screens across gameplay and cutscenes."},{"t":"Max Payne Mobile","p":["iOS"],"r":"April 12","l":"https://en.wikipedia.org/wiki/Max_Payne_(video_game)"},{"t":"McDroid","p":[],"d":"Elefantopia","g":"Tower defense","l":"https://en.wikipedia.org/wiki/McDroid"},{"t":"McPixel","p":["Windows","macOS","Linux","iOS","Android"],"d":"Sos Sosowski","g":"Puzzle","r":"June 25, 2012","l":"https://en.wikipedia.org/wiki/McPixel","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co21cd.jpg","s":"McPixel is a save-the-day guy that you guide through 100 short challenges in an old-school point'n'click fashion. The goal in each challenge is to prevent stuff from blowing up using available tools! You have only 20 seconds to save the day! Think quick!"},{"t":"Mecho Wars","p":["PlayStation Network"],"r":"January 10","l":"https://en.wikipedia.org/wiki/Mecho_Wars"},{"t":"Medal of Honor: Warfighter","p":["Windows","PlayStation 3","Xbox 360"],"g":"Shooter","r":"October 23","l":"https://www.igdb.com/games/medal-of-honor-warfighter","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2so4.jpg","s":"A direct sequel to EA's 2010 franchise reboot, Medal of Honor: Warfighter once again puts Xbox 360 gamers in the role of elite Tier 1 operators as they battle the world's most dangerous terrorists in places like the Philippines, Bosnia, and Somalia. The single-player story follows the life of Tier 1 soldier Preacher as he struggles to readjust to civilian life, only to have his world rocked when a massive PETN bomb goes off on U.S. soil. Players then join familiar characters Stump, Mother, and Voodoo as they attempt to track down the source of the explosives.\n\nThough the game is still built on EA DICE's Frostbite 2 engine, Danger Close Games handled all development of Warfighter, including the new Fireteam multiplayer mode in which two players join forces to share health and ammo during battle. Gamers can select special Tier 1 soldiers from ten different countries, including Germany, South Korea, Russia, and three different branches of the U.S. military, and then choose from the Assault, Sniper, Demolitions, Point Man, Heavy Gunner, and Spec Ops character classes. As many as 20 players can compete across eight different maps in a variety of modes, including Combat Mission, Team Deathmatch, and Sector Control."},{"t":"Mega Run","p":["iOS","Android","Windows Phone"],"d":"Get Set Games","r":"May 29, 2012","l":"https://en.wikipedia.org/wiki/Mega_Run"},{"t":"Men of War: Condemned Heroes","p":["Windows"],"r":"April 12"},{"t":"Metal Gear Solid HD Collection","p":["PlayStation Vita"],"r":"June 12","l":"https://en.wikipedia.org/wiki/Metal_Gear_Solid_HD_Collection"},{"t":"Metal Gear Solid: Snake Eater 3D","p":["Nintendo 3DS"],"u":"Konami","r":"February 21"},{"t":"Metal Gear Solid: Social Ops","p":["iOS","Android"],"d":"GREE","u":"Konami","g":"Action, stealth","r":"December 6, 2012","l":"https://en.wikipedia.org/wiki/Metal_Gear_Solid:_Social_Ops","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3dmq.jpg","s":"Metal Gear Solid: Social Ops (officially abbreviated MGS SOP) was a 3D mobile game. It was released exclusively in Japan for the iPhone and Android smartphones on December 6, 2012. The game involved gameplay and re-enactment from the games Metal Gear Solid 3: Snake Eater and Metal Gear Solid: Peace Walker. Social Ops was similar to the Metal Gear Acid series in terms of character movement and its use of items and weapons via trading cards.\n\nThe trading cards involved characters and enemies from Metal Gear, Metal Gear 2: Solid Snake. Metal Gear Solid, Metal Gear Solid 2: Sons of Liberty, Metal Gear Solid 3: Snake Eater, Metal Gear Solid 4: Guns of the Patriots, Metal Gear Solid: Peace Walker, Metal Gear Rising: Revengeance and Metal Gear Solid V: Ground Zeroes. Besides cards relating to the Metal Gear series, there were also cards related to Zone of the Enders, another series of games by Kojima Productions and collaboration cards with other GREE game series such as Cerberus Jihad and Dragon Collection.\n\nThe game's official website was launched on August 30, 2012.\n\nOn October 2013, Konami announced via the Social Ops website that the servers of the game would come to an end. The final mission was downloadable on October 31, 2013 til November 13, 2013. The game was then removed from being downloaded on December 13, 2013 and the service ended for good on January 31, 2014. All players unused credits from the \"Metal Gear Solid Coin\" bank was refunded."},{"t":"Metal Slug 3","p":["iOS"],"r":"July 12","l":"https://en.wikipedia.org/wiki/Metal_Slug_3"},{"t":"Miasmata","p":["Windows"],"d":"IonFX","u":"IonFX Studios","g":"Adventure game, survival","r":"November 28, 2012","l":"https://en.wikipedia.org/wiki/Miasmata","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobx12.jpg","s":"Miasmata is a first-person survival/adventure game, developed from the ground-up by brothers Joe and Bob Johnson. You play as Robert Hughes, a plague-stricken scientist on a journey to discover a cure. Your adventure begins on the shores of a remote and mysterious island."},{"t":"MIB: Alien Crisis","p":["PlayStation 3","Xbox 360","Wii"],"r":"May 22"},{"t":"Michael Jackson: The Experience","p":["PlayStation Vita","macOS"],"r":"February 15"},{"t":"Michael Phelps: Push the Limit","p":["Xbox 360"],"r":"October 11"},{"t":"Micro Miners","p":["iOS","Android"],"d":"BonusLevel.org","u":"BonusLevel.org","g":"Puzzle","r":"November 15, 2012","l":"https://en.wikipedia.org/wiki/Micro_Miners"},{"t":"Microsoft Flight","p":["Windows"],"r":"February 29","l":"https://en.wikipedia.org/wiki/Microsoft_Flight"},{"t":"Microsoft Mahjong","p":["Windows","iOS","Android"],"d":"Arkadium, Microsoft Casual Games","u":"Microsoft Studios","g":"Puzzle","r":"October 26, 2012","l":"https://en.wikipedia.org/wiki/Microsoft_Mahjong","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6ec9.jpg","s":"Microsoft Mahjong (formerly Mahjong Titans and Taipei) is a computer game version of mahjong solitaire published by Microsoft. The version titled Mahjong Titans was developed by Oberon Games and included in Windows Vista and Windows 7 (except Starter and Home Basic editions). It takes advantage of the new graphical user interface (GUI) of Windows Vista, and includes features such as tile set and background choices. (In Windows Vista build 5219, the game was known as Shanghai Solitaire.) The game did not make it to Windows 8; however, a standalone version, developed by Arkadium and published by Microsoft Studios, can be downloaded from the Windows Store free of charge.\n\nAn older version of the game was known as Taipei and was bundled in Microsoft Entertainment Pack 1 and Best of Microsoft Entertainment Pack. That version included 32767 possible configurations."},{"t":"Microsoft Solitaire Collection","p":["Windows","Browser"],"d":"Microsoft Casual Games","u":"Xbox Game Studios","g":"Card game","r":"October 26, 2012","l":"https://en.wikipedia.org/wiki/Microsoft_Solitaire_Collection","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co28mq.jpg","s":"Microsoft Solitaire Collection is a video game included with Windows 10. It replaces Solitaire, FreeCell and Spider Solitaire included with the previous versions of Windows. It also adds Pyramid and TriPeaks to Windows for the first time and introduces new daily challenges and themes."},{"t":"Middens","p":["Windows","macOS"],"r":"September 9","l":"https://en.wikipedia.org/wiki/Middens_(video_game)"},{"t":"Middle Manager of Justice","p":["iOS"],"r":"December 13","l":"https://en.wikipedia.org/wiki/Middle_Manager_of_Justice"},{"t":"Midway Arcade Origins","p":["PlayStation 3","Xbox 360"],"r":"November 6","l":"https://en.wikipedia.org/wiki/Midway_Arcade_Origins"},{"t":"Mighty Switch Force! Hyper Drive Edition","p":["Wii U"],"r":"November 18","l":"https://en.wikipedia.org/wiki/Mighty_Switch_Force!"},{"t":"Mikey Shorts","p":["iOS","Android"],"d":"BeaverTap Games","u":"Noodlecake Studios","g":"Platform","r":"August 23, 2012","l":"https://en.wikipedia.org/wiki/Mikey_Shorts","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coc7dr.jpg","s":"RUN, JUMP, and SLIDE through the land to help Mikey Shorts rescue the people! Collect coins to buy fun disguises along the way!"},{"t":"Miku Flick","p":["iOS"],"d":"Sega, Crypton Future Media","u":"Sega","g":"Rhythm game","r":"March 9, 2012","l":"https://en.wikipedia.org/wiki/Miku_Flick","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4ome.jpg","s":"Miku Flick is a rhythm game and a spin-off of the Hatsune Miku: Project DIVA series of Vocaloid rhythm games. As the game is a spin-off from the Project Diva series, its gameplay differs greatly from the original series. Players can pick their songs using a Cover Flow system from a selection of 13 songs all sung by Hatsune Miku. This is the first game in the series to not feature any other Vocaloids apart from Hatsune Miku. The game has 10 tiles, arranged in a 3×3 grid with the last column having a 4th tile at the bottom. Each of these tiles has a hiragana Lyric on them, when indicated you are required to flick the tile in the indicated direction. Timing is as essential as the original game as the game still retains the points system as well as accuracy scoring system as the original series."},{"t":"Miku Flick/02","p":["iOS"],"d":"Sega, Crypton Future Media","u":"Sega","g":"Rhythm game","r":"August 10, 2012","l":"https://en.wikipedia.org/wiki/Miku_Flick/02","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4omg.jpg","s":"Miku Flick/02 is a rhythm game, a sequel to Miku Flick, and a spin off of the Hatsune Miku: Project DIVA series of Vocaloid rhythm games. The game will retain the primary gameplay of its prdecessor whereby the game has 10 tiles, arranged in a 3x3 grid with the middle column having a 4th tile at the bottom. Each of these tiles has a hiragana Lyric on them, when indicated you are required to flick the tile in the indicated direction. Unlike its predecessor though, the game will feature vocaloids other than Hatsune Miku including Kagamine Len, Kagamine Rin and Megurine Luka as well as duet songs whereby two vocaloids would sing together for a song. The game will also include a new \"Extreme\" difficulty mode, which will provide players with a difficulty between the \"Hard\" Mode and \"Break the Limit\" Mode of the original."},{"t":"Million Arthur","p":[],"l":"https://en.wikipedia.org/wiki/Million_Arthur"},{"t":"Minecraft","p":["Xbox 360"],"r":"May 9","l":"https://en.wikipedia.org/wiki/Minecraft"},{"t":"Minecraft legacy console editions","p":[],"l":"https://en.wikipedia.org/wiki/Minecraft_legacy_console_editions"},{"t":"Miner Wars 2081","p":["Windows"],"r":"November 28","l":"https://en.wikipedia.org/wiki/Miner_Wars_2081"},{"t":"Miner Wars Arena","p":["Windows","macOS"],"d":"Keen Software House","g":"Action","r":"August 28, 2012","l":"https://en.wikipedia.org/wiki/Miner_Wars_Arena","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2qp4.jpg","s":"It is the year 2090. Our Solar System is in the aftermath of a total political breakdown. Humanity is fighting over resources in asteroids.Gameplay\nTake control of a mining spaceship, hack your way through asteroids, and crush your enemies in a fully destructible environment! Compete against AI-controlled bots or prepare for the ultimate death-match against another human player (2 players can play on 1 PC)."},{"t":"Mini Ninjas Adventures","p":["Xbox 360"],"r":"June 29","l":"https://en.wikipedia.org/wiki/Mini_Ninjas#Mini_Ninjas_Adventures"},{"t":"MLB 12: The Show","p":["PlayStation 3","PlayStation Vita"],"r":"March 6"},{"t":"Mobile Suit Gundam AGE","p":["PlayStation Portable"],"d":"Level-5","u":"Namco Bandai Games","g":"Action role-playing game, hack and slash, Mecha, Military Science Fiction","r":"August 30, 2012","l":"https://en.wikipedia.org/wiki/Mobile_Suit_Gundam_AGE_(video_game)"},{"t":"Mobile Suit Gundam Unicorn","p":["PlayStation 3"],"d":"From Software","u":"Namco Bandai Games","g":"Action","r":"March 8, 2012","l":"https://en.wikipedia.org/wiki/Mobile_Suit_Gundam_Unicorn_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4tg9.jpg","s":"Mobile Suit Gundam Unicorn is the first Gundam game to exclusively tell the story of the hunt for Laplace's Box. In Unicorn Mode the story is told from the perspectives of Banagher Links, Riddhe Marcenas, and Marida Cruz. Each is playable for major combat operations they are involved in, while the space between combat is told as narrated cutscenes. In battle each mobile suit has access to a melee attack, a primary ranged attack, and additional ranged weapons based on its design. All ranged weapons have limited ammo that can not be replenished, as well as an alternate fire mode. Boosting and dashing can be used to avoid fire or clear distance between targets, but depletes a fuel gauge. Bringing an enemy mobile suit to a disabled state with weak attacks allows the player's MS to cannibalize it for armor and fuel replenishment."},{"t":"Modern Combat 4: Zero Hour","p":["iOS","Android"],"r":"December 6"},{"t":"ModNation Racers: Road Trip","p":["PlayStation Vita"],"r":"February 22"},{"t":"Mole Baby","p":["iOS"],"d":"Taomee","u":"Taomee","g":"Simulation","r":"February 16, 2012","l":"https://en.wikipedia.org/wiki/Mole_Baby"},{"t":"Mole Kart","p":["iOS","Android"],"d":"Shanghai Shengran Information Technology","u":"Shanghai Shengran Information Technology","g":"Racing","r":"January 12, 2012","l":"https://en.wikipedia.org/wiki/Mole_Kart"},{"t":"Monster Retsuden Oreca Battle","p":["Arcade"],"l":"https://en.wikipedia.org/wiki/Monster_Retsuden_Oreca_Battle","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coarc8.jpg","s":"A trading card arcade game that utilizes various Konami characters."},{"t":"Monsters, Inc. Run","p":[],"l":"https://en.wikipedia.org/wiki/Monsters,_Inc._Run"},{"t":"Montopia","p":["iOS","Android"],"d":"Zynga Japan","u":"Zynga","g":"role-playing game","r":"September 12, 2012","l":"https://en.wikipedia.org/wiki/Montopia"},{"t":"Mortal Kombat: Arcade Kollection","p":["Windows"],"r":"February 2","l":"https://en.wikipedia.org/wiki/Mortal_Kombat"},{"t":"Mortal Kombat: Komplete Edition","p":["PlayStation 3","Xbox 360","PlayStation Vita"],"r":"February 28"},{"t":"MotorStorm: RC","p":["PlayStation 3","PlayStation Vita"],"r":"March 6"},{"t":"Mugen Souls","p":["PlayStation 3"],"d":"Compile Heart","u":"Compile Heart, NIS America, NIS Europe, Ghostlight","g":"Role-playing","r":"March 22, 2012","l":"https://en.wikipedia.org/wiki/Mugen_Souls","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2fuo.jpg","s":"Mugen Souls is an RPG developed by Compile Heart with collaboration from GCREST. The main protagonist of Mugen Souls, Chou-Chou, plans to conquer the universe by subjugating the seven worlds it comprises, as she thinks the planets look pretty. Gameplay revolves around exploration and turn-based, open-field combat, and the game also includes mini games and customization. Due to the questionable nature of the game's portrayal of child protagonists, certain aspects of the western release have been edited and some mini-games have been disabled."},{"t":"Mutant Mudds","p":["Nintendo 3DS","Windows","iOS"],"r":"January 26","l":"https://en.wikipedia.org/wiki/Mutant_Mudds"},{"t":"Mutant Storm Reloaded","p":["Windows"],"r":"March 21","l":"https://en.wikipedia.org/wiki/Mutant_Storm_Reloaded"},{"t":"My Little Pony: Magic Princess","p":["iOS","Android","Windows","Windows Phone"],"d":"Gameloft","u":"Gameloft","g":"City-building","r":"November 8, 2012","l":"https://en.wikipedia.org/wiki/My_Little_Pony:_Magic_Princess","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6e0n.jpg","s":"Saddle up for adventure with Twilight Sparkle & friends!\nAfter being locked away in the moon for centuries, Nightmare Moon is set free and spreading night across Ponyville! Only Twilight Sparkle and her friends can free Ponyville from her grasp and bring light and friendship back to the land. Help them rebuild the town and reach their dreams in exciting quests!"},{"t":"My Singing Monsters","p":["Android","iOS"],"g":"Music, Simulator, Strategy","r":"August 22","l":"https://en.wikipedia.org/wiki/My_Singing_Monsters","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2y7i.jpg","s":"Welcome to My Singing Monsters! Collect, breed, and listen to your monsters sing. You have never seen a game like this before!\n\nPopulate an island and watch what happens. Create unique havens by landscaping and arranging your creatures. Name them, feed them, make them happy; each monster is loaded with personality. You’ll experience game play and music as never before with this innovative technology!"},{"t":"Mystic Chronicles","p":["PlayStation Portable","iOS"],"d":"Kemco","u":"Natsume Inc.","g":"Role-playing video game","r":"January 19, 2012","l":"https://en.wikipedia.org/wiki/Mystic_Chronicles","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2npz.jpg","s":"Mystic Chronicles is a Japanese role-playing video game developed by Kemco. While initially released as Fantasy Chronicles for the iOS, the name was retitled as a result of Natsume providing a new English translation for its release on the PlayStation Portable, released in North America on July 16, 2013.\n\nThe game plays as a traditional Japanese role-playing video game. In the game, the player navigates a character through a fantasy would, interacing with non-playable characters and fighting enemies. When engaging enemies, the game utilizes a turn based battle system reminiscent of ones found in the Dragon Quest series of games."},{"t":"N.O.V.A. 3","p":["iOS"],"r":"May 10","l":"https://en.wikipedia.org/wiki/N.O.V.A._3"},{"t":"Naka no Hito nado Inai! Tokyo Hero Project","p":[],"l":"https://en.wikipedia.org/wiki/Naka_no_Hito_nado_Inai!_Tokyo_Hero_Project"},{"t":"Namco Arcade","p":["iOS"],"d":"Namco Bandai Games","u":"Namco Bandai Games","g":"Various","r":"January 26, 2012","l":"https://en.wikipedia.org/wiki/Namco_Arcade"},{"t":"Nancy Drew: The Deadly Device","p":["Windows","macOS"],"r":"October 23"},{"t":"Nancy Drew: Tomb of the Lost Queen","p":["Windows","macOS"],"r":"May 8"},{"t":"Nano Assault Neo","p":["Wii U"],"r":"November 18","l":"https://en.wikipedia.org/wiki/Nano_Assault_Neo"},{"t":"Naruto Shippuden: Ultimate Ninja Storm Generations","p":["PlayStation 3","Xbox 360"],"g":"Fighting","r":"March 13","l":"https://www.igdb.com/games/naruto-shippuden-ultimate-ninja-storm-generations","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1u98.jpg","s":"The title will power the series into the future by revolutionizing online play and ramping up the number of playable and support characters far beyond any NARUTO game in the wildly popular franchise. Players will compete in a variety of online battle modes with their favorite NARUTO characters, including Naruto and Sasuke. NARUTO fans have been waiting to see more of Zabuza and Haku since the launch of the original Manga, and now they will have their chance!"},{"t":"NASCAR The Game: Inside Line","p":["PlayStation 3","Wii","Xbox 360"],"r":"November 6"},{"t":"Natural Selection 2","p":["Windows"],"g":"Shooter, Puzzle, Real Time Strategy (RTS), Strategy, Indie","r":"October 31","l":"https://en.wikipedia.org/wiki/Natural_Selection_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1x8r.jpg","s":"Natural Selection 2 is an immersive, multiplayer shooter that pits aliens against humans in a strategic and action-packed struggle for survival. It seamlessly combines shooter and RTS/strategy gameplay."},{"t":"Naughty Bear: Panic in Paradise","p":["PlayStation Network","Xbox 360"],"r":"October 10","l":"https://en.wikipedia.org/wiki/Naughty_Bear#Sequel"},{"t":"Naval War: Arctic Circle","p":["Windows"],"r":"April 10"},{"t":"NBA 2K13","p":["Windows","PlayStation 3","Xbox 360","PlayStation Portable","Wii"],"u":"2K","g":"Simulator, Sport, Strategy","r":"October 2, 2012","l":"https://en.wikipedia.org/wiki/NBA_2K13","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22tj.jpg","s":"With more than 5 million copies sold worldwide and more than 25 Sports Game of the Year awards won, NBA 2K12 was another monster release for the biggest NBA video game simulation franchise in the world. This year, 2K Sports has joined forces with the legendary JAY Z as Executive Producer to transcend sports video games and take virtual hardwood to the next level. Featuring an enhanced MyCAREER mode and all-new gameplay features, NBA 2K13 will let gamers pit the best players in NBA history against the new dynasty of talent, including the much-debated matchup between the 2012 U.S. Men's National Team and the 1992 \"Dream Team.\""},{"t":"NBA Baller Beats","p":["Xbox 360"],"r":"September 11","l":"https://en.wikipedia.org/wiki/NBA_Baller_Beats"},{"t":"NCAA Football 13","p":["PlayStation 3","Xbox 360"],"r":"July 10","l":"https://en.wikipedia.org/wiki/NCAA_Football_13"},{"t":"Need for Speed: Most Wanted","p":["Windows","Xbox 360","PlayStation 3","PlayStation Vita","iOS","Android"],"g":"Racing, Adventure","r":"October 30","l":"https://www.igdb.com/games/need-for-speed-most-wanted-53b9fef3-adb4-41a0-8ca0-ffcbb0060467","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20a5.jpg","s":"Need for Speed: Most Wanted takes on the gameplay style of the first Most Wanted title in the Need for Speed franchise. Most Wanted allows players to select one car and compete against other racers in three types of events: Sprint races, which involves traveling from one point of the city to another, Circuit races, each having two or three laps total and Speed runs, which involve traversing through a course in the highest average speed possible. There is also the Ambush races, which start with the player surrounded by cops and tasked to evade their pursuit as quickly as possible."},{"t":"Nemo's Reef","p":["iOS","Android","Windows Phone"],"d":"Disney Mobile","g":"Simulator, Strategy","r":"December 20, 2012","l":"https://en.wikipedia.org/wiki/Nemo's_Reef","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/ucwyijiapjhunugmhkar.jpg","s":"Players Build their own reef in Nemo's Reef.\n\nNemo's Reef was a city-building release on iOS and Android based on the 2003 Disney/Pixar animated feature film, Finding Nemo. The app was released in tie-in with the 2012 home video re-release of Finding Nemo.\n\nThe game was officially removed on June 1, 2017 from application stores after it was announced that the game would be no longer available to download on May 31, 2017. The game's servers were permanently closed on June 30 on that same year, one year after the theatrical release of Finding Dory."},{"t":"NeverDead","p":["PlayStation 3","Xbox 360"],"r":"January 31","l":"https://en.wikipedia.org/wiki/NeverDead"},{"t":"New Little King's Story","p":["PlayStation Vita"],"r":"October 2","l":"https://en.wikipedia.org/wiki/Little_King%27s_Story"},{"t":"New Super Mario Bros. 2","p":["Nintendo 3DS"],"g":"Platform, Adventure","r":"August 19","l":"https://en.wikipedia.org/wiki/New_Super_Mario_Bros._2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobaah.jpg","s":"New Super Mario Bros. 2 is a side-scrolling 2.5D action-adventure platform game for the Nintendo 3DS. As the direct sequel to New Super Mario Bros., it is an indirect follow-up to New Super Mario Bros. Wii. The game's main focus is on coins, with the primary goal being to collect one million. To reach the goal, the game includes many new items to aid the player, such as the Gold Flower, which turns Mario into Gold Mario."},{"t":"New Super Mario Bros. U","p":["Wii U"],"g":"Platform, Adventure","r":"November 18","l":"https://en.wikipedia.org/wiki/New_Super_Mario_Bros._U","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co21ts.jpg","s":"New Super Mario Bros. U is a side-scrolling 2.5D platform game, and the fourth and latest installment in the New Super Mario Bros. series. As the sequel to New Super Mario Bros. Wii, the game is a follow-up game of New Super Mario Bros. 2. It uses new, more detailed background styles and models and introduces the Flying Squirrel power-up, acquired by Mario and his friends from an item called the Super Acorn, as well as utilizing the Wii U GamePad in Boost Mode. In addition to the core campaign, there are also challenge modes."},{"t":"Nexuiz","p":["Xbox 360","Windows"],"r":"February 29","l":"https://en.wikipedia.org/wiki/Nexuiz_(2012_video_game)"},{"t":"NFL Blitz","p":["PlayStation Network","Xbox 360"],"r":"January 4","l":"https://en.wikipedia.org/wiki/NFL_Blitz_(2012_video_game)"},{"t":"NHL 13","p":["PlayStation 3","Xbox 360"],"r":"September 11","l":"https://en.wikipedia.org/wiki/NHL_13"},{"t":"Nicktoons MLB 3D","p":["Nintendo 3DS"],"r":"March 6","l":"https://en.wikipedia.org/wiki/Nicktoons_MLB"},{"t":"Nights into Dreams HD","p":["PlayStation Network","Xbox 360","Windows"],"r":"October 2","l":"https://en.wikipedia.org/wiki/Nights_into_Dreams...#HD_version"},{"t":"NightSky","p":["Nintendo 3DS"],"r":"October 25","l":"https://en.wikipedia.org/wiki/Nicklas_Nygren#NightSky"},{"t":"Nihilumbra","p":["iOS"],"d":"BeautiFun Games","g":"Puzzle-platform","r":"June 27, 2012","l":"https://en.wikipedia.org/wiki/Nihilumbra","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co27n2.jpg","s":"Nihilumbra is played as a standard platform game, by controlling Born as he walks and jumps across the game's levels. There are multiple enemies that the player needs to avoid since, at first, there is no way to defeat them. The game is divided into the five worlds that Born explores. In each of them, the player is granted a new colour, with which the player can paint on the terrain (by touching the screen) to modify the behaviour of the environment."},{"t":"Nike+ Kinect Training","p":["Xbox 360"],"r":"October 30","l":"https://en.wikipedia.org/wiki/Nike%2B_Kinect_Training"},{"t":"Ninja Gaiden 3","p":["PlayStation 3","Xbox 360"],"g":"Hack and slash/Beat 'em up, Adventure","r":"March 20","l":"https://en.wikipedia.org/wiki/Ninja_Gaiden_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5ryd.jpg","s":"Ninja Gaiden 3 is the first main entry in the modern Ninja Gaiden series not to be directed by former Team Ninja head Tomonobu Itagaki. NG3 features new game mechanics, a focus on consequence and 8-player online modes."},{"t":"Ninja Gaiden 3: Razor's Edge","p":["Wii U"],"g":"Hack and slash/Beat 'em up, Adventure","r":"November 18","l":"https://www.igdb.com/games/ninja-gaiden-3-razor-s-edge","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob1ty.jpg","s":"Ninja Gaiden 3: Razor's Edge is an enhanced port of Ninja Gaiden 3 that includes all downloadable content from the original title, as well as additional enhancements made to improve the game. The game can be considered an equivalent to the Ninja Gaiden Sigma games, as it enhances the original title."},{"t":"Ninja Gaiden Sigma Plus","p":["PlayStation Vita"],"r":"February 22","l":"https://en.wikipedia.org/wiki/Ninja_Gaiden_Sigma"},{"t":"Nintendo Land","p":["Wii U"],"g":"Shooter, Platform, Puzzle, Racing, Adventure, Arcade","r":"November 18","l":"https://en.wikipedia.org/wiki/Nintendo_Land","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1p9c.jpg","s":"Nintendo Land is a fun and lively virtual theme park filled with attractions based on popular Nintendo game worlds. Explore the Nintendo Land Plaza as your Mii character, and play in park attractions featuring unique and innovative gameplay made possible by the Wii U GamePad controller. Enjoy team, competitive, and solo gameplay experiences for up to five players!"},{"t":"Node.Hack","p":[],"l":"https://en.wikipedia.org/wiki/Node.Hack"},{"t":"Nutty Fluffies Rollercoaster","p":["iOS"],"d":"RedLynx","u":"Ubisoft","g":"Side-scroller","r":"November 1, 2012","l":"https://en.wikipedia.org/wiki/Nutty_Fluffies_Rollercoaster"},{"t":"Oddworld: Munch's Oddysee","p":["PlayStation Network"],"r":"December 24"},{"t":"Oddworld: Stranger's Wrath","p":["PlayStation Vita"],"r":"December 18"},{"t":"Of Orcs and Men","p":["Windows","PlayStation 3","Xbox 360"],"g":"Role-playing (RPG)","r":"October 11","l":"https://en.wikipedia.org/wiki/Of_Orcs_and_Men","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ph5.jpg","s":"Of Orcs and Men first puts the player into the role of an elite Orc soldier, Arkail, from the legendary legion of Bloodjaws. The legion is a league of warriors deeply involved in the war between the Orcs and the Goblins on one side and their persecutors, Humankind, on the other. As a veteran warrior who has seen the most brutal of battles, the player is appointed by the Orc commander to complete a mission that could change the course of the war, to kill the Emperor himself, the man responsible for the bloodshed. A Goblin, Styx, soon joins the player, an unlikely but indispensable ally."},{"t":"Offspring Fling","p":["Windows","macOS","Linux"],"d":"Kyle Pulver","g":"Puzzle-platform","r":"March 30, 2012","l":"https://en.wikipedia.org/wiki/Offspring_Fling"},{"t":"Oil Rush","p":["Windows","Linux","macOS"],"r":"January 25","l":"https://en.wikipedia.org/wiki/Oil_Rush"},{"t":"One Piece Grand Collection","p":["Android","iOS"],"d":"Namco Bandai Games","u":"Namco Bandai Games","g":"Social-network","l":"https://en.wikipedia.org/wiki/One_Piece_Grand_Collection"},{"t":"One Piece: Pirate Warriors","p":["PlayStation 3"],"r":"September 25"},{"t":"One Piece: Romance Dawn","p":["PlayStation Portable"],"d":"Three Rings","u":"Namco Bandai Games","g":"RPG","r":"December 20, 2012","l":"https://en.wikipedia.org/wiki/One_Piece:_Romance_Dawn","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6o3g.jpg","s":"The game is an RPG; it uses turn-based battles and action commands that help guide the player. The player commands the protagonist Luffy and other characters that are in his crew. The characters level up, and the player can strengthen attacks by obtaining points. All characters and enemies are from the One Piece series and play the same roles as seen in the source material. Cutscenes are told in a manga style."},{"t":"Oniken","p":["Windows","macOS","Linux"],"d":"Joymasher","u":"Joymasher","g":"Action, platform","r":"June 21, 2012","l":"https://en.wikipedia.org/wiki/Oniken","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co26c4.jpg","s":"When a global war nearly decimated humankind, an evil military organization called Oniken takes advantage of the situation to dominate and oppress the few remaining survivors. Even though any resistance to this organization seemed hopeless, a small rebel movement organizes strikes against Oniken. One day, a ninja mercenary named Zaku offers his services to the resistance for unknown reasons. His moves are lethal and now he is the resistance's only hope.\n\nOniken is an action platform game highly inspired by the 1980's, its games and its movies. You can see this not only in the graphics and sound design, but also in Oniken's story and difficulty.\n\nDon't Worry, You Will Die A Lot Of Times.\n\nEvery copy of Oniken comes with digital versions of the game manual and the original soundtrack.Features\nGraphics, sounds and difficulty from the 8-bit era\nCinematic cutscenes\nOver 18 boss fights\nSix missions, three stages each\nAn extra mission after you beat the game\nBoss rush mode\nNot difficult enough? Try the new HARDCORE MODE\nGlobal Leaderboards\nFull pixelated violence"},{"t":"Orcs Must Die! 2","p":["Windows"],"g":"Shooter, Platform, Strategy, Adventure, Indie","r":"July 30","l":"https://en.wikipedia.org/wiki/Orcs_Must_Die!_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/eksi5x5lmj3vh2z69ydl.jpg","s":"Orcs Must Die! 2 thrusts players and their friends back into battle against a terrifying mob of orcs and other monsters. With a redesigned spellbook, players will have a broader range of options to build a deadly arsenal of defenses. Investing hard-earned skulls in an enormous new upgrade system will allow players to cater to their favorite methods of burning, grinding, tossing, or dismembering orcs. \n \nOrcs Must Die! 2 begins days after the ending of the original game. With the rifts closed and the magical Order dead, the War Mage finds himself suddenly thrust into a new battle against the mindless orc mob. He has a powerful, if questionable, new companion in the Sorceress, an ex-War Mage responsible for the destruction of the Order."},{"t":"Order Up!!","p":["Nintendo 3DS"],"r":"June 12","l":"https://en.wikipedia.org/wiki/Order_Up!"},{"t":"Orgarhythm","p":["PlayStation Vita"],"r":"October 23","l":"https://en.wikipedia.org/wiki/Orgarhythm"},{"t":"Orion: Prelude","p":["Windows"],"d":"Spiral Game Studios","u":"Spiral Game Studios","g":"First-person shooter","r":"May 4, 2012","l":"https://en.wikipedia.org/wiki/Orion:_Prelude","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8udh.jpg","s":"ORION: Prelude' is an indie Sci-Fi shooter (FPS/TPS) that seamlessly blends together incredible visuals and addictive combat. It puts you and your friends together into intense, cinematic battles using some of the most incredible weaponry and amazing vehicles in which you must work or compete against one another to accomplish mission objectives, explore giant worlds and survive the devastating Dinosaur Horde."},{"t":"Out There Somewhere","p":["Windows","macOS"],"d":"MiniBoss","u":"MiniBoss, EQGAMES","g":"Puzzle-platform","l":"https://en.wikipedia.org/wiki/Out_There_Somewhere","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2iqg.jpg","s":"You play an explorer stranded on a dangerous alien planet. Low on fuel, your only hope for escape is to find the planet’s core in this incredibly clever action-puzzle-platformer."},{"t":"Outernauts","p":["Browser","iOS"],"d":"Insomniac Games","u":"Electronic Arts","g":"Role-playing, social network game","r":"July 2012","l":"https://en.wikipedia.org/wiki/Outernauts","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1zik.jpg","s":"Outernauts was an Adobe Flash social role-playing video game for Facebook. Developed by Insomniac Games, it is the developer's first social video game, as well as their first game for a non-Sony platform. The game is published by Electronic Arts and was released as an open beta in July 2012. It was announced by Insomniac Games that the game would no longer be available on Facebook from January 31, 2014 and would be ported to iOS. The game was shut down on February 1, 2016."},{"t":"Pac-Man Games","p":["iOS"],"r":"March 29","l":"https://en.wikipedia.org/wiki/Pac-Man_Games"},{"t":"Page Chronica","p":["PlayStation 3"],"r":"December 4"},{"t":"Painkiller: Hell & Damnation","p":["Windows"],"g":"Shooter","r":"October 31","l":"https://www.igdb.com/games/painkiller-hell-damnation","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1uyo.jpg","s":"Painkiller: Hell & Damnation is both remake and sequel of the first-person shooter video game Painkiller, developed by The Farm 51 and published by Nordic Games."},{"t":"Paper Mario: Sticker Star","p":["Nintendo 3DS"],"g":"Puzzle, Role-playing (RPG), Adventure","r":"November 11","l":"https://www.igdb.com/games/paper-mario-sticker-star","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1tfp.jpg","s":"A sticky situation has never been so fun! There's trouble afoot in the town of Decalburg, where the devious Bowser has disrupted the beloved Sticker Fest by causing the Sticker Comet to explode. Now Royal Stickers and pieces of the comet have been flung far and wide, and it's up to Mario and his ally Kersti to set things right by recovering them. This captivating hand-held adventure will have new and experienced fans of the Paper Mario series captivated as they navigate colorful 3D environments, defeat enemies, collect oodles of stickers and items and use them in a variety of fun ways."},{"t":"Papo & Yo","p":["PlayStation Network"],"g":"Platform, Puzzle, Adventure, Indie","r":"August 14","l":"https://en.wikipedia.org/wiki/Papo_%26_Yo","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1nc0.jpg","s":"A semi-autobiographical 3D puzzle platformer in which a boy named Quico is transported from his abusive home into a dreamlike favela where he has to lead an easygoing creature named Monster through the world with the help of his sister and Lula, his robotic doll, while protecting himself and his companions from Monster's frenzy fits brought on by an addiction to poison frogs."},{"t":"Party Place","p":["iOS","Android"],"d":"Zynga","g":"social network game","r":"December 6, 2012","l":"https://en.wikipedia.org/wiki/Party_Place"},{"t":"Party Wave","p":["iOS","Android"],"d":"Mistwalker","u":"Mistwalker","g":"Puzzle","r":"July 20, 2012","l":"https://en.wikipedia.org/wiki/Party_Wave","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7msz.jpg","s":"An Action Surfing Game Developed by Mistwalker.\nTotal of 50 stages! Don't forget the additional bonus stages and Arcade Mode, too.\nThere are two elements in playing Party Wave: paddling and surfing. For paddling, touch surfers and drag them to a spot where the surf breaks, while avoiding the obstacles such as dolphins and turtles. And for surfing, touch surfers to make them turn and jump to prevent wipeouts.\nLet's surf a wave with the surfing crowd and the board-riding dog, Skip, while getting help from three mermaid sisters and Hiso Alien, who provides valuable bonuses.\nParty Wave!"},{"t":"Pastry Panic","p":["iOS"],"r":"May 24","l":"https://en.wikipedia.org/wiki/Pastry_Panic"},{"t":"Payback 2","p":["Android","iOS"],"d":"Apex Designs Entertainment Ltd.","u":"Apex Designs Entertainment Ltd.","g":"Action","r":"October 4, 2012","l":"https://en.wikipedia.org/wiki/Payback_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co86zo.jpg","s":"Payback 2 includes everything from tank battles to high speed helicopter races to huge gang battles - but you really have to try it get a feel for how much variety there is, and we're adding more all the time!"},{"t":"Penny Arcade Adventures - Episode 3","p":["Windows","macOS"],"r":"June 25"},{"t":"Penny Arcade's On the Rain-Slick Precipice of Darkness 3 and 4","p":["Windows","macOS","Xbox 360","iOS"],"d":"Zeboyd Games","u":"Penny Arcade","g":"Role-playing","r":"June 25, 2012","l":"https://en.wikipedia.org/wiki/Penny_Arcade's_On_the_Rain-Slick_Precipice_of_Darkness_3_and_4"},{"t":"Persona 4 Arena","p":["PlayStation 3","Xbox 360"],"g":"Fighting, Role-playing (RPG), Adventure, Visual Novel","r":"August 7","l":"https://en.wikipedia.org/wiki/Persona_4_Arena","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co25v5.jpg","s":"Persona 4 Arena is a fighting video game developed for Japanese arcades and later ported to home consoles. Based on Atlus' Persona role-playing game series, Arena serves as a direct sequel to Persona 4 and features characters from its predecessor, Persona 3. Atlus wrote the story to the game while Arc System Works handled the gameplay."},{"t":"Persona 4 Golden","p":["PlayStation Vita"],"u":"Atlus","g":"Role-playing (RPG), Adventure","r":"June 14, 2012","l":"https://en.wikipedia.org/wiki/Persona_4#Persona_4_Golden","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1n1x.jpg","s":"Persona 4 Golden is an enhanced version of the role-playing game Persona 4, combining turn-based combat with daily life simulation. Players control a high school student who moves to the rural town of Inaba for one year and becomes involved in investigating a series of murders linked to a mysterious world inside television sets. Gameplay is divided between exploring randomly generated dungeons where players fight Shadows using summoned creatures called Personas, and navigating daily life by attending school, building friendships through Social Links, and developing character attributes.\n\nGolden adds new story content including the character Marie, additional Personas, online features, new difficulty settings, expanded voice acting, and additional animated cutscenes over the original PlayStation 2 release."},{"t":"Perspective","p":["Windows"],"d":"DigiPen Institute of Technology","u":"DigiPen Institute of Technology","g":"Platform, puzzle","r":"December 12, 2012","l":"https://en.wikipedia.org/wiki/Perspective_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8ctv.jpg","s":"A first-person puzzle game in which the player controls both a first-person character and a 2D character in a 3D environment. Shift the first-person viewpoint to alter the 2D character's world."},{"t":"Pets vs Orcs","p":[],"l":"https://en.wikipedia.org/wiki/Pets_vs_Orcs"},{"t":"Phantasy Star Online 2","p":["Windows"],"d":"Sega Division 3","u":"Sega","g":"Action role-playing, Massively Multiplayer Online","r":"July 4, 2012","l":"https://en.wikipedia.org/wiki/Phantasy_Star_Online_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ep5.jpg","s":"Embark on a never-ending assortment of missions with fellow operatives and experience unparalleled character customization and action RPG combat, completely free to play. Explore numerous worlds with a party of up to four friends or exclusive multiparty areas where up to twelve players can play simultaneously!\n\nOriginally released in Japan and Asia in 2012 and 2014 respectively, The game makes its Global debut in 2020 with a North American launch on Xbox One and Windows 10 before eventually releasing on Steam and across 33 countries. The Global version features the latest balances and patches from the Japanese version while also slowly unlocking new content and features; starting out with the game's first three Episodes, Nine classes and several features introduced in latter major updates.\n\nAside from that, the game supports cross-platform multiplayer and uses a Free-to-Play model with in-game purchases; players can experience a lot of what the game has to offer with no upfront fee."},{"t":"Photo Kano","p":["PlayStation Portable"],"g":"Adventure","l":"https://en.wikipedia.org/wiki/Photo_Kano","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co727w.jpg","s":"A visual novel for PSP."},{"t":"Pid","p":["Windows","macOS","Xbox 360","PlayStation Network"],"r":"October 31","l":"https://en.wikipedia.org/wiki/Pid_(video_game)"},{"t":"Pikmin 2","p":["Wii"],"r":"June 10","l":"https://en.wikipedia.org/wiki/Pikmin_2"},{"t":"Pinball FX 2","p":["Xbox 360"],"r":"October 27","l":"https://en.wikipedia.org/wiki/Pinball_FX_2"},{"t":"Pineapple Smash Crew","p":["Windows"],"d":"Rich Make Game","g":"Action-adventure, dungeon crawl","r":"February 2, 2012","l":"https://en.wikipedia.org/wiki/Pineapple_Smash_Crew","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/hye7vzobbjnhfydwfzix.jpg","s":"Developed by lone designer Rich Edwards with music created by legendary chiptune artist Syphus, Pineapple Smash Crew is a fast paced tactical blast-em-up! PSC features tight squad formation shooting, aliens, robots, zombies and grenades- loads and loads of grenades! Level up and choose wisely from an assortment of devastating grenade-launched weaponry... PSC's unique modern-retro flavour will take you back to the classics of old then smash you back into the present with a 'ka-boom!'"},{"t":"Pirate101","p":["Windows","macOS"],"d":"KingsIsle Entertainment","u":"KingsIsle Entertainment","g":"MMORPG","r":"October 15, 2012","l":"https://en.wikipedia.org/wiki/Pirate101","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobqfk.jpg","s":"Pirate101 is a pirate-themed massively multiplayer online role-playing game (MMORPG) created by KingsIsle Entertainment and released in 2012. A sister game to Wizard101 set in the same universe, players assume the role of heroic pirates who set out in search of the treasures of the \"Spiral\"."},{"t":"Pirates: Tides of Fortune","p":["Browser"],"d":"Plarium","g":"Massively multiplayer online real-time strategy game","l":"https://en.wikipedia.org/wiki/Pirates:_Tides_of_Fortune"},{"t":"Pitfall!","p":["iOS","Android"],"d":"The Blast Furnace","u":"Activision","g":"Platform","r":"August 9, 2012","l":"https://en.wikipedia.org/wiki/Pitfall!_(2012_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9k2s.jpg","s":"Pitfall! for iOS/Android, reimagined as an infinite runner!\n\nLet me introduce myself. I'm Pitfall Harry, veteran jungle explorer. Fortune hunting's my game, and yours, too, if you're daring enough to take this trip with me. Don't be nervous; I'll be your guide through the jungle, and I'm one of the best. Untold riches are waiting for us in there, but so are dangers a dozen times over. We'll be swinging on vines over bottomless tarpits. We'll be hopping across swamps, using crocodile heads like stepping stones. We'll be searching underground through dark passageways crawling with killer scorpions. So pack up your backpack and meet me at the jungle at dawn - and we'll be off to seek a king's ransom in gold, diamonds and lost treasures - in Pitfall Harry's Jungle Adventure."},{"t":"Pixel Defenders Puzzle","p":["iOS"],"d":"Social Titans","g":"Puzzle","r":"December 15, 2012","l":"https://en.wikipedia.org/wiki/Pixel_Defenders_Puzzle","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobmx2.jpg","s":"Place, match and thwack your way through dozens of gorgeous retro-style levels, a variety of game-modes and special hand-crafted scenarios."},{"t":"Pixel Dungeon","p":["Android"],"g":"Role-playing (RPG), Adventure, Indie","l":"https://en.wikipedia.org/wiki/Pixel_Dungeon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co21fz.jpg","s":"Pixel Dungeon is an exciting and extremely popular roguelike (more than 2 million mobile installs!). Explore the depths of Pixel Dungeon, collect useful items and fight fierce monsters to find the Amulet of Yendor - the ultimate artefact of this game world!"},{"t":"PixelJunk 4am","p":["PlayStation Network"],"r":"May 15","l":"https://en.wikipedia.org/wiki/PixelJunk_4am"},{"t":"PixelJunk Eden","p":["Windows"],"r":"February 2","l":"https://en.wikipedia.org/wiki/PixelJunk_Eden"},{"t":"Pizza Vs. Skeletons","p":["iOS","Android"],"d":"Riverman Media LLC","u":"Riverman Media LLC","g":"Platform","r":"February 16, 2012","l":"https://en.wikipedia.org/wiki/Pizza_Vs._Skeletons","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8mk1.jpg","s":"Control a 25-foot-tall pizza as it smashes through a horde of undead rivals on land, sea, and in outer space."},{"t":"Plague Inc.","p":["iOS"],"g":"Real Time Strategy (RTS), Simulator, Strategy, Tactical","r":"May 26","l":"https://en.wikipedia.org/wiki/Plague_Inc.","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2qyq.jpg","s":"As a new disease, it is your job to destroy the entire human species by evolving to a deadly plague."},{"t":"Planets Under Attack","p":["PlayStation Network","Xbox 360"],"r":"November 13","l":"https://en.wikipedia.org/wiki/Planets_Under_Attack"},{"t":"PlanetSide 2","p":["Windows"],"g":"Shooter, Role-playing (RPG), Tactical, Arcade","r":"November 20","l":"https://en.wikipedia.org/wiki/PlanetSide_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2iq1.jpg","s":"PlanetSide 2 is a Massively Multiplayer first person shooter that delivers truly epic, massive combat on a scale never before seen in stunning, breathtaking detail. Battles take place not between dozens of troops, but thousands; with air and ground vehicles slugging it out alongside squads of troops. Whether in open fields, tightly-packed urban centers or enormous structures, winning requires strategic teamwork and a quick trigger finger."},{"t":"Plants vs. Zombies","p":["PlayStation Vita"],"u":"PopCap Games","r":"February 22","l":"https://en.wikipedia.org/wiki/Plants_vs._Zombies"},{"t":"PlayStation All-Stars Battle Royale","p":["PlayStation 3","PlayStation Vita"],"g":"Fighting, Platform","r":"November 20","l":"https://en.wikipedia.org/wiki/PlayStation_All-Stars_Battle_Royale","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ssv.jpg","s":"Playstation All-Stars Battle Royal is a cross over fighting game featuring (mostly exclusive) iconic characters from various Playstation franchises. Each stage also feature prominent setting from other franchises.\n\nPlayable characters are:\nBig Daddy (Bioshock)\nCole MacGrath (Infamous)\nColonel Radec (Killzone)\nDante (DMC)\nEmmett Graves (Starhawk) (DLC content)\nEvil Cole McGrath (Infamous)\nFate Princess (Fat Princess)\nHeihachi Mishima (Tekken)\nIsaac Clarke (Dead Space) (DLC content)\nJak and Daxter (Jak and Daxter)\nKat (Gravity Rush) (DLC content)\nKratos (God of War)\nNariko (Heavenly Sword)\nNathan Drake (Uncharted)\nParappa (Parappa the rapper)\nRaiden (Metal Gear Revengeance)\nRatchet and Clank (Ratchet and Clank)\nSackboy (Little Big Planet)\nSir Daniel Fortesque (MediEvil)\nSly Cooper (Sly Cooper)\nSpike (Ape Escape)\nSweet Tooth (Twisted Metal)\nToro Inoue (Doku Demo Issyo)\nZeus (God of War) (DLC content)"},{"t":"Pocket Fleet","p":["Browser","iOS","Android"],"d":"Tolga Özuygur and Cem Uzunoğlu","u":"Overdose Caffeine Games","g":"MOBA","r":"September 2012","l":"https://en.wikipedia.org/wiki/Pocket_Fleet"},{"t":"Pocket Planes","p":["iOS","Android"],"r":"June 14","l":"https://en.wikipedia.org/wiki/Pocket_Planes"},{"t":"Pokémon Black 2 and White 2","p":["Nintendo DS"],"r":"October 7","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Black_and_White#Sequels"},{"t":"Pokémon Black and White 2","p":["Nintendo DS"],"r":"June 23","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Black_and_White_2"},{"t":"Pokémon Black Version 2","p":["Nintendo DS"],"d":"Game Freak","u":"Nintendo, The Pokémon Company","g":"Role-playing (RPG), Turn-based strategy (TBS), Adventure","r":"June 23, 2012","l":"https://www.igdb.com/games/pokemon-black-version-2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1z8d.jpg","s":"Pokémon Black Version 2 and Pokémon White Version 2 are the second and final paired versions of Generation V and are the sequels of Pokémon Black and White, respectively.\nBoth games were revealed on Pokémon Smash! by Junichi Masuda, and subsequently the official Japanese and international Pokémon websites, on February 26, 2012. They were released in Japan on June 23, 2012, in North America on October 7, 2012, in Australia on October 11, 2012, in Europe on October 12, 2012 and in South Korea on November 8, 2012.\nThe games feature two new forms of Kyurem that serve as the game mascots of the games: Black Kyurem for Black 2 and White Kyurem for White 2."},{"t":"Pokémon Conquest","p":["Nintendo DS"],"g":"Role-playing (RPG), Strategy, Turn-based strategy (TBS)","r":"June 18","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Conquest","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2jxm.jpg","s":"Pokémon Conquest is a strategy game set in the Ransei region. You play as a Warlord of the Primus Kingdom, one of the 17 Kingdoms in the Ransei region. You are charged with the task of battling against a wide variety of powerful opponents, including the mighty Nobunaga, whose goal is to destroy the Ransei region!The 17 Kingdoms of the Ransei region possess a variety of Armies competing for control. The 17 Kingdoms are also deeply linked to a specific Pokémon type. Primus Kingdom, for example, has a strong connection with Normal-type Pokémon!"},{"t":"Pokémon Tretta","p":["Arcade"],"g":"Arcade","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Tretta","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6n04.jpg","s":"Pokémon Tretta is an arcade game developed by Takara Tomy A.R.T.S. and Marvelous AQL, which also developed the Pokémon Battrio arcade game. Officially announced on April 18, 2012, Pokémon Tretta was rolled out nationwide in Japan in early July, phasing out the majority of retired Battrio machines. The arcade machines became fully operational on July 14, 2012 with the release of the first set. The machines are also available in Taiwan in Traditional Chinese and in the Philippines, Indonesia, Malaysia, Singapore, Thailand, and Hong Kong in English.\n\nLike its predecessor, Pokémon Tretta focuses on three-on-three Pokémon battles that require special tiles, called Tretta, that depict one of the various Pokémon species in order to play. Unlike Battrio however, Tretta incorporates searching and capturing Pokémon in various locations. Pokémon caught in-game are dispensed for players to use in other battles, or to add to their collection."},{"t":"Pokémon White Version 2","p":["Nintendo DS"],"d":"Game Freak","u":"The Pokémon Company, Nintendo","g":"Role-playing (RPG), Turn-based strategy (TBS), Adventure","r":"June 23, 2012","l":"https://www.igdb.com/games/pokemon-white-version-2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1z8e.jpg","s":"Pokémon White Version 2 and Pokémon Black Version 2 are the second and final paired versions of Generation V and are the sequels of Pokémon Black and White, respectively.\nBoth games were revealed on Pokémon Smash! by Junichi Masuda, and subsequently the official Japanese and international Pokémon websites, on February 26, 2012. They were released in Japan on June 23, 2012, in North America on October 7, 2012, in Australia on October 11, 2012, in Europe on October 12, 2012 and in South Korea on November 8, 2012.\nThe games feature two new forms of Kyurem that serve as the game mascots of the games: Black Kyurem for Black 2 and White Kyurem for White 2."},{"t":"PokéPark 2: Wonders Beyond","p":["Wii"],"r":"February 27"},{"t":"Poptropica Adventures","p":["Nintendo DS"],"r":"November 6","l":"https://en.wikipedia.org/wiki/Poptropica"},{"t":"Port Royale 3: Pirates & Merchants","p":["Windows","PlayStation 3","Xbox 360"],"r":"May 4"},{"t":"Postal 2: Complete","p":["Windows","macOS","Linux"],"r":"November 2","l":"https://en.wikipedia.org/wiki/Postal_2"},{"t":"Potatoman Seeks the Troof","p":["Ouya","Linux","Windows","iOS","macOS"],"d":"PixelJAM Games","g":"Platformer","l":"https://en.wikipedia.org/wiki/Potatoman_Seeks_the_Troof","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2nzp.jpg","s":"Potatoman will put your reflexes and worldview to the test as you journey through scorching deserts, dark forests, busy cities, the tallest mountains and eventually your own potato-consciousness in search of the ultimate answer. Are you prepared to face the TROOF?"},{"t":"Pou","p":["Android","BlackBerry OS"],"d":"Paul Salameh","u":"Paul Salameh","g":"Virtual pet","r":"August 5, 2012","l":"https://en.wikipedia.org/wiki/Pou_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob03g.jpg","s":"Think you have what it takes to adopt a Pou? How will YOU customize your Pou?\nDo you have what it takes to take care of your very own alien pet?! Feed it, clean it, play with it and watch it grow up while leveling up and unlocking different wallpapers and outfits to satisfy your unique taste. How will you customize your Pou?"},{"t":"Poyopoyo Kansatsu Nikki","p":["Nintendo 3DS"],"l":"https://en.wikipedia.org/wiki/Poyopoyo_Kansatsu_Nikki","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2sre.jpg"},{"t":"Pretentious Game","p":["Windows","iOS","Android"],"d":"Keybol","u":"Bulkypix","g":"Puzzle-platform","l":"https://en.wikipedia.org/wiki/Pretentious_Game"},{"t":"Primal","p":["PlayStation Network"],"r":"February 28","l":"https://en.wikipedia.org/wiki/Primal_(video_game)"},{"t":"Primal Carnage","p":["Windows"],"r":"October 29","l":"https://en.wikipedia.org/wiki/Primal_Carnage"},{"t":"Primordia","p":["Windows","macOS","Linux"],"d":"Wormwood Studios","u":"Wadjet Eye Games","g":"Adventure","r":"December 5, 2012","l":"https://en.wikipedia.org/wiki/Primordia_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1m4v.jpg","s":"Life has ceased. Man is but a myth. And now, even the machines have begun to fail. Lead Horatio Nullbuilt and his sarcastic sidekick Crispin on a journey through the crumbling world of Primordia, facing malfunctioning robots, ancient secrets, and an implacable, power-hungry foe."},{"t":"Prince of Persia Classic","p":["iOS","Android"],"r":"February 29","l":"https://en.wikipedia.org/wiki/Prince_of_Persia_(1989_video_game)#Legacy"},{"t":"Pro Evolution Soccer 2013","p":["Windows","PlayStation 3","Xbox 360","Wii","PlayStation 2","PlayStation Portable"],"g":"Simulator, Sport","r":"September 25","l":"https://en.wikipedia.org/wiki/Pro_Evolution_Soccer_2013","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coarps.jpg","s":"Pro Evolution Soccer 2013 (also known as World Soccer: Winning Eleven 2013 in Japan and South Korea) is an association football video game part of the Pro Evolution Soccer series, developed and published by Konami."},{"t":"Professor Layton and the Miracle Mask","p":["Nintendo 3DS"],"r":"October 28","l":"https://en.wikipedia.org/wiki/Professor_Layton_and_the_Miracle_Mask"},{"t":"Professor Layton vs. Phoenix Wright: Ace Attorney","p":["Nintendo 3DS"],"d":"Capcom, Level-5","u":"Level-5, Nintendo","g":"Adventure, puzzle, visual novel","r":"November 29, 2012","l":"https://en.wikipedia.org/wiki/Professor_Layton_vs._Phoenix_Wright:_Ace_Attorney","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob8ey.jpg","s":"Join forces with expert investigator Professor Layton and ace attorney Phoenix Wright in this unbelievable crossover adventure! Find out what new twists they bring to the courtroom as they solve puzzles and debunk witnesses’ lies. Cross-examine multiple witnesses at the same time to uncover the mysteries of the magical city of Labyrinthia.\n\nIn a medieval town where the people live in fear of witchcraft and those who wield it, Professor Layton and Phoenix Wright, along with their assistants Luke and Maya, join forces to face a perilous journey filled with harrowing mysteries that cannot be solved with mere logic.\n\nInvestigate the city of Labyrinthia and gather information from its townspeople by solving puzzles, then prove your client’s innocence in court. In new group cross-examinations, you’ll pit one witness’ testimony against another’s to get the story straight, then literally rewrite history alongside the greatest puzzle-solving duo Labyrinthia has ever known."},{"t":"Project Zero 2: Wii Edition","p":["Wii"],"d":"Tecmo Koei Games","u":"Nintendo","g":"Survival horror","r":"June 28, 2012","l":"https://en.wikipedia.org/wiki/Project_Zero_2:_Wii_Edition","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3vow.jpg","s":"Fatal Frame 2: Wii Edition is a remake Fatal Frame II: Crimson Butterfly, originally for the PlayStation 2 and the Xbox.\n\nDeep Crimson Butterfly features several major gameplay improvements and enhancements that the original doesn't have such as:\n-A dynamic over the shoulder third person camera angle first used in Mask of the Lunar Eclipse.\n-The map and layout of the game have been updated to work better with the new viewpoint.\n-The graphics and character models are vastly improved, and the costumes were designed with more emphasis on the back since it is constantly in the player's view."},{"t":"Prototype 2","p":["PlayStation 3","Xbox 360","Windows"],"g":"Platform, Hack and slash/Beat 'em up, Adventure","r":"April 24","l":"https://en.wikipedia.org/wiki/Prototype_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20jt.jpg","s":"Prototype 2 is an open-world action game published by Activision and developed by Radical Entertainment. It's a direct sequel to Prototype and was announced at the 2010 Spike Video Game Awards.\n\nThe events of Prototype 2 takes place in New York City, now known as New York Zero (NYZ), following Sgt. James Heller on his quest to destroy Alex Mercer, after having lost everything and everyone he loved to the Blacklight virus."},{"t":"Psychonauts","p":["PlayStation 3"],"r":"August 28","l":"https://en.wikipedia.org/wiki/Psychonauts"},{"t":"Pudding Monsters","p":["iOS","Android"],"d":"ZeptoLab","u":"ZeptoLab, QubicGames","g":"Puzzle video game","r":"December 19, 2012","l":"https://en.wikipedia.org/wiki/Pudding_Monsters","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co49sv.jpg","s":"Sticky, curious… and determined to get bigger! Pudding Monsters is a deliciously addicting puzzle adventure with wacky characters and innovative stick-‘em-together game-play. It’s casual fun for the whole family!"},{"t":"Puddle","p":["Xbox 360","PlayStation Network","PlayStation Vita","Windows"],"r":"January 25","l":"https://en.wikipedia.org/wiki/Puddle_(video_game)"},{"t":"Puella Magi Madoka Magica","p":[],"l":"https://en.wikipedia.org/wiki/Puella_Magi_Madoka_Magica"},{"t":"Punch Quest","p":["iOS"],"d":"Madgarden","u":"Rocketcat Games, Noodlecake Studios","g":"Beat-em-up, endless runner","r":"October 25, 2012","l":"https://en.wikipedia.org/wiki/Punch_Quest","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9hym.jpg","s":"Punch Quest is an iOS beat-em-up/speed-run game developed by Madgarden and published by Rocketcat Games on October 25, 2012."},{"t":"Pure Chess","p":["Windows","PlayStation 3","PlayStation Vita","iOS","Android","Xbox One"],"d":"VooFoo Studios","u":"Ripstone, Play It","g":"Digital tabletop","r":"April 11, 2012","l":"https://en.wikipedia.org/wiki/Pure_Chess","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2r15.jpg","s":"Chess! One of the world’s most popular games, has just got even better! Pure Chess Grandmaster Edition is a stunning celebration of the greatest strategy game of all time."},{"t":"Puyopuyo!! Quest","p":["Android","iOS"],"d":"Sega","u":"Sega","g":"Puzzle, role-playing","l":"https://en.wikipedia.org/wiki/Puyopuyo!!_Quest","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co97hc.jpg","s":"Puyo Puyo!! Quest, not to be confused with Puyo Puyo!! Quest Arcade or Puyo Puyo Quest (the RPG-styled quest mode in Puyo Puyo Box), is a Puzzle RPG spin off of the Puyo Puyo series. The game features puzzle elements that is never before seen in the franchise, and uses a card system similar to other mobile RPG such as Puzzle & Dragons. The game is also renowned for reviving many older characters from across the franchise, and introducing many new original characters."},{"t":"Puzzle & Dragons","p":["iOS"],"r":"November 14","l":"https://en.wikipedia.org/wiki/Puzzle_%26_Dragons"},{"t":"Puzzlejuice","p":["iOS","Android"],"d":"Sirvo","u":"Sirvo","g":"Puzzle","r":"January 19, 2012","l":"https://en.wikipedia.org/wiki/Puzzlejuice","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2s8w.jpg","s":"Falling blocks and word games collide in this iOS release."},{"t":"Pyongyang Racer","p":["Browser"],"d":"Nosotek","u":"Koryo Tours","g":"Racing","r":"December 19, 2012","l":"https://en.wikipedia.org/wiki/Pyongyang_Racer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5fug.jpg","s":"Pyongyang Racer is a racing game set in the streets of Pyongyang, created to be an advergame for Koryo Tours, a travel agency organizing tours to North Korea, developed by Nosotek in collaboration with students from the Kim Chaek University of Technology."},{"t":"Q.U.B.E.","p":["Windows","macOS"],"r":"January 6","l":"https://en.wikipedia.org/wiki/Q.U.B.E."},{"t":"Quantum Conundrum","p":["Windows","PlayStation Network","Xbox 360"],"g":"Platform, Puzzle, Strategy, Adventure","r":"June 21","l":"https://en.wikipedia.org/wiki/Quantum_Conundrum","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co50mf.jpg","s":"In Quantum Conundrum, players take on the role of a young kid dropped off on his uncle's doorstep for the weekend; his uncle just so happens to be the brilliant, eccentric inventor, Professor Fitz Quadwrangle. Upon entering the Professor's vast manor home retrofitted with crazy technology to test his latest hypotheses, players quickly realize their uncle has gone missing. Fortunately, players soon gain access to Professor Quadwrangle's latest invention, the Inter-Dimensional Shift Device, which, at the press of a button, will shift the world around them to an entirely new dimension. In order to find him, players must use the newly found IDS Device to dynamically change the world to and from a variety of different dimensions to progress through the complicated Quadwrangle Manor. While on the journey, becoming adept at utilizing the various dimensions will help them trek from one bizarre and challenging room to the next. It might sound easy enough, but it is a tall order for a kid in a giant puzzle of a manor!"},{"t":"Quantum Moves","p":[],"l":"https://en.wikipedia.org/wiki/Quantum_Moves"},{"t":"Rabbids Land","p":["Wii U"],"r":"November 18","l":"https://en.wikipedia.org/wiki/Rabbids_Land"},{"t":"Rabbids Rumble","p":["Nintendo 3DS"],"r":"November 13","l":"https://en.wikipedia.org/wiki/Rabbids_Rumble"},{"t":"Racer (simulator)","p":["Windows","Linux","macOS"],"d":"Ruud van Gaal","u":"Dolphinity","g":"Sim racing","r":"August 9, 2012","l":"https://en.wikipedia.org/wiki/Racer_(simulator)"},{"t":"RAD Soldiers","p":["iOS"],"d":"Splash Damage","u":"Warchest Ltd.","g":"Turn-based strategy","r":"December 19, 2012","l":"https://en.wikipedia.org/wiki/RAD_Soldiers"},{"t":"Radiant Defense","p":["iOS"],"r":"April 17","l":"https://en.wikipedia.org/wiki/Hexage"},{"t":"Rage of Bahamut","p":["Android","iOS"],"d":"Cygames","u":"DeNA","g":"Collectible card game","r":"January 1, 2012","l":"https://en.wikipedia.org/wiki/Rage_of_Bahamut","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/drxouh4uiv08r1ejqsro.jpg","s":"Rage of Bahamut is an original free-to-play collectible card game on Android and iOS. This deceptively simple fantasy adventure is easy to pick up, but nearly impossible to put down!"},{"t":"Rage of the Gladiator","p":["Android","iOS"],"r":"November 21","l":"https://en.wikipedia.org/wiki/Rage_of_the_Gladiator"},{"t":"Ragnarok Odyssey","p":["PlayStation Vita","PlayStation 3"],"d":"Game Arts","u":"GungHo Online Entertainment, Marvelous USA","g":"Role-playing","r":"February 2, 2012","l":"https://en.wikipedia.org/wiki/Ragnarok_Odyssey","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qoq.jpg","s":"Ragnarok Odyssey is set in an original world based on Norse mythology where a battle is being waged between humans and giants after the fall of the gods had previously separated the races. Players create their characters from over 20,000 possible combinations based on customizable physical features, then select one of six specialized job classes. The game's real-time battles are fast and furious as players can fling enemies skyward, follow them into the air for gravity-defying strikes, then finish off the combo by smacking them clear across the stage. Gameplay is driven forward by story-advancing and optional quests, and up to four players can fight together in online co-op mode."},{"t":"Ragnarok Tactics","p":["PlayStation Portable"],"r":"November 6","l":"https://en.wikipedia.org/wiki/Ragnarok_Tactics"},{"t":"RaiderZ","p":["Windows"],"d":"Masangsoft, MAIET Entertainment","u":"Perfect World Entertainment","g":"MMORPG","l":"https://en.wikipedia.org/wiki/RaiderZ","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2r3n.jpg","s":"RaiderZ is a free-to-play MMO formerly developed by MAIET Entertainment and published in North America by Perfect World Entertainment."},{"t":"Rainbow Moon","p":["PlayStation Network"],"r":"July 10","l":"https://en.wikipedia.org/wiki/Rainbow_Moon"},{"t":"Rat Chaos","p":["Browser"],"g":"Art game, Electronic literature, Interactive fiction","l":"https://en.wikipedia.org/wiki/Rat_Chaos","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3xef.jpg","s":"Rat Chaos is a 2012 stream of consciousness art and browser game created by Winter Lake."},{"t":"Ratchet & Clank Collection","p":["PlayStation 3"],"r":"August 28","l":"https://en.wikipedia.org/wiki/Ratchet_%26_Clank_Collection"},{"t":"Ratchet & Clank: Full Frontal Assault","p":["PlayStation Network","PlayStation Vita"],"g":"Shooter, Platform, Strategy, Adventure","r":"November 27","l":"https://www.igdb.com/games/ratchet-clank-full-frontal-assault","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co230o.jpg","s":"Explore action-packed battlefields and wipe out waves of enemies with outrageous weapons. Classic Ratchet & Clank gameplay returns with a base-defense twist, including competitive and co-op cross-play for the PS3 and PS Vita."},{"t":"Ravaged","p":["Windows"],"d":"2 Dawn Games","u":"Reverb Publishing","g":"First-person shooter","r":"October 17, 2012","l":"https://en.wikipedia.org/wiki/Ravaged","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2sce.jpg","s":"Ravaged is designed with a heavy focus on vehicular combat taking place on vast maps that will have you strategically fighting it out on land and in air with over 40 vehicles and weapons."},{"t":"Rayman 3 HD","p":["PlayStation Network","Xbox 360"],"r":"March 23","l":"https://en.wikipedia.org/wiki/Rayman_3_HD"},{"t":"Rayman Jungle Run","p":["iOS","Android"],"r":"September 20","l":"https://en.wikipedia.org/wiki/Rayman_Origins#Rayman_Jungle_Run"},{"t":"Rayman Origins","p":["PlayStation Vita","Windows","Nintendo 3DS"],"r":"February 15","l":"https://en.wikipedia.org/wiki/Rayman_Origins"},{"t":"RayStorm","p":["iOS"],"r":"June 22","l":"https://en.wikipedia.org/wiki/RayStorm"},{"t":"Reality Fighters","p":["PlayStation Vita"],"r":"March 13","l":"https://en.wikipedia.org/wiki/Reality_Fighters"},{"t":"Receiver","p":["Windows","macOS","Linux"],"d":"Wolfire Games","u":"Wolfire Games","g":"First-person shooter, simulation","r":"June 18, 2012","l":"https://en.wikipedia.org/wiki/Receiver_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co29ot.jpg","s":"Receiver was created for the 7-day FPS challenge to explore gun handling mechanics, randomized levels, and unordered storytelling. Armed only with a handgun and an audio cassette player, you must uncover the secrets of the Mindkill in a building complex infested with automated turrets and hovering shock drones."},{"t":"Record of Agarest War 2","p":["PlayStation 3"],"r":"June 27","l":"https://en.wikipedia.org/wiki/Record_of_Agarest_War_2"},{"t":"Red Bull Crashed Ice Kinect","p":["Xbox 360"],"r":"November 30"},{"t":"Renga","p":[],"d":"wallFour","u":"wallFour","g":"Shoot 'em up","l":"https://en.wikipedia.org/wiki/Renga_(video_game)"},{"t":"Resident Evil 6","p":["PlayStation 3","Xbox 360"],"g":"Shooter, Adventure","r":"October 2","l":"https://en.wikipedia.org/wiki/Resident_Evil_6","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobgod.jpg","s":"Resident Evil 6 is the ninth video game installment in the Resident Evil series. It continues the struggle against zombies infected by the new highly virulent C-virus. The game uses the same over-the-shoulder view as Resident Evil 4 and Resident Evil 5, however with a new gameplay mechanic that allows players to slowly move while shoot. Players can select between three scenarios featuring multiple characters and intertwined storylines, and within these scenarios both stories and action cross paths. At key moments during the game, up to four players can join together online to tackle a specific situation, with some stages seeing the usual partnerships swapped to further increase the depth of gameplay."},{"t":"Resident Evil: Operation Raccoon City","p":["PlayStation 3","Xbox 360","Windows"],"g":"Shooter, Adventure","r":"March 20","l":"https://www.igdb.com/games/resident-evil-operation-raccoon-city","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20d0.jpg","s":"Resident Evil: Operation Raccoon City is a third-person shooter and is a spin-off of the long-running Resident Evil series. Unlike the main games in the series, it is less of a survival horror game and more of an action-packed shooter. The game includes twelve playable characters, however the players can choose only four characters for the online modes. Each team member has their own special role and abilities."},{"t":"Resident Evil: Revelations","p":["Nintendo 3DS"],"g":"Shooter, Adventure","r":"February 7","l":"https://www.igdb.com/games/resident-evil-revelations","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co54dy.jpg","s":"Resident Evil: Revelations is a survival horror game that restores elements of the series' nature, as opposed to the survival action of Resident Evil 5. The game features a single-player mode where the player must complete a series of episodes that involve solving puzzles and defeating enemies, and a multiplayer mode where players may fight their way through altered single-player scenarios."},{"t":"Resident Evil: The Umbrella Chronicles","p":["PlayStation Network"],"r":"June 26"},{"t":"Resistance: Burning Skies","p":["PlayStation Vita"],"r":"May 29"},{"t":"Resonance","p":["Windows","macOS","Linux"],"d":"XII Games","u":"Wadjet Eye Games","g":"Graphic adventure","r":"June 19, 2012","l":"https://en.wikipedia.org/wiki/Resonance_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2is4.jpg","s":"Resonance is a joint effort between Wadjet Eye and xii games. This is an old-school adventure game with an engaging story for all old-school fans."},{"t":"Retro City Rampage","p":["PlayStation Network","Windows"],"r":"October 9","l":"https://en.wikipedia.org/wiki/Retro_City_Rampage"},{"t":"Retro/Grade","p":["PlayStation Network"],"r":"August 21","l":"https://en.wikipedia.org/wiki/Retro/Grade"},{"t":"RFactor 2","p":["Windows"],"d":"Image Space Incorporated, Studio 397","u":"Image Space Incorporated, Motorsport Games","g":"Racing simulation","l":"https://en.wikipedia.org/wiki/RFactor_2"},{"t":"Rhythm Heaven Fever","p":["Wii"],"r":"February 13","l":"https://en.wikipedia.org/wiki/Rhythm_Heaven_Fever"},{"t":"Rhythm Thief & the Emperor's Treasure","p":["Nintendo 3DS"],"r":"July 10","l":"https://en.wikipedia.org/wiki/Rhythm_Thief_%26_the_Emperor%27s_Treasure"},{"t":"Ridge Racer","p":["PlayStation Vita"],"r":"March 13","l":"https://en.wikipedia.org/wiki/Ridge_Racer_(2011_video_game)"},{"t":"Ridge Racer Unbounded","p":["Windows","PlayStation 3","Xbox 360"],"g":"Racing, Arcade","r":"March 27","l":"https://en.wikipedia.org/wiki/Ridge_Racer_Unbounded","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7anv.jpg","s":"Ridge Racer Unbounded takes the Ridge Racer series in whole new direction by adding a dose of destruction to the familiar arcade gameplay."},{"t":"Rift: Storm Legion","p":["Windows"],"r":"November 13","l":"https://en.wikipedia.org/wiki/Rift_(video_game)#Storm_Legion"},{"t":"Rinth Island","p":["iOS"],"r":"March 29","l":"https://en.wikipedia.org/wiki/Rinth_Island"},{"t":"Rise of the Guardians: The Video Game","p":["PlayStation 3","Xbox 360","Wii","Nintendo 3DS","Nintendo DS","Wii U"],"r":"November 20"},{"t":"Risen 2: Dark Waters","p":["Windows","PlayStation 3","Xbox 360"],"g":"Role-playing (RPG), Adventure","r":"April 27","l":"https://www.igdb.com/games/risen-2-dark-waters","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rje.jpg","s":"Set several years after the end of Risen, raging titans have devastated the world and pushed humanity to the brink of existence. Subsequently, monstrous creatures have risen from the watery depths of the sea and their attacks have brought all seafaring to a grinding halt."},{"t":"Robbery Bob","p":["iOS","Android"],"r":"May 3","l":"https://en.wikipedia.org/wiki/Robbery_Bob"},{"t":"Robotics;Notes","p":["PlayStation 3","Xbox 360"],"d":"5pb.","u":"5pb., Spike Chunsoft, Numskull Games","g":"Visual novel","r":"June 28, 2012","l":"https://en.wikipedia.org/wiki/Robotics;Notes","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2vxt.jpg","s":"Robotics;Notes is a Japanese visual novel developed and published by 5pb.. It is the third game in 5pb.'s Science Adventure series and is described as an \"Augmented Science Adventure\". Robotics;Notes takes place in Tanegashima in the year 2019 and revolves around robotics."},{"t":"Rock Band Blitz","p":["PlayStation Network","Xbox 360"],"r":"August 28","l":"https://en.wikipedia.org/wiki/Rock_Band_Blitz"},{"t":"Rocketbirds: Hardboiled Chicken","p":["Windows"],"r":"October 15"},{"t":"Rockman Xover","p":["iOS"],"g":"Platform","l":"https://en.wikipedia.org/wiki/Rockman_Xover","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5ts3.jpg","s":"Infinite runner meets Mega Man in this mobile game. A new hero, OVER-1, takes on classic Mega Man foes from multiple eras.\n\nRockman Xover (Rockman Crossover) was a game announced at Gamescon for the iOS phone platform. It was released on November 29, 2012, and was available for both the iOS and Android devices. The game contained characters from the entire Mega Man franchise.\n\nThe game was also released in China and Korea, but those versions had fewer updates than the Japanese version and had their servers shutdown in 2014, the Korean version in April and the Chinese in August. In the Japanese version, some time after announcing its upcoming end, Crest sales ended on December 24, 2014, and the game itself continued in operation until March 31, 2015."},{"t":"Rocksmith","p":["Windows"],"r":"October 16","l":"https://en.wikipedia.org/wiki/Rocksmith"},{"t":"Rollercoaster Mania","p":["Facebook"],"d":"Noisy Duck","u":"6waves","g":"Theme park game","l":"https://en.wikipedia.org/wiki/Rollercoaster_Mania"},{"t":"RollerCoaster Tycoon 3D","p":["Nintendo 3DS"],"r":"October 16","l":"https://en.wikipedia.org/wiki/RollerCoaster_Tycoon_3D"},{"t":"Romance of the Three Kingdoms 12","p":["Windows","PlayStation 3","PlayStation Vita","Wii U"],"d":"Koei Tecmo","u":"Koei Tecmo","g":"Strategy","r":"December 13, 2012","l":"https://en.wikipedia.org/wiki/Romance_of_the_Three_Kingdoms_12","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co61bu.jpg"},{"t":"Root Double: Before Crime * After Days","p":["Xbox 360","Windows"],"d":"Regista, Yeti","u":"Yeti, Sekai Project","g":"Visual novel","r":"June 14, 2012","l":"https://en.wikipedia.org/wiki/Root_Double:_Before_Crime_*_After_Days"},{"t":"Rose and Time","p":["iOS","Android","Ouya","Windows","macOS","Linux"],"d":"Sophie Houlden","g":"Puzzle-platform","r":"April 2012","l":"https://en.wikipedia.org/wiki/Rose_and_Time","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2yu6.jpg","s":"Rose is desperate to unravel the mysteries of time travel, so she can rescue her parents who are trapped in the past. One day she feels close to an answer, but must be careful to not cause any paradoxes."},{"t":"Rose Guns Days","p":[],"l":"https://en.wikipedia.org/wiki/Rose_Guns_Days"},{"t":"RPG Maker VX Ace","p":["Windows"],"r":"March 15","l":"https://en.wikipedia.org/wiki/RPG_Maker_VX#RPG_Maker_VX_Ace"},{"t":"Ruby Blast","p":["Facebook","iOS"],"d":"Zynga","g":"Puzzle, social network game","r":"June 19, 2012","l":"https://en.wikipedia.org/wiki/Ruby_Blast"},{"t":"Rugby League Live 2","p":["PlayStation 3","Xbox 360","iOS"],"d":"Big Ant Studios, Wicked Witch Software","u":"Tru Blu Entertainment","g":"Sports","r":"October 9, 2012","l":"https://en.wikipedia.org/wiki/Rugby_League_Live_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9b3q.jpg","s":"Rugby Leage Live 2 is a rugby simulation game in which players compete against real-world teams in realistic matches. It features a number of different game modes, including a career mode, custom matches and online games. There is also a Fanhub program in which a user can create and edit teams, players and competitions."},{"t":"Run Roo Run","p":["iOS"],"r":"January 12","l":"https://en.wikipedia.org/wiki/Run_Roo_Run"},{"t":"Rush: A Disney–Pixar Adventure","p":["Xbox 360"],"d":"Asobo Studio","u":"Microsoft Studios","g":"Platform","r":"March 20, 2012","l":"https://en.wikipedia.org/wiki/Rush:_A_Disney%E2%80%93Pixar_Adventure"},{"t":"Ruzzle","p":["iOS","Android","Windows Phone"],"d":"MAG Interactive","g":"Word Game","r":"March 2012","l":"https://en.wikipedia.org/wiki/Ruzzle"},{"t":"Sacred Gold","p":["Linux"],"r":"September 3","l":"https://en.wikipedia.org/wiki/Sacred_(video_game)"},{"t":"Sakura Samurai: Art of the Sword","p":["Nintendo 3DS"],"u":"Nintendo","r":"February 2"},{"t":"Sanctum","p":["macOS"],"r":"August 13","l":"https://en.wikipedia.org/wiki/Sanctum_(2011_video_game)"},{"t":"Saturday Morning RPG","p":["iOS"],"r":"April 5","l":"https://en.wikipedia.org/wiki/Saturday_Morning_RPG"},{"t":"SBK Generations","p":["Windows","PlayStation 3","Xbox 360"],"d":"Milestone","u":"Black Bean Games","g":"Racing","r":"May 1, 2012","l":"https://en.wikipedia.org/wiki/SBK_Generations","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8qps.jpg","s":"The official game of the Superbike FIM World Championship is back this year on PlayStation 3 and Xbox 360 with the most comprehensive motorcycling simulation of all time.\n\nExperience the last 4 seasons, including the new 2012 season, of the SBK world championship. Take the title of World Champion, take on the new SBK Experience mode and win the all-new single-maker races. With SBK Generations, Milestone is ready to release the definitive masterpiece of the motorcycling genre!\n\nOFFICIAL MODE: experience the thrills of the official Superbike championship! Race as the SBK, SuperSport and SuperStock 1000 riders on the most famous circuits in the world, and relive the history-making races of the 2009 to 2012 seasons.\nCARRIER MODE: take on the championships from 2009 to 2012 as your alter-ego, starting in the lower categories and going all the way to the premium class, where the World Champion title awaits.\n\nSBK EXPERIENCE: a unique and innovative experience that brings you into the heart of the world of motorcycling through thrilling themed challenges and single-maker races, against the best riders in the world, including the Legends.\n\nONLINE: experience all the thrills of a real Superbike race, challenging up to 15 players online."},{"t":"Scania Truck Driving Simulator","p":["Windows","macOS"],"d":"SCS Software","u":"Excalibur Publishing, SCS Software","g":"Vehicle simulation","r":"June 8, 2012","l":"https://en.wikipedia.org/wiki/Scania_Truck_Driving_Simulator"},{"t":"Scarface","p":["iOS"],"r":"April 26","l":"https://en.wikipedia.org/wiki/Scarface_(iOS_game)"},{"t":"Scarlet Blade","p":["Windows"],"d":"Liveplex","u":"Netmarble, Aeria Games","g":"MMORPG","l":"https://en.wikipedia.org/wiki/Scarlet_Blade_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/mmxrpt0prkh1lsdnwj86.jpg","s":"Free-to-play MMORPG developed by LivePlex and published by Aeria Games. It is somewhat infamous for its cast of heavily-sexualized female characters."},{"t":"Scarygirl","p":["PlayStation Network","Windows","Xbox 360"],"r":"January 18","l":"https://en.wikipedia.org/wiki/Scarygirl_(video_game)"},{"t":"Score! Classic Goals","p":["iOS","Android"],"d":"First Touch Games","u":"First Touch Games","g":"Soccer/Puzzle","r":"May 17, 2012","l":"https://en.wikipedia.org/wiki/Score!_Classic_Goals","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3sss.jpg","s":"Football themed game made by First Touch Games released in 2012."},{"t":"SCP: Containment Breach","p":["Windows"],"r":"April 15","l":"https://en.wikipedia.org/wiki/SCP_%E2%80%93_Containment_Breach"},{"t":"Scribblenauts Unlimited","p":["Nintendo 3DS","Wii U","Windows"],"g":"Platform, Puzzle, Strategy, Adventure","r":"November 13","l":"https://en.wikipedia.org/wiki/Scribblenauts_Unlimited","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1my3.jpg","s":"Venture into a wide-open world where the most powerful tool is your imagination. Help Maxwell solve robust puzzles in seamless, free-roaming levels by summoning any object you can think of. Create your own original objects, assign unique properties, and share them with friends online using Steam Workshop – to be used in game or further modified as you like!"},{"t":"Secret Files 3","p":["Windows"],"d":"Animation Arts","u":"Deep Silver","g":"Graphic adventure","r":"September 13, 2012","l":"https://en.wikipedia.org/wiki/Secret_Files_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1s8f.jpg","s":"The adventure is not limited to the present, there are also all kinds of puzzles to solve set in the past and in the future, and depending on the choices the player makes, alternative endings await them..."},{"t":"Sentou Gakuen","p":["Browser"],"d":"PST Team","u":"PST Team","g":"Visual novel, MMORPG","r":"January 1, 2012","l":"https://en.wikipedia.org/wiki/Sentou_Gakuen"},{"t":"Serious Sam 3: BFE","p":["macOS","Xbox 360"],"r":"April 23"},{"t":"Sesame Street: Elmo's Musical Monsterpiece","p":["Wii","Nintendo DS"],"d":"Griptonite Games","u":"Warner Bros. Interactive Entertainment","g":"Adventure, edutainment","r":"June 15, 2012","l":"https://en.wikipedia.org/wiki/Sesame_Street:_Elmo's_Musical_Monsterpiece","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2d1d.jpg","s":"Create a musical monsterpiece with Elmo and his Sesame Street friends.\n\nPlay instruments, explore music and dance with Elmo, Abby Cadabby, Count von Count and the honkers as they travel through a music-themed land of wonder!\n\nFeatures\n- Learn about different styles of music as well as intrument and sound indentifaction.\n- Dance to various rhythyms and beats using simple Wii movments.\n- Use a second Wii remote to drop-in and assist when needed.\n- Monitor your child's gameplay with the Parents Page tracking.\n- Game difficulty adapts to your child's level."},{"t":"Shadow of the Colossus","p":["PlayStation 3"],"d":"Team Ico","u":"Sony Computer Entertainment","g":"Platform, Puzzle, Adventure","r":"January 12, 2012","l":"https://www.igdb.com/games/shadow-of-the-colossus--2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ijk.jpg","s":"In a desolate land where beasts as big as mountains roam free, a lone hero and his horse must ride into the unknown on a quest for ancient power. Shadow of the Colossus, an undisputed PlayStation 2 masterpiece, is about to be reborn with the power of PlayStation 3."},{"t":"Shank 2","p":["Windows","PlayStation Network","Xbox 360"],"g":"Hack and slash/Beat 'em up, Adventure, Indie","r":"February 7","l":"https://en.wikipedia.org/wiki/Shank_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co25f3.jpg","s":"The fan-favorite 2D brawler is back as ex-mob hit man Shank returns to action in Shank 2. With those closest to him under attack, Shank is once again forced on the offensive. Now he must put his trusty arsenal of handguns, shotguns, automatic weapons, chainsaws, machetes, grenades, plus all-new weaponry and moves to use in order to protect those close to him. The original game set a new standard for its visual style and Shank 2 raises the bar. Shank 2 expands on the original game’s amazing combat system to redefine the 2D side-scrolling brawler."},{"t":"Shifting World","p":["Nintendo 3DS"],"r":"April 24","l":"https://en.wikipedia.org/wiki/Shift_(game)"},{"t":"Shin Megami Tensei: Devil Survivor 2","p":["Nintendo DS"],"r":"February 28"},{"t":"Shining Blade","p":["PlayStation Portable"],"d":"Media.Vision","u":"Sega","g":"Tactical role-playing game","r":"March 15, 2012","l":"https://en.wikipedia.org/wiki/Shining_Blade","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co49u9.jpg","s":"This is a Japan-only game in the Shining franchise.\nThe game's battle system is called \"Concerto\", and is a strategic real time battle system similar to the ones found in Sakura Wars and Valkyria Chronicles. The player make use of swords, bows and magic in a battle system that places importance on character cooperation—hence the name \"Concerto\".\nThe player forms a party of up to five for battle. The game will have damage based on character position, and items collected upon defeating enemies.\n\nThe songstresses are special members of the player's battle party. By performing their magic song, they can achieve various effects on battle—blocking enemies from moving, increasing characters' move count, making hasten the party's pace. Some songs can even be used for attack. Using the songs requires Mana Energy.\n\nThe game also has inter-character relationships. Depending on the player's selections during event scenes, movements and usage of group skills during battle, the characters' relationships will change."},{"t":"Shinobido 2: Revenge of Zen","p":["PlayStation Vita"],"r":"February 22"},{"t":"Shoot Many Robots","p":["PlayStation Network","Xbox 360","Windows"],"r":"March 13","l":"https://en.wikipedia.org/wiki/Shoot_Many_Robots"},{"t":"Silent Hill 2","p":["PlayStation 3","Xbox 360"],"d":"Hijinx Studios","u":"Konami","g":"Puzzle, Adventure","r":"March 20, 2012","l":"https://www.igdb.com/games/silent-hill-2--2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5wkr.jpg","s":"This version of Silent Hill 2 is a remaster included in the Silent Hill HD Collection. The graphics have been re-mastered to 720p, the in-game voice-over was updated along with a re-mastering of the soundtrack and achievements/trophies were added."},{"t":"Silent Hill HD Collection","p":["PlayStation 3","Xbox 360"],"r":"March 20","l":"https://en.wikipedia.org/wiki/Silent_Hill_2"},{"t":"Silent Hill: Book of Memories","p":["PlayStation Vita"],"r":"October 16"},{"t":"Silent Hill: Downpour","p":["PlayStation 3","Xbox 360"],"g":"Adventure","r":"March 13","l":"https://www.igdb.com/games/silent-hill-downpour","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2vyo.jpg","s":"Silent Hill: Downpour is the eighth Silent Hill video game installment and the last fully-released video game in the series. Just like its predecessors, Downpour combines exploring abandoned surroundings, talking to characters, and solving puzzles, set against a slow, psychological horror theme. Different from the previous game Silent Hill: Shattered Memories is the return of combat. The player often has to fight off monsters using a variety of weapons, but he can carry only one melee and one ranged weapon who can deteriorate over time. Entirely new to the series is the introduction of a weather system: there is a full day and night cycle and rain often warns the player of danger that is approaching. It is possible to hide until the weather becomes better again."},{"t":"Silversword","p":["iOS"],"g":"Role-playing","r":"January 13, 2012","l":"https://en.wikipedia.org/wiki/Silversword","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobn5k.jpg","s":"\"Silverworld\" is a 560,000-word interactive time-travel fantasy novel by Kyle Marquis, where your choices control the story. It's entirely text-based—without graphics or sound effects—and fueled by the vast, unstoppable power of your imagination."},{"t":"SimCity Social","p":["Facebook"],"d":"Playfish","u":"Electronic Arts","g":"City-building game","r":"June 25, 2012","l":"https://en.wikipedia.org/wiki/SimCity_Social","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1r42.jpg","s":"SimCity Social is a city-building simulation game available on Facebook.\n\nSimCity Social brings the real city-building simulation to the masses, giving players the freedom to create sprawling cities that come to life as a result of player-driven choice.\n\nIn SimCity Social, players don’t just build a city – they choose the kind of city they want and watch its soul come to life as it grows and reacts to their decisions."},{"t":"Sine Mora","p":["Xbox 360","Windows","PlayStation Network","PlayStation Vita"],"r":"March 21","l":"https://en.wikipedia.org/wiki/Sine_Mora"},{"t":"Sing Party","p":["Wii U"],"r":"November 18","l":"https://en.wikipedia.org/wiki/Sing_Party"},{"t":"Sins of a Solar Empire: Rebellion","p":["Windows"],"r":"June 12"},{"t":"Skullgirls","p":["PlayStation Network","Xbox 360"],"g":"Fighting, Indie, Arcade","r":"April 10","l":"https://en.wikipedia.org/wiki/Skullgirls","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2e3u.jpg","s":"Skullgirls is a fast-paced 2-D fighting game that puts players in control of fierce warriors in an extraordinary Dark Deco world. Featuring all-new game systems which test the skills of veteran fighting game fans while also making the genre enjoyable and accessible to newcomers, Skullgirls is a modern take on classic arcade fighters with a hand-drawn high-definition twist. It’s a one-of-a-kind, action-packed competition complete with awesome combos and an intriguing backstory."},{"t":"Skylanders: Giants","p":["PlayStation 3","Xbox 360","Wii","Nintendo 3DS","Wii U"],"g":"Role-playing (RPG), Hack and slash/Beat 'em up, Adventure","r":"October 21","l":"https://www.igdb.com/games/skylanders-giants","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ysh.jpg","s":"Skylanders: Giants is a 2012 video game in the Skylanders series, a direct sequel to the 2011 game Skylanders: Spyro's Adventure and features the voices of Kevin Michael Richardson, Greg Ellis, Peter Lurie, Steve Blum, Dave Wittenberg, Carlos Alazraqui, Kevin Sorbo, Bobcat Goldthwait, Patrick Seitz and Julie Nathanson. It is the game before Skylanders: Swap Force. As the title suggests, it features larger Skylanders known as \"Giants\", along with other new gameplay mechanics."},{"t":"Slave of God","p":["Windows","macOS"],"d":"Increpare","g":"Puzzle, Simulator, Adventure, Indie","r":"December 30, 2012","l":"https://en.wikipedia.org/wiki/Slave_of_God","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/vc5ibwecxsvim015b3r6.jpg","s":"A multicolored, surreal trip through a pulsating nightclub."},{"t":"Sleeping Dogs","p":["Windows","PlayStation 3","Xbox 360"],"g":"Shooter, Hack and slash/Beat 'em up, Adventure","r":"August 14","l":"https://en.wikipedia.org/wiki/Sleeping_Dogs_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2e3z.jpg","s":"Sleeping Dogs is a third-person open-world action-adventure game set in contemporary Hong Kong. Players control Wei Shen, an undercover police officer who infiltrates a Triad organization called the Sun On Yee. Gameplay emphasizes melee combat using martial arts moves, grapples, and environmental attacks over gunplay, alongside driving, parkour, and open-world exploration. The game features a triple experience system split between Triad, Police, and Face progression paths, each unlocking different abilities and rewards."},{"t":"Slender Rising","p":["iOS"],"d":"Michael Hegemann","u":"Michael Hegemann","g":"Survival horror","r":"November 16, 2012","l":"https://en.wikipedia.org/wiki/Slender_Rising","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9abp.jpg","s":"Slender Rising is a 2012 horror and indie mobile game by Michael Hegemann. It is based on the creepypasta called Slender Man, a tall, faceless man who hunts people down and inspired by the PC game Slender: The Eight Pages.\n\nThe first-person game tasks players with collecting notes across various maps whilst trying to avoid the Slender Man."},{"t":"Slender: The Eight Pages","p":["Windows","macOS"],"d":"Parsec Productions","u":"Parsec Productions","g":"Survival horror","r":"June 26, 2012","l":"https://en.wikipedia.org/wiki/Slender:_The_Eight_Pages","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2657.jpg","s":"Slender (known as Slender: The Eight Pages as of v0.9.7) is an independently-developed concept game based on the Slender Man mythos. The game centers around an unknown character being stalked and chased by the Slender Man within the woods while seeking eight pages scattered about various landmarks.\n\nThe game was created by Mark J. Hadley as an experiment. The experiment proved to be a success, and Slender gained mass amounts of popularity after going viral. It can be downloaded for free from Hadley's website."},{"t":"Slenderman's Shadow","p":["Windows"],"g":"Indie","l":"https://en.wikipedia.org/wiki/Slenderman's_Shadow","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6bh5.jpg","s":"Slenderman's Shadow is a survival horror game based on the Slenderman mythos. Explore 9 terrifying environments, including an old Hospice, an Elementary school, and a Carnival. Discover new areas, complete your mission, and survive the horrifying being pursuing you.\n\nSlenderman's Shadow is a series of playable maps created (8th Oct 2012) by Marc Steene and Wray Burgess, and later (13th Jan 2013), as a full remake, a survival horror game, based on Slender: The Eight Pages by Parsec Productions."},{"t":"Sliterlink by Nikoli","p":["Nintendo 3DS"],"r":"June 21","l":"https://en.wikipedia.org/wiki/Hamster_Corporation"},{"t":"Slydris","p":["iOS"],"r":"July 26","l":"https://en.wikipedia.org/wiki/Slydris"},{"t":"Smart As ...","p":["PlayStation Vita"],"r":"October 30","l":"https://en.wikipedia.org/wiki/Smart_As"},{"t":"Snapshot","p":["Windows"],"r":"August 30","l":"https://en.wikipedia.org/wiki/Snapshot_(video_game)"},{"t":"Sniper Elite V2","p":["Windows","PlayStation 3","Xbox 360"],"g":"Shooter, Tactical","r":"May 1","l":"https://en.wikipedia.org/wiki/Sniper_Elite_V2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2e41.jpg","s":"Sniper Elite V2 is the eagerly-awaited sequel to the highly-acclaimed Sniper Elite, giving gamers the most authentic World War II sniping experience available. You are elite US sniper Karl Fairburne. Parachuted into Berlin amidst the Germans’ final stand, your mission is to prevent Nazi V2 rocket program technology from falling into the hands of the besieging Red Army. You must aid key scientists keen to defect to the US, and terminate those who would help the Russians.\n\nTake advantage of authentic weaponry, learn how to stalk your targets, fortify your position, set up the shot, use your skill, patience and cunning to achieve your mission. Stealth gameplay is the key as you find yourself trapped between two desperate armies in a race against time. Watch as the celebrated ‘bullet cam’ from Sniper Elite returns, bloodier and more gruesome than ever – skilful shots are rewarded with a slow-motion flight of the bullet, then targets are graphically rendered in X-Ray as the bullet enters and destroys your victim. Organs shred, bones splinter, teeth shatter, as the true impact of the sniper’s bullet is brought to life.\n\nAs World War Two ends and the Cold War begins, every shot counts. Use it wisely."},{"t":"Snops Attack! Zombie Defense","p":["Xbox 360"],"d":"SnopsGames","u":"SnopsGames","g":"Vertical scrolling shooter","r":"September 11, 2012","l":"https://en.wikipedia.org/wiki/Snops_Attack!_Zombie_Defense","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6850.jpg","s":"Take control of our canine hero, Snops, in this action packed shoot-em-up as he tries to save the world from a zombified invasion which has turned everything zombie! Special attacks, massive firepower, explosions, and Zombies! Remember, you're our only hope... You cannot fail!"},{"t":"Sol Trigger","p":["PlayStation Portable"],"d":"Imageepoch","u":"Imageepoch","g":"Role-playing","r":"October 4, 2012","l":"https://en.wikipedia.org/wiki/Sol_Trigger","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2otd.jpg","s":"Sol Trigger is the La Résistance to the Machine Church which rules the dystopian city of Kaiserhald. The Machine Church is using a miraculous energy source known as \"Sol\" to raise the city to even greater heights, but Sol Trigger know that Sol is secretly made from people, and that the Church intends to ramp up their production with a new form of twisted technology."},{"t":"SOL: Exodus","p":["Windows"],"r":"January 25"},{"t":"SolaRola","p":["iOS"],"r":"July 26"},{"t":"Sonic & All-Stars Racing Transformed","p":["Wii U","PlayStation 3","Xbox 360","PlayStation Vita"],"g":"Racing, Sport, Arcade","r":"November 18","l":"https://en.wikipedia.org/wiki/Sonic_%26_All-Stars_Racing_Transformed","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1zvw.jpg","s":"Race as Sonic and a host of legendary All-Stars and prepare to transform! Speed across land, sea and air in a high velocity battle to the finish line, as your amazing transformable vehicle changes from car to boat to plane mid-race. Racing on mobile will never be the same again!"},{"t":"Sonic Adventure 2","p":["PlayStation Network","Xbox 360","Windows"],"g":"Platform, Adventure","r":"October 2","l":"https://en.wikipedia.org/wiki/Sonic_Adventure_2#Release","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5agh.jpg","s":"Sonic Adventure 2 comes to PC and the seventh generation of home video game consoles. This near-identical port of the GameCube version features widescreen gameplay and the re-addition of certain Dreamcast features. Some GameCube features are available only via DLC."},{"t":"Sonic Jump","p":["iOS","Android"],"r":"October 18","l":"https://en.wikipedia.org/wiki/Sonic_Jump"},{"t":"Sonic the Fighters","p":["PlayStation Network","Xbox 360"],"g":"Fighting","r":"November 27","l":"https://en.wikipedia.org/wiki/Sonic_the_Fighters","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6z4q.jpg","s":"Sonic The Fighters is an arcade fighting game in the Sonic the Hedgehog series. This digital high-definition port of was released for the Xbox 360 and PlayStation 3 on November 2012. As of April 2016, the Xbox 360 version of Sonic the Fighters is compatible with Xbox One"},{"t":"Sonic the Hedgehog 4: Episode I","p":["Windows"],"d":"Sonic Team","u":"SEGA","g":"Platformer","r":"January 19"},{"t":"Sonic the Hedgehog 4: Episode II","p":["Windows","PlayStation Network","Xbox 360","iOS"],"g":"Platform, Adventure, Arcade","r":"May 15","l":"https://www.igdb.com/games/sonic-the-hedgehog-4-episode-ii","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1zvs.jpg","s":"The Sonic 4 Saga continues in Episode II with the return of a beloved side kick and fan-favorite villains! Following the events of Episode I, Metal Sonic has returned to form an alliance with Dr. Eggman! To face this new evil, Sonic will have to call upon an old friend to help him save the day!"},{"t":"Sonic the Hedgehog CD","p":["Windows"],"d":"Sonic Team","u":"SEGA","g":"Platformer","r":"January 19","l":"https://en.wikipedia.org/wiki/Sonic_the_Hedgehog_CD"},{"t":"Sorcery","p":["PlayStation 3"],"r":"May 22","l":"https://en.wikipedia.org/wiki/Sorcery_(video_game)"},{"t":"Soul Sacrifice","p":["PlayStation Vita"],"r":"May 13","l":"https://en.wikipedia.org/wiki/Soul_Sacrifice_(video_game)"},{"t":"Soulcalibur V","p":["PlayStation 3","Xbox 360"],"g":"Fighting, Simulator, Strategy, Arcade","r":"January 31","l":"https://en.wikipedia.org/wiki/Soulcalibur_V","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ta1.jpg","s":"SOULCALIBUR V, the latest entry in the premier weapons-based head-to-head fighting series continues the epic struggle of warriors in search for the legendary Soul Swords. SCV takes place 17 years after the events of SOULCALIBUR IV and continues the epic story of warriors in search of the legendary Soul Swords in 17th century Europe. The heroic battles transpire in a beautiful and fluid world with eye-popping graphics and visual appeal. SOULCALIBUR V tunes the battle, movement, and visual systems so players can pull off cool dynamic attacks with ease and battle with complete freedom. A new dawn rises in the eternal struggle between the mighty Soul Swords!."},{"t":"Sound Shapes","p":["PlayStation Network"],"g":"Music, Platform, Puzzle, Strategy","r":"August 7","l":"https://en.wikipedia.org/wiki/Sound_Shapes","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2itt.jpg","s":"Play, Compose and Share in a unique take on the classic side-scrolling platformer where your actions make the music.\n\nEqual parts instrument and game, Sound Shapes gives everyone the ability to make music. Play through a unique campaign that fuses music and artwork into a classic 2D platformer, featuring artwork by Pixeljam, Capy, Superbrothers and more, with music by I Am Robot and Proud, Jim Guthrie and Deadmau5. Create your own unique musical levels with all of the campaign content and share with the world. Sound Shapes creates an ever-changing musical community for everyone to enjoy at home or on the go."},{"t":"South Park: Tenorman's Revenge","p":["Xbox 360"],"r":"March 30"},{"t":"Spaceteam","p":["iOS","Android"],"d":"Sleeping Beast Games","g":"Puzzle, Simulator, Indie","r":"December 1, 2012","l":"https://en.wikipedia.org/wiki/Spaceteam","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobc5l.jpg","s":"A cooperative shouting game for phones and tablets\nDo you like pushing buttons and shouting at your friends? Do you like discharging Clip-jawed Fluxtrunions? If you answered yes, or no, then you might have what it takes to be on a Spaceteam!\n\nFeatures:\n\nTeamwork\nAn untimely demise\nBeveled Nanobuzzers\nAuxiliary Technoprobes\nFour-stroke Pluckers"},{"t":"Spec Ops: The Line","p":["Windows","PlayStation 3","Xbox 360"],"g":"Shooter, Adventure","r":"June 26","l":"https://www.igdb.com/games/spec-ops-the-line","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2acb.jpg","s":"A third-person shooter in which three American soldiers led by Capt. Walker are sent to Dubai in order to recover whoever remains of an infantry unit, the 33rd Battalion, until they decide to take action against the militants situated in the city. As they progress, however, the logistical and ethical complexity of their objective deepens, and their perception of themselves, and their enemy, is put into question."},{"t":"SpellForce 2: Faith in Destiny","p":["Windows"],"d":"Trine Games","u":"Nordic Games","g":"Real-time strategy, role-playing video game","r":"June 19, 2012","l":"https://en.wikipedia.org/wiki/SpellForce_2:_Faith_in_Destiny","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rjx.jpg","s":"An all new campaign that fits into the SpellForce series and enriches the world of SpellForce, including favourite characters and quests.\n\nAn all new race of demonic enemies are also playable in multiplayer mode, featuring new units and structures.\n\nRide into battle on a fierce dragon and use new spells and effects to enhance your tactical possibilities.\n\nInnovative new Role-Playing-Strategy Genre.\n\nClick'n'Fight and Quick-Action-Buttons: The revolutionary control system guarantees instant action, and a wealth of unique tactical possibilities at your fingertips.\n\nEasy Skill tree system that allows individual character development.\n\nEnjoy a highly detailed and living fantasy world that adapts to the actions of the player: Fight monsters, gather items, adventure, trade and collect mighty artifacts to use for your battles.\n\n5 different fractions: Lead The Realm, The Clans, The Pact, the Shaikan and the Nameless to victory, with 12 very different units consisting of infantry, cavalry and flyers.\n\n10 different races: heroic humans, powerful elves, strong dwarves, barbaric trolls,battle-tested orcs, destructive barbarians, powerful dark elves, unbreakable gargoyles, malicious shadows and mean demonic powers."},{"t":"Spelunky","p":["Xbox 360"],"g":"Platform, Adventure, Indie","r":"July 4","l":"https://en.wikipedia.org/wiki/Spelunky","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co47m4.jpg","s":"Spelunky (also known as Spelunky HD) is a remake of Spelunky (now known as Spelunky Classic), an open source indie platformer video game created by Derek Yu and originally released as freeware for Microsoft Windows. The player controls a spelunker who explores a series of caves while collecting treasure, saving damsels, fighting enemies and dodging traps. The caves are procedurally generated, making each run through the game unique. Spelunky is one of the first examples of a roguelike-like, borrowing concepts from the roguelike genre, and was the influence for many later roguelike-like games."},{"t":"Spin Up","p":["iOS"],"r":"March 28","l":"https://en.wikipedia.org/wiki/Spin_Up"},{"t":"Spirit Camera","p":["Nintendo 3DS"],"d":"Tecmo Koei Games","u":"Nintendo","g":"Survival horror","r":"January 12, 2012","l":"https://en.wikipedia.org/wiki/Spirit_Camera","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2v3e.jpg","s":"Spirit Camera: The Cursed Memoir introduces a mysterious girl named Maya who has been hiding in the shadows of an old house. Players must help Maya break free from a terrifying curse by aiding her escape from the clutches of a malevolent woman in black. By using the Nintendo 3DS system's built-in camera, players can view Maya in their own surroundings as the game's eerie events unfold."},{"t":"Spirit Camera: The Cursed Memoir","p":["Nintendo 3DS"],"r":"April 13"},{"t":"Splice","p":["Windows","macOS","Linux","iOS","Android","PlayStation 3","PlayStation 4"],"d":"Cipher Prime","g":"Puzzle, Strategy","r":"June 13, 2012","l":"https://en.wikipedia.org/wiki/Splice_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co248k.jpg","s":"Splice is a puzzler where you are microbes that you \"splice\" to create a specific strand structure in a few amount of moves."},{"t":"Sports Champions 2","p":["PlayStation 3"],"r":"October 30","l":"https://en.wikipedia.org/wiki/Sports_Champions_2"},{"t":"Sports Connection","p":["Wii U"],"d":"Ubisoft Barcelona, Longtail Studios","u":"Ubisoft","g":"Sports","r":"November 18, 2012","l":"https://en.wikipedia.org/wiki/Sports_Connection"},{"t":"Spy Hunter","p":["Nintendo 3DS","PlayStation Vita"],"r":"October 9","l":"https://en.wikipedia.org/wiki/Spy_Hunter"},{"t":"SSX","p":["PlayStation 3","Xbox 360"],"g":"Racing, Sport","r":"February 28","l":"https://en.wikipedia.org/wiki/SSX_(2012_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ypl.jpg","s":"A snowboarding game and a reboot of the SSX series. Players ride down mountain courses based on real-world locations, chaining tricks to build boost and reach faster speeds. Alongside a career-style World Tour, the game offers free exploration of the mountains and asynchronous online challenges where players compete for scores and times."},{"t":"Stacking","p":["Windows"],"r":"March 6","l":"https://en.wikipedia.org/wiki/Stacking_(video_game)"},{"t":"Star Conflict","p":["Windows"],"d":"Star Gem Inc.","u":"Gaijin Entertainment","g":"Action, MMO, space sim","r":"July 24, 2012","l":"https://en.wikipedia.org/wiki/Star_Conflict","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1szt.jpg","s":"Star Conflict is a Free to Play online space combat game featuring multiple Objective-Based Team Gameplay modes, three main factions with 2 respective sub factions each, and an array of ship customization and three types of ships complete with there own ship tree and skill tree."},{"t":"StarDrone Extreme","p":["PlayStation Vita"],"r":"April 17"},{"t":"Starhawk","p":["PlayStation 3"],"r":"May 8","l":"https://en.wikipedia.org/wiki/Starhawk_(2012_video_game)"},{"t":"Starseed Pilgrim","p":["Windows","macOS"],"d":"droqen","g":"Puzzle-platform","l":"https://en.wikipedia.org/wiki/Starseed_Pilgrim","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2jp8.jpg","s":"Starseed Pilgrim is a puzzle game where the player adds blocks with different proporties to each other, trying to get as far as possible as the blocks disappear."},{"t":"Stealth Bastard Deluxe","p":["Windows"],"r":"November 28","l":"https://en.wikipedia.org/wiki/Stealth_Bastard"},{"t":"Steam Bandits: Outpost","p":["Windows","macOS","Android","iOS","Linux"],"d":"Iocaine Studios","g":"City Building, Casual","l":"https://en.wikipedia.org/wiki/Steam_Bandits:_Outpost"},{"t":"Steel Battalion: Heavy Armor","p":["Xbox 360"],"r":"June 19"},{"t":"Stonekeep: Bones of the Ancestors","p":["Wii"],"d":"Alpine Studios","u":"Interplay Entertainment","g":"Role-playing (RPG), Adventure","l":"https://en.wikipedia.org/wiki/Stonekeep:_Bones_of_the_Ancestors","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co520w.jpg","s":"Stonekeep: Bones of the Ancestors is a video game developed by Alpine Studios and published by Interplay Entertainment for the Nintendo Wii in 2012. The game is the second game released in the Stonekeep series, although it is not Stonekeep 2, a game that was cancelled after five years of development, but rather a new game based on the original. The game was released through the WiiWare online distribution system, Interplay's second game of the kind, after MDK2 HD, to positive sales, but largely negative critical reception."},{"t":"Stormfall: Age of War","p":["Browser","Facebook"],"d":"Plarium","u":"Plarium","g":"Massively multiplayer online real-time strategy game","l":"https://en.wikipedia.org/wiki/Stormfall:_Age_of_War"},{"t":"Street Fighter X Mega Man","p":["Windows"],"r":"December 17","l":"https://en.wikipedia.org/wiki/Street_Fighter_X_Mega_Man"},{"t":"Street Fighter X Tekken","p":["PlayStation 3","Xbox 360","Windows","PlayStation Vita"],"g":"Fighting, Arcade","r":"March 6","l":"https://en.wikipedia.org/wiki/Street_Fighter_X_Tekken","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1w4i.jpg","s":"The long awaited dream match-up between the two titans of fighting is here!"},{"t":"Strikefleet Omega","p":["Android","iOS","Fire OS"],"d":"Harebrained Schemes","u":"6waves","g":"Tower defense, real-time strategy","r":"June 21, 2012","l":"https://en.wikipedia.org/wiki/Strikefleet_Omega"},{"t":"Stronghold Kingdoms","p":["Windows"],"d":"Firefly Studios","u":"Firefly Studios","g":"Massively multiplayer online real-time strategy","r":"October 17, 2012","l":"https://en.wikipedia.org/wiki/Stronghold_Kingdoms","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2srx.jpg","s":"Live the life of a medieval lord online in Stronghold Kingdoms, the world’s first Castle MMO. Farm peacefully, engage in political mind games or lay siege to sworn enemies.\n\nBesiege the castle that’s never been taken, overthrow ruthless tyrants, bankroll your faction’s war effort, pillage your neighbour’s resources, peacefully raise cattle or do it all! A range of stats, rankings and achievements gives every player something to aim for, from ‘Banquet King’ and ‘Peacebringer’ to 'Besieger of the Month' and ‘Lionheart'! Factions, elections, liege lords and their vassals all provide a real sense of structured community, with many different ways to chat with other players, discuss strategies and build allegiances.\n\nWhile an impregnable castle should be at the heart of any lord or lady's domain, you can also specialise with a vast research tree. Starting as a humble peasant, each promotion brings with it valuable research points to spend on trading, diplomacy, warfare, farming, religion and more. Be aware though, as your power grows so does your responsibility. Your vassals and parishioners will look to you for guidance and leadership. You may find yourself fighting for the crown itself!"},{"t":"Style Savvy: Trendsetters","p":["Nintendo 3DS"],"r":"October 21"},{"t":"Subway Surfers","p":["iOS","macOS","Android","Browser","Windows Phone","Windows"],"d":"Kiloo, SYBO Games","u":"Kiloo Games, SYBO Games","g":"Endless runner","r":"May 24, 2012","l":"https://en.wikipedia.org/wiki/Subway_Surfers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7fvi.jpg","s":"DASH as fast as you can!\nDODGE the oncoming trains!\n\nHelp Jake, Tricky & Fresh escape from the grumpy Inspector and his dog."},{"t":"Sumioni: Demon Arts","p":["PlayStation Vita"],"r":"March 20","l":"https://en.wikipedia.org/wiki/Sumioni"},{"t":"Summer Stars 2012","p":["PlayStation 3","Wii"],"r":"July 10"},{"t":"Summoner Wars","p":["iOS","Android"],"d":"Plaid Hat Games, Playdek","r":"July 4, 2012","l":"https://en.wikipedia.org/wiki/Summoner_Wars"},{"t":"Super Amazing Wagon Adventure","p":["Xbox 360"],"d":"sparsevector","u":"sparsevector","g":"Action-adventure","r":"July 6, 2012","l":"https://en.wikipedia.org/wiki/Super_Amazing_Wagon_Adventure","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co882h.jpg","s":"Super Amazing Wagon Adventure is a fast-paced 2d shooting game with a random story. You control a group of three migrants traveling west along a wagon trail. The game consists of short scenes that are sequenced together in a semi-random way to tell a crazy adventure story. One minute you could be massacring a herd of buffalo, the next attacked by eagles while falling off a cliff."},{"t":"Super Hexagon","p":["Windows","macOS"],"u":"Terry Cavanagh","g":"Action, Indie","r":"November 27, 2012","l":"https://en.wikipedia.org/wiki/Super_Hexagon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4iei.jpg","s":"Super Hexagon is a minimal action game by Terry Cavanagh, with music by Chipzel."},{"t":"Super Lemonade Factory","p":["iOS","Windows","macOS"],"d":"Initials Command","g":"Platform, Indie","r":"March 14, 2012","l":"https://en.wikipedia.org/wiki/Super_Lemonade_Factory","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6j2c.jpg","s":"Post World War II, a region in political turmoil. Andre’s father offers to give him his lemonade factory – but on one condition; he and his wife, Liselot, must journey through the entire factory, a task that is easier said than done. Andre and Liselot must combine their unique abilities to make it through each room together. Along the way they’ll meet a cast of characters including the foreman, the chef, a food inspector and a general who wants the factory to supply drinks to the military, now engaged in a new war."},{"t":"Super Mole Escape","p":["iOS"],"d":"Grumpyface Studios","u":"Adult Swim Games","g":"Endless runner, action","r":"August 9, 2012","l":"https://en.wikipedia.org/wiki/Super_Mole_Escape"},{"t":"Super Monday Night Combat","p":["Windows"],"r":"April 18","l":"https://en.wikipedia.org/wiki/Super_Monday_Night_Combat"},{"t":"Super Monkey Ball: Banana Splitz","p":["PlayStation Vita"],"d":"Marvelous AQL","u":"Sega","g":"Platform, party","r":"June 14, 2012","l":"https://en.wikipedia.org/wiki/Super_Monkey_Ball:_Banana_Splitz","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3s6e.jpg","s":"Super Monkey Ball: Banana Splitz is a video game released exclusively for the PlayStation Vita by Sega. The game is the tenth release in the Super Monkey Ball series."},{"t":"Super Monsters Ate My Condo","p":["iOS"],"r":"September 27","l":"https://en.wikipedia.org/wiki/Super_Monsters_Ate_My_Condo"},{"t":"Super Ox Wars","p":["iOS"],"u":"Llamasoft","g":"Scrolling shooter","r":"June 24, 2012","l":"https://en.wikipedia.org/wiki/Super_Ox_Wars"},{"t":"Super Stardust Delta","p":["PlayStation Vita"],"r":"February 22","l":"https://en.wikipedia.org/wiki/Super_Stardust_Delta"},{"t":"Superbrothers: Sword & Sworcery EP","p":["Windows"],"r":"April 16"},{"t":"Supremacy MMA: Unrestricted","p":["PlayStation Vita"],"r":"March 27","l":"https://en.wikipedia.org/wiki/Supremacy_MMA"},{"t":"Sweet Fuse: At Your Side","p":["PlayStation Portable"],"d":"Comcept","u":"Idea Factory, Aksys Games","g":"Visual novel","r":"June 14, 2012","l":"https://en.wikipedia.org/wiki/Sweet_Fuse:_At_Your_Side","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7lc1.jpg","s":"Sweet Fuse is a mystery and romance visual novel in which the player assumes the role of Saki Inafune, as she plays through seven days of death games. Much of its gameplay is spent on reading the story's narrative and dialogue. The player will be prompted on occasion to pick what to make Saki say. Picking the correct responses will sometimes given the player an \"affection point\" for a particular character which raises that character's affection level. There are moments during which Saki will become irate, indicated by the screen shaking and turning red, and the player will have to choose between having her restrain her anger or letting it out.\n\n\"Explosive Insight\" sections take place when Saki must find a solution or an answer to a problem. Saki recalls the situation to herself, with a number of keywords and phrases in her thoughts highlighted. The player can pick up to three highlighted words or phrases to select, and the player prompts Saki's epiphany if one of their selections is correct.[1] If the player does not select the correct phrases, a bad ending will usually occur and they are prompted to try again.\n\nThe game follows a branching plot line with multiple endings; depending on the decisions that the player makes during the game, the plot will progress in a specific direction."},{"t":"Swordigo","p":["iOS","Android"],"d":"Touch Foo","u":"Touch Foo","g":"Platform-adventure, action role-playing game, Metroidvania","r":"March 22, 2012","l":"https://en.wikipedia.org/wiki/Swordigo","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3z7c.jpg","s":"Side-scrolling action RPG for mobile devices.\n\nRun, jump and slash your way through a vast world of platforming challenges and embark on an epic adventure! The #1 mobile adventure game and a 3D platformer, now also available for Android phones and tablets.\n\nA GREAT ADVENTURE\n• Explore a magical realm of dungeons, towns, treasures and devious monsters.\n• Gain experience and level up your character.\n\nMAGIC AND SWORDS\n• Find powerful weapons, items and spells to defeat your enemies.\n• Venture into gloomy caves and dungeons to discover powerful hidden swords.\n\nSIDE-SCROLLER PLATFORMER GAME\n• Fluid and challenging platforming gameplay designed specifically for mobile devices.\n• Precise touch controls optimized for smartphones and tablets.\n• Customize the controls to your preference."},{"t":"Symphonica","p":["iOS"],"d":"iNiS","u":"Square Enix","g":"Rhythm game","r":"October 18, 2012","l":"https://en.wikipedia.org/wiki/Symphonica_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/zikzxwg2xx3oeloyxyli.jpg","s":"A mix between a visual novel and a rhythm game developed by the creators of Elite Beats Agents."},{"t":"Symphony","p":["Windows"],"d":"Empty Clip Studios","u":"Empty Clip Studios","g":"Shoot-em-up","r":"August 9, 2012","l":"https://en.wikipedia.org/wiki/Symphony_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2rig.jpg","s":"Your music is under attack… You must liberate it! \nIn Symphony, you fight through levels uniquely generated by your own song collection, discover items and vanquish bosses to defeat the evil within! \n \n \n \nWith Symphony, we wanted to push the limits of user-music-based gameplay and focused on two concepts: \n \nYour music creates the game \nEvery song has a unique emotion, sound and rhythm, and we wanted the gameplay to capture that as fully as possible. When your music gets intense or calmer, so does the gameplay. Enemies appear and shoot on the beat of the music. Some weapons are music-driven. Each song has its personality and it directly translates into gameplay. \n \nReplayability \nIn Symphony, each song in your collection not only becomes a unique level, but also provides you with an item you can equip and challenges you with score targets to reach. As you progress through the game, you unlock new difficulty levels, new items and abilities! This means you have many reasons to play your favorite song over and over."},{"t":"Syndicate","p":["Windows","PlayStation 3","Xbox 360"],"g":"Shooter, Puzzle","r":"February 21","l":"https://en.wikipedia.org/wiki/Syndicate_(2012_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2srt.jpg","s":"Set in 2069, Syndicate takes players into a dark, Machiavellian world run without government oversight with many syndicates vying for total dominance of their local market place. With no one to question their intentions or actions, three mega corporations - Eurocorp, Cayman Global, and Aspari - are at the forefront of this brutal war for control of the pivotal American market. In the world of Syndicate, everything is digitally connected, including the people. Players aren't limited to the weapons in their hands. Through DART 6 bio-chip technology implanted in their head, players can slow down time and breach the digital world around them to take down their foes using a variety of upgradable hacking mechanics. Syndicate's blend of fast-paced, futuristic, action shooter settings and story combined with innovative chip breach gameplay instantly immerses players in a unique digital world."},{"t":"Table Top Tanks","p":["PlayStation Vita"],"r":"May 22"},{"t":"Tales from Space: Mutant Blobs Attack","p":["PlayStation Vita","Windows"],"r":"February 21"},{"t":"Tales of Graces ƒ","p":["PlayStation 3"],"r":"March 13","l":"https://en.wikipedia.org/wiki/Tales_of_Graces_%C6%92"},{"t":"Tales of Maj'Eyal","p":["Windows","macOS","Linux"],"d":"Netcore Games","g":"Roguelike","l":"https://en.wikipedia.org/wiki/Tales_of_Maj'Eyal","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2iqa.jpg","s":"Tales of Maj'Eyal is a roguelike RPG, featuring tactical turn-based combat and advanced character building. Play as one of many unique races and classes in the lore-filled world of Eyal, exploring random dungeons, facing challenging battles, and developing characters with your own tailored mix of abilities and powers."},{"t":"Tales of the Abyss","p":["Nintendo 3DS"],"r":"February 14","l":"https://en.wikipedia.org/wiki/Tales_of_the_Abyss"},{"t":"Tales of the Heroes: Twin Brave","p":["PlayStation Portable"],"d":"Alfa System","u":"Namco Bandai Games","g":"Beat 'em up, Action","r":"February 23, 2012","l":"https://en.wikipedia.org/wiki/Tales_of_the_Heroes:_Twin_Brave","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co31oz.jpg","s":"Tales of the Heroes: Twin Brave is an action beat 'em up, video game in the Tales series of games. It is considered an \"scort title\", and plays more similarly to the Dynasty Warriors game series."},{"t":"Tales of the World: Dice Adventure","p":["Browser"],"d":"Namco Bandai Games","u":"Namco Bandai Games","g":"Board game, roleplaying game","r":"April 26, 2012","l":"https://en.wikipedia.org/wiki/Tales_of_the_World:_Dice_Adventure","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8055.jpg","s":"Tales of the World: Dice Adventure is a web browser-based board game in the Tales series released April 26, 2012 in Japan. The game is a role-playing and board game hybrid, where the player rolls virtual dice to determine how much a character moves across the board. Through the course of traversing the board, the player can form parties with other characters, experience story events, and participate in battles."},{"t":"Tales of the World: Tactics Union","p":["Android","Nintendo 3DS"],"d":"Namco Bandai Games, Jupiter","u":"Namco Bandai Games","g":"Tactical RPG","r":"July 2, 2012","l":"https://en.wikipedia.org/wiki/Tales_of_the_World:_Tactics_Union","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8054.jpg","s":"Revalia is a world formed from the dreams of people from countless different worlds. As long as there are those who dream, it continues to exist; when they cease to dream, the world will die. Within Revalia resides the Rufres tribe, whose duty is to keep the balance in the world by purifying the nightmares of the people, the incarnation of the people's darkness in their hearts called Vuul."},{"t":"Tales of Xillia 2","p":["PlayStation 3"],"d":"Bandai Namco Studios","u":"Bandai Namco Games","g":"Action role-playing game","r":"November 1, 2012","l":"https://en.wikipedia.org/wiki/Tales_of_Xillia_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co25yo.jpg","s":"The game takes place a year after Tales of Xillia. Elle Mel Marta is given specific instructions by her father to board a train and to find the Land of Canaan. Her train is hijacked before its departure and Ludger Will Kresnik boards it to save her. The train crashes and the two receive life saving treatment from Clanspia Inc. which puts Ludger in debt. Clanspia Inc. hires Ludger, intending to use his Kresnik powers to destroy alternative timelines because the spirit Origin can no longer sustain the abundance of souls in the worlds. While working off the debt, Ludger also searches for his brother, Julius Will Kresnik, who has been blamed for the train hijacking."},{"t":"Tank! Tank! Tank!","p":["Wii U"],"r":"November 18","l":"https://en.wikipedia.org/wiki/Tank!_Tank!_Tank!"},{"t":"Tantei Opera Milky Holmes","p":[],"l":"https://en.wikipedia.org/wiki/Tantei_Opera_Milky_Holmes"},{"t":"Tekken 3D: Prime Edition","p":["Nintendo 3DS"],"r":"February 14"},{"t":"Tekken Tag Tournament 2","p":["PlayStation 3","Xbox 360","Wii U"],"g":"Fighting","r":"September 11","l":"https://en.wikipedia.org/wiki/Tekken_Tag_Tournament_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1w4k.jpg","s":"The console release added new characters and stages."},{"t":"Teleglitch","p":["Windows","macOS","Linux"],"d":"Test3 Projects","u":"Paradox Interactive","g":"Action","r":"November 2012","l":"https://en.wikipedia.org/wiki/Teleglitch","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2hz0.jpg","s":"Teleglitch is a roguelike top-down shooter with pixel graphics. The game takes place in a secret corporate research facility on an inhospitable planet far beyond the reach of civilization where something has gone horribly wrong."},{"t":"Temple Run","p":["Android"],"r":"March 27","l":"https://en.wikipedia.org/wiki/Temple_Run"},{"t":"TERA","p":["Windows"],"r":"May 1","l":"https://en.wikipedia.org/wiki/TERA_(video_game)"},{"t":"Test Drive: Ferrari Racing Legends","p":["PlayStation 3","Xbox 360","Windows"],"r":"July 3"},{"t":"The Amazing Spider-Man","p":["Nintendo DS","PlayStation 3","Xbox 360","Wii","Nintendo 3DS","Android","iOS","Windows"],"g":"Hack and slash/Beat 'em up, Adventure","r":"June 26","l":"https://en.wikipedia.org/wiki/The_Amazing_Spider-Man_(2012_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2l1s.jpg","s":"The Amazing Spider-Man is an action-adventure video game released in 2012, developed by Beenox and published by Activision. The game serves as a tie-in to the 2012 film of the same name, though it features its original storyline that continues after the movie's events. Players control Spider-Man as he swings through an open-world version of New York City, battling criminals and iconic villains like the Lizard and Rhino while facing Oscorp's mutated creatures.\n\nThe game focuses on Spider-Man's web-slinging, combat, and exploration abilities. It has a mix of main missions and side activities. The gameplay includes stealth, brawler-style combat, and environmental puzzles."},{"t":"The Basement Collection","p":["Windows","macOS","Linux"],"g":"Various","r":"August 31, 2012","l":"https://en.wikipedia.org/wiki/The_Basement_Collection"},{"t":"The Battle Cats","p":["iOS","Android","Nintendo 3DS","Windows"],"d":"PONOS Corporation, Tose","u":"PONOS Corporation, Bandai Namco Entertainment","g":"Tower defense","l":"https://en.wikipedia.org/wiki/The_Battle_Cats","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3gcw.jpg","s":"The Battle Cats is a tower defense mobile game. The cats must face fearsome enemies, such as Doge the dog, Gory the Gorilla, and H. Nah the Hyena."},{"t":"The Binding of Isaac: Wrath of the Lamb","p":["Windows","macOS"],"r":"May 28"},{"t":"The Book of Unwritten Tales: The Critter Chronicles","p":["Windows","macOS","Linux"],"d":"King Art Games","u":"Nordic Games","g":"Adventure","r":"December 5, 2012","l":"https://en.wikipedia.org/wiki/The_Book_of_Unwritten_Tales:_The_Critter_Chronicles","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qlp.jpg","s":"The Critter Chronicles tell the story of how adventurer Nate Bonnett and Critter, his hairy sidekick, first met, all set before their appearance in Wilbur's and Ivo's adventure in The Book of Unwritten Tales. Enjoy a thrilling and hilarious point-and-click adventure in the fantasy world of Aventasia. Travel from the Northlands to the Mage's Tower of Seastone and experience a story that offers tremendous fun for seasoned players of \"The Book of Unwritten Tales\" and newcomers alike."},{"t":"The Cat Lady","p":["Windows","Linux"],"d":"Harvester Games","u":"Screen 7","g":"Graphic adventure","r":"December 7, 2012","l":"https://en.wikipedia.org/wiki/The_Cat_Lady","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rfw.jpg","s":"The Cat Lady is a single-player horror graphic adventure and the second entry in the Devil Came Through Here trilogy, following Downfall and preceding Lorelai. It is a puzzle-based adventure played entirely with the four arrow keys, so characters move left and right between scenes while the up and down keys handle interacting with the environment and inventory. Dialogue is fully voiced, and occasional dialogue choices can shift the story and its ending slightly. The game deals with mature themes including depression, suicide, murder, and illness, alongside moments of humor."},{"t":"The Cube","p":["Nintendo 3DS","PlayStation 3","Wii"],"d":"Route 1 Games","u":"Funbox Media","g":"Puzzle","r":"November 16, 2012","l":"https://en.wikipedia.org/wiki/The_Cube_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co27v4.jpg","s":"Remember those old games from your childhood and feel the taste of passing level after level, absorbing all the soulfulness of our game. Maybe you also want to become a Cube? Based on the British game show of the same name."},{"t":"The Dark Eye: Chains of Satinav","p":["Windows","macOS"],"d":"Daedalic Entertainment","u":"Deep Silver, Merge Games","g":"Graphic adventure","r":"June 22, 2012","l":"https://en.wikipedia.org/wiki/The_Dark_Eye:_Chains_of_Satinav","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1u2h.jpg","s":"With a history of more than 25 years, The Dark Eye is one of Europe's best-known role-playing brands. In addition to the popular pen & paper adventures, TDE has also inspired a series of successful computer games. The Dark Eye: Chains of Satinav immerses players deep in the world of Aventuria, where they experience an amazing story and explore lands never before featured in a TDE computer game.\n\nIn Andergast, whose inhabitants are considered to be notoriously superstitious, King Efferdan awaits a state visit from high-ranking dignitaries. For centuries the kingdom has been at odds with neighboring Nostria, but now first steps are being undertaken toward a lasting peace. But a plague of crows troubles the king, for the birds are acting with unusual aggressiveness, even attacking humans. Moreover, there are those among the citizens of Andergast who swear that the crows are bringing them dark nightmares. As the belligerent creatures infiltrate even the castle itself, the king seeks a skilled bird catcher - an opportunity for young Geron to prove that the reputation for ill luck that has followed him since childhood is undeserved. Following an audience with the king, the prestigious task is assigned to him. However, not only does his task prove unexpectedly difficult, but it also turns out to be the first step of the greatest adventure of his life, which will lead him to the borders of the charted lands of Aventuria and beyond."},{"t":"The Darkness II","p":["Windows","PlayStation 3","Xbox 360","macOS"],"g":"Shooter","r":"February 7","l":"https://en.wikipedia.org/wiki/The_Darkness_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1mxv.jpg","s":"The Darkness II is an intense first person shooter that delivers a twisted and gripping narrative of tragedy, modern crime drama, and supernatural horror. Players will be taken down the brutal and personal path of Jackie Estacado, head of a New York crime family and wielder of an ancient and ruthless force of chaos and destruction known as The Darkness."},{"t":"The Denpa Men: They Came By Wave","p":["Nintendo 3DS"],"r":"September 27"},{"t":"The Elder Scrolls V: Skyrim – Dawnguard","p":["Xbox 360","Windows"],"d":"Bethesda Game Studios","u":"Bethesda Softworks","g":"Action role-playing","r":"June 26, 2012","l":"https://en.wikipedia.org/wiki/The_Elder_Scrolls_V:_Skyrim_%E2%80%93_Dawnguard"},{"t":"The Elder Scrolls V: Skyrim – Dragonborn","p":["Xbox 360"],"d":"Bethesda Game Studios","u":"Bethesda Softworks","g":"Action role-playing","r":"December 4, 2012","l":"https://en.wikipedia.org/wiki/The_Elder_Scrolls_V:_Skyrim_%E2%80%93_Dragonborn"},{"t":"The Elder Scrolls V: Skyrim – Hearthfire","p":["Xbox 360","Windows"],"d":"Bethesda Game Studios","u":"Bethesda Softworks","g":"Action role-playing","r":"September 4, 2012","l":"https://en.wikipedia.org/wiki/The_Elder_Scrolls_V:_Skyrim_%E2%80%93_Hearthfire"},{"t":"The Expendables 2 Video game","p":["Windows","PlayStation Network","Xbox 360"],"r":"August 21","l":"https://en.wikipedia.org/wiki/The_Expendables_2#Video_games"},{"t":"The Fool and His Money","p":["Windows","macOS"],"r":"October 25","l":"https://en.wikipedia.org/wiki/The_Fool_and_His_Money"},{"t":"The Hip Hop Dance Experience","p":["Wii","Xbox 360"],"d":"iNiS, Land Ho!","u":"Ubisoft","g":"Dance","r":"November 13, 2012","l":"https://en.wikipedia.org/wiki/The_Hip_Hop_Dance_Experience","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22j0.jpg","s":"The Hip Hop Dance Experience is a dancing game for the Wii and Xbox 360 published by Ubisoft. It is a continuation of The Experience franchise, a spin-off of the Just Dance series."},{"t":"The House in Fata Morgana","p":["Windows"],"d":"Novectacle","u":"Novectacle, FuRyu, Dramatic Create, MangaGamer","g":"Visual novel","r":"December 31, 2012","l":"https://en.wikipedia.org/wiki/The_House_in_Fata_Morgana","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co23cn.jpg","s":"A gothic suspense tale set in a cursed mansion. \"The House in Fata Morgana\" is a full-length visual novel spanning nearly a millennium that deals in tragedy, human nature, and insanity."},{"t":"The House of the Dead 4","p":["PlayStation Network"],"r":"April 17","l":"https://en.wikipedia.org/wiki/The_House_of_the_Dead_4"},{"t":"The House of the Dead III","p":["PlayStation Network"],"r":"February 7","l":"https://en.wikipedia.org/wiki/The_House_of_the_Dead_III"},{"t":"The Idolmaster Shiny Festa","p":["PlayStation Portable"],"d":"Namco Bandai Studios, A-1 Pictures","u":"Namco Bandai Games","g":"Rhythm game","r":"October 25, 2012","l":"https://en.wikipedia.org/wiki/The_Idolmaster_Shiny_Festa"},{"t":"The Journey Down","p":["iOS","Linux","macOS","Windows","Xbox One","PlayStation 4"],"d":"Skygoblin","u":"Skygoblin","g":"Adventure","r":"May 18, 2012","l":"https://en.wikipedia.org/wiki/The_Journey_Down"},{"t":"The Last Story","p":["Wii"],"r":"August 14","l":"https://en.wikipedia.org/wiki/The_Last_Story"},{"t":"The Legend of Dragoon","p":["PlayStation Network"],"r":"May 1","l":"https://en.wikipedia.org/wiki/The_Legend_of_Dragoon"},{"t":"The Legend of Nayuta: Boundless Trails","p":["PlayStation Portable"],"d":"Nihon Falcom","u":"NIS America, Nihon Falcom","g":"Action role-playing","r":"July 26, 2012","l":"https://en.wikipedia.org/wiki/The_Legend_of_Nayuta:_Boundless_Trails","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7ouy.jpg","s":"Nayuta no Kiseki is an action role-playing game that was released on July 26th, 2012. The title has a completely new setting, new characters and even a new game system from previous \"Kiseki\" games. It is also the first game in the Kiseki series to drop the \"Legend of Heroes\" title."},{"t":"The Lord of the Rings Online: Riders of Rohan","p":["Windows"],"u":"Turbine, Inc.","r":"October 15, 2012"},{"t":"The Lost City","p":["iOS","Android"],"d":"Fire Maple Games","u":"Fire Maple Games","g":"Adventure game","r":"January 31, 2012","l":"https://en.wikipedia.org/wiki/The_Lost_City_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/dosiygrdu1rrvvnwascs.jpg","s":"Mobile offering inspired by classic point and click adventure games!"},{"t":"The Naked Gun: ICUP","p":[],"l":"https://en.wikipedia.org/wiki/The_Naked_Gun:_ICUP"},{"t":"The Pinball Arcade","p":["Xbox 360","PlayStation 3","PlayStation Vita"],"r":"April 4","l":"https://en.wikipedia.org/wiki/The_Pinball_Arcade"},{"t":"The Political Machine 2012","p":["Windows"],"d":"Stardock","u":"Stardock","g":"Government simulation","r":"July 31, 2012","l":"https://en.wikipedia.org/wiki/The_Political_Machine_2012","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co441g.jpg","s":"Do you have what it takes to be president?\nPlay as more than 20 candidates including Barack Obama, Mitt Romney, Rick Santorum, Ron Paul, Newt Gingrich or create your own candidate from scratch.\nPlayers take to the campaign trail against a computer controlled opponent or a human challenger over the Internet. The goal: win the hearts and minds of America's voters to achieve victory in the 2012 presidential election."},{"t":"The Republia Times","p":["Browser"],"d":"Lucas Pope","g":"Indie","r":"April 2012","l":"https://en.wikipedia.org/wiki/The_Republia_Times","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7dit.jpg","s":"The Republia Times is a free-to-play indie browser video game created by Lucas Pope, released in April 2012. In the game, the player takes the role of the editor of a newspaper torn between personal opposition to the government and threats to the lives of the editor's wife and children if the editor does not generate loyalty among the population.\n\nOriginally created as a warm up for a Ludum Dare game jam, The Republia Times was nominated in two categories in the Games for Change Awards."},{"t":"The Room","p":["iOS"],"d":"Fireproof Games","u":"Fireproof Games, Team17","g":"Puzzle","r":"September 12, 2012","l":"https://en.wikipedia.org/wiki/The_Room_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co27bf.jpg","s":"A mysterious invitation leads to the attic of an abandoned house. In the room is a cast-iron safe laced with strange carvings and on top, a note from your distant companion. It promises something ancient and astonishing concealed in the iron chamber - you need only find a way in."},{"t":"The Sandbox","p":["iOS","Android","Windows"],"d":"Pixowl","u":"Pixowl","g":"Sandbox game","r":"May 15, 2012","l":"https://en.wikipedia.org/wiki/The_Sandbox_(2012_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8x73.jpg","s":"The Sandbox is a unique world building & crafting game featuring over 200+ physics elements presented in 2D pixel blocks that can interact with each others. Players can craft amazing worlds, create pixel art, chain reactions, chiptune music, advanced contraptions, electric circuits or just play with physics.\n\nPlay with basic elements ranging from simple water, stone, sand, wood, glass, lava, fire, to more complex: electricity, metal, virus, antivirus,heater, cooler, lasers, pipes, gems, sensors, leds TNT, C4, crosswire, conveyor belt, music instruments etc."},{"t":"The Sea Will Claim Everything","p":["Windows"],"d":"Jonas & Verena Kyratzes","u":"Jonas Kyratzes","g":"Adventure, visual novel","r":"May 23, 2012","l":"https://en.wikipedia.org/wiki/The_Sea_Will_Claim_Everything"},{"t":"The Secret World","p":["Windows"],"g":"Puzzle, Role-playing (RPG), Adventure","r":"July 3","l":"https://en.wikipedia.org/wiki/The_Secret_World","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ub8.jpg","s":"The Secret World is a massively-multiplayer online world with a unique modern-day setting and unparalleled storytelling. Imagine if every myth, conspiracy theory and urban legend was true--a world where you align with secret societies and face the looming darkness."},{"t":"The Silent Age","p":["iOS","Android","Windows Phone","Fire OS","Windows","macOS","PlayStation Vita"],"d":"House on Fire","g":"Point and click adventure game","r":"December 6, 2012","l":"https://en.wikipedia.org/wiki/The_Silent_Age","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2k29.jpg","s":"Lose yourself in The Silent Age, the thrilling point-and-click adventure with over seven million mobile downloads, completely revamped and updated for PC.\nThe Silent Age is an unforgettable experience. Can you, a simple janitor and literally, “the average Joe,” save humankind?"},{"t":"The Simpsons Arcade Game","p":["Xbox 360","PlayStation Network"],"r":"February 3","l":"https://en.wikipedia.org/wiki/The_Simpsons_Arcade_Game"},{"t":"The Simpsons: Tapped Out","p":["iOS"],"g":"Simulator, Adventure","r":"March 1","l":"https://www.igdb.com/games/the-simpsons-tapped-out","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2jg2.jpg","s":"The Simpsons: Tapped Out is a freemium mobile game for iOS and Android, based on the American animated series The Simpsons. It allows users to create and maintain their own version of Springfield using familiar characters and buildings. The game is constantly being updated with new, often season-specific content, for example during holidays like Thanksgiving, and Treehouse of Horror episodes-related content for Halloween. Not limited to English-speaking players, the game is available in many languages such as French, Italian, German, Simplified Chinese and Brazilian Portuguese. The game was developed and published by EA Mobile and launched in the EU on February 29, 2012 and in US on March 1, 2012 for iOS and February 6, 2013 for Android. The game was released for Kindle Fire devices in several markets on June 24, 2013. According to its own estimates, EA generated over $130 million in revenue since the game's release. For BlackBerry 10, the Android version of the game can be downloaded via Amazon Appstore."},{"t":"The Sims 3: Seasons","p":[],"l":"https://en.wikipedia.org/wiki/The_Sims_3:_Seasons"},{"t":"The Sims 3: Showtime","p":["Windows","macOS"],"r":"March 6"},{"t":"The Sims 3: Supernatural","p":["Windows","macOS"],"r":"September 4"},{"t":"The Snowman and the Snowdog","p":["iOS","Android"],"r":"December 9","l":"https://en.wikipedia.org/wiki/The_Snowman_and_the_Snowdog#Video_game"},{"t":"The Splatters","p":["Xbox 360"],"r":"April 11","l":"https://en.wikipedia.org/wiki/The_Splatters"},{"t":"The Testament of Sherlock Holmes","p":["Windows","PlayStation 3","Xbox 360"],"g":"Point-and-click, Puzzle, Adventure","r":"September 25","l":"https://en.wikipedia.org/wiki/The_Testament_of_Sherlock_Holmes","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qsi.jpg","s":"The Testament of Sherlock Holmes immerses you in 1898 London as you conduct an incredible investigation.\n\nAll the evidence suggests our hero is the main suspect in a case involving theft, fraud and double-crossings. Unable to prove his own innocence, Holmes is rapidly losing London's trust as doubt spreads through the city like wildfire. Even Doctor Watson's faith in his friend begins to waver, as the famous detective flees Scotland Yard and raises further suspicion; prowling around at night, destruction of evidence... would Holmes go so far as to commit murder?\n\nThe complex and decidedly-mature storyline surrounds a particularly tricky investigation, in which each and every puzzle will challenge both insight and wits!\n\nAs Sherlock Holmes, you will use the detective's full repertoire: handle and inspect clues, reenact crimes and use the game's new deduction system to draw your own conclusions.\n\nChoose your questioning approach to catch characters off guard and gather valuable information. Face an open investigation, and decide which leads to follow and which to ignore."},{"t":"The Undead Syndrome","p":["Xbox 360"],"r":"July 30"},{"t":"The Unfinished Swan","p":["PlayStation Network"],"g":"Puzzle, Adventure","r":"October 23","l":"https://en.wikipedia.org/wiki/The_Unfinished_Swan","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3sp2.jpg","s":"The Unfinished Swan is a game about exploring the unknown.\n\nThe player is a young boy chasing after a swan who has wandered off into a surreal, unfinished kingdom. The game begins in a completely white space where players can throw paint to splatter their surroundings and reveal the world around them."},{"t":"The Ville","p":[],"d":"Zynga","g":"social simulation","r":"June 30, 2012","l":"https://en.wikipedia.org/wiki/The_Ville_(video_game)"},{"t":"The Walking Dead","p":["Xbox 360","PlayStation 3","iOS","macOS","Windows"],"d":"Telltale Games","u":"Sony Computer Entertainment, Telltale Games","g":"Point-and-click, Puzzle, Adventure","r":"April 24, 2012","l":"https://www.igdb.com/games/the-walking-dead","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2j1g.jpg","s":"The Walking Dead: Season One (also known as The Walking Dead: The Game) is an episodic interactive drama graphic adventure video game developed and published by Telltale Games. Based on Robert Kirkman's The Walking Dead comic book series, the game consists of five episodes, released between April and November 2012. It is available for Android, iOS, Kindle Fire HDX, Microsoft Windows, Mac OS X, PlayStation 3, PlayStation Vita, Xbox 360, PlayStation 4 and Xbox One. The game is the first of The Walking Dead video game series published by Telltale."},{"t":"The Walking Dead: A Telltale Games Series","p":["PlayStation 3","Windows","Xbox 360"],"u":"Telltale Games","r":"November 21, 2012","l":"https://en.wikipedia.org/wiki/The_Walking_Dead_(video_game)"},{"t":"The Walking Dead: Episode 1 – A New Day","p":["Windows","PlayStation Network","macOS","Xbox 360","iOS"],"r":"April 25","l":"https://en.wikipedia.org/wiki/The_Walking_Dead_(2012_video_game)"},{"t":"The Walking Dead: Episode 2 – Starved for Help","p":["Windows","macOS","PlayStation Network","Xbox 360","iOS"],"r":"June 27","l":"https://en.wikipedia.org/wiki/The_Walking_Dead_(2012_video_game)"},{"t":"The Walking Dead: Episode 3 – Long Road Ahead","p":["PlayStation Network","Windows","Xbox 360"],"r":"August 28","l":"https://en.wikipedia.org/wiki/The_Walking_Dead_(2012_video_game)"},{"t":"The Walking Dead: Episode 4 – Around Every Corner","p":["PlayStation Network","Windows","Xbox 360"],"r":"October 9","l":"https://en.wikipedia.org/wiki/The_Walking_Dead_(2012_video_game)"},{"t":"The Walking Dead: Episode 5 – No Time Left","p":["Windows","PlayStation 3","Xbox 360","macOS","iOS"],"u":"Telltale Games","r":"November 21, 2012","l":"https://en.wikipedia.org/wiki/The_Walking_Dead_(video_game)"},{"t":"The War Z","p":["Windows"],"r":"December 17","l":"https://en.wikipedia.org/wiki/The_War_Z"},{"t":"The Witch's House","p":["Windows"],"d":"Fummy","u":"Fummy, Dangen Entertainment","g":"Adventure horror","r":"October 3, 2012","l":"https://en.wikipedia.org/wiki/The_Witch's_House","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co26bo.jpg","s":"The Witch's House falls within the tradition of Japanese horror RPGs with heavy emphasis on puzzle-solving and jump scares. Among other entries in the genre such as Ib and Ao Oni, The Witch's House surprised fans with pixel-art that conceals truly frightening horror.\nThe Witch's House is deliberately designed with traps at almost every turn--sudden death is unpredictable and it keeps players on their toes. Anything can happen at any time."},{"t":"The Witcher 2: Assassins of Kings","p":["macOS"],"r":"October 18"},{"t":"The Witcher 2: Assassins of Kings Enhanced Edition","p":["Xbox 360"],"g":"Role-playing (RPG), Adventure","r":"April 17","l":"https://www.igdb.com/games/the-witcher-2-assassins-of-kings-enhanced-edition","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ykc.jpg","s":"All existing owners of The Witcher 2 received free upgrades to the Enhanced Edition, and could pre-load the update starting 11 April 2012. All new copies on PC and Xbox 360 shipped with the additional content on board. The Witcher 2: Assassins of Kings - Enhanced Edition added over 10GB of new content, including four hours of gameplay, arena mode, new tutorial, 36 minutes of cinematics including a new intro created by Platige Image and an outro, as well as a host of fixes to gameplay and the interface."},{"t":"The World Ends with You","p":["iOS"],"r":"August 27","l":"https://en.wikipedia.org/wiki/The_World_Ends_with_You"},{"t":"Theatrhythm Final Fantasy","p":["Nintendo 3DS","iOS"],"g":"Music, Role-playing (RPG)","r":"July 3","l":"https://en.wikipedia.org/wiki/Theatrhythm_Final_Fantasy","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2x5n.jpg","s":"Theatrhythm Final Fantasy features a hybrid of music rhythm gameplay with RPG elements. Adorably re-designed heroes from the catalogue of FINAL FANTASY titles will set out on an adventure to combat memorable villains with the rhythmic taps of the player's stylus."},{"t":"They Bleed Pixels","p":["Windows","macOS","Linux","Steam"],"d":"Spooky Squid Games","u":"Spooky Squid Games","g":"Platform","r":"August 29, 2012","l":"https://en.wikipedia.org/wiki/They_Bleed_Pixels","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2l3w.jpg","s":"They Bleed Pixels is a fiendishly difficult action platformer inspired by H.P. Lovecraft and classic horror. Rendered in a distinct visual style that blends pixel art with paper and ink textures, They Bleed Pixels is a singular mix of intense platforming and fierce beat-em-up action. At the core of its fighting system is a simple one-button combat scheme with surprising depth and versatility. Button mashing is discouraged while kicking shadowy monsters into saws, pits and spikes is rewarded, thanks to a unique system that lets you earn and place your own checkpoints through stylish kills. The fancier your kills, the faster you fill the checkpoint meter."},{"t":"Thirty Flights of Loving","p":["Windows","macOS"],"d":"Blendo Games","u":"Blendo Games","g":"Adventure","r":"August 20, 2012","l":"https://en.wikipedia.org/wiki/Thirty_Flights_of_Loving","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2edo.jpg","s":"Explore the world of Thirty Flights of Loving through a first-person short story. In this sequel to Gravity Bone, take a deep dive with high-flying schemers, lovelorn criminals, and more stray kittens than you can shake a stick at. Saddle up, gunslinger."},{"t":"Thomas Was Alone","p":["Windows"],"g":"Platform, Puzzle, Adventure, Indie","r":"November 12","l":"https://en.wikipedia.org/wiki/Thomas_Was_Alone","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8ak5.jpg","s":"Thomas Was Alone is an indie minimalist 2D platformer about friendship and jumping and floating and anti-gravity. Guide a group of rectangles through a series of obstacles, using their different skills together to get to the end of each environment."},{"t":"ThunderCats","p":["Nintendo DS"],"d":"Aspect Co.","u":"Namco Bandai Games","g":"Platform","r":"October 30, 2012","l":"https://en.wikipedia.org/wiki/ThunderCats_(2012_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2df2.jpg","s":"ThunderCats is a side-scrolling video game that is based on the original animated television series ThunderCats. The game was published in 1988 by Elite Systems Ltd for home computers.\n\nThe player takes control of the character Lion-O and maneuvers him through 14 side scrolling levels to search for the missing Eye of Thundera. Lion-O begins the game equipped with the Sword of Omens (with the Eye of Thundera missing from the hilt) but has the option to switch throughout the game between the sword and a short range energy gun. In several levels, Lion-O will jump into a flying vehicle that can fire in a similar manner as the short range energy gun. The first four levels of the game are a part of the Garden of the Elementals, where the player may choose the order they play each of the themed levels, consisting of fire, water, air, and earth.\n\nEach level has a time limit to complete it; when it expires, Mumm-Ra appears and more goons and villains appear to make it tougher for Lion-O to finish."},{"t":"Tiger & Bunny","p":[],"l":"https://en.wikipedia.org/wiki/Tiger_&_Bunny"},{"t":"Tiger Woods PGA Tour 13","p":["PlayStation 3","Xbox 360"],"r":"March 27","l":"https://en.wikipedia.org/wiki/Tiger_Woods_PGA_Tour_13"},{"t":"Time Travelers","p":["Nintendo 3DS","PlayStation Vita","PlayStation Portable"],"d":"Level-5","u":"Level-5","g":"Playing cinema, adventure, visual novel","r":"July 12, 2012","l":"https://en.wikipedia.org/wiki/Time_Travelers_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co30gz.jpg","s":"Time Travelers is a cinematic interactive drama game with multiple choices. Usually, if a main character makes a mistake or dies, they can reverse time to perform the right action. Their choices will be displayed in the flowchart. The right choices are necessary to advance the story. A final choice determines which ending the player gets. The game has quick time events, in which players must perform actions by quickly pressing the right button."},{"t":"Tiny & Big in Grandpa's Leftovers","p":["Windows","macOS","Linux"],"d":"Black Pants Game Studio","u":"Black Pants Game Studio","g":"Puzzle-platform","r":"June 19, 2012","l":"https://en.wikipedia.org/wiki/Tiny_&_Big_in_Grandpa's_Leftovers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2h2e.jpg","s":"Tiny & Big, a comic styled jump and slice platformer, gives you the unique ability to shape a whole world at your will! You are Tiny, a nerdy inventor who tries to reclaim his most beloved possession: Grandpa's white, fine rib underpants! On his journey through a forsaken desert he will meet mysterious creatures, no clowns, a taxi robot and his arch enemy: Big!"},{"t":"Tiny Troopers","p":["iOS","Android","Windows","macOS","Windows Phone"],"d":"Kukouri Mobile Entertainment","u":"Chillingo, Iceberg Interactive, Game Troopers","g":"Multidirectional shooter","r":"June 7, 2012","l":"https://en.wikipedia.org/wiki/Tiny_Troopers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co44p7.jpg","s":"Tiny Troopers puts you in command of a team of small soldiers. Guide them through 30 deadly missions with varied objectives: destroy enemy armoured formations, save hostages and eliminate enemy generals, to name but just a few."},{"t":"Tiny Wings 2","p":["iOS"],"r":"July 12","l":"https://en.wikipedia.org/wiki/Tiny_Wings"},{"t":"Titans Mobile","p":["Android","iOS"],"r":"August 25"},{"t":"ToeJam & Earl in Panic on Funkotron","p":["PlayStation Network","Xbox 360"],"r":"November 6","l":"https://en.wikipedia.org/wiki/ToeJam_%26_Earl_in_Panic_on_Funkotron"},{"t":"Tokyo Jungle","p":["PlayStation Network"],"g":"Role-playing (RPG), Simulator, Strategy, Adventure","r":"September 25","l":"https://en.wikipedia.org/wiki/Tokyo_Jungle","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4ajh.jpg","s":"In Tokyo Jungle, everything is the enemy, and only the strongest will survive!\n\nWith over 50 playable animals to choose from, unleash your inner beast to hunt your way to the top of Tokyo's post-apocalyptic food chain. Whether in Story or Survival Mode, you never know where your next meal will come from or the dangers you'll face, so be prepared for anything and everything. Forage through this desolate but dangerous city to complete story-based challenges using a variety of survival skills, from all-out attack to stealth. Beware-- you are not the only animal out there hunting for survival!"},{"t":"Tom Clancy's Ghost Recon: Future Soldier","p":["PlayStation 3","Xbox 360","Windows"],"g":"Shooter, Adventure","r":"May 22","l":"https://www.igdb.com/games/tom-clancy-s-ghost-recon-future-soldier","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ypp.jpg","s":"The story of a Vengeance, the history of a secret war.\n\nWhen a stolen military grade bomb takes out a Ghost squad, a new Ghost Unit must track down the source of the weapons. But the trail Kozak, Ghost Lead, Pepper and 30K follow leads around the world, into the corridors of power where rebellion and war are brewing. Soon, the Ghosts are all that stands between the world and a devastating global conflict."},{"t":"Tomba!","p":["PlayStation Network"],"r":"June 19","l":"https://en.wikipedia.org/wiki/Tomba!"},{"t":"Tony Hawk's Pro Skater HD","p":["Xbox 360","PlayStation Network","Windows"],"g":"Sport, Arcade","r":"July 18","l":"https://en.wikipedia.org/wiki/Tony_Hawk%27s_Pro_Skater_HD","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co494x.jpg","s":"Tony Hawk's Pro Skater HD takes the best elements of the classic THPS games and gives them a fresh update to create an all new skateboarding experience."},{"t":"Top Gun: Hard Lock","p":["PlayStation 3","Windows","Xbox 360"],"r":"March 6","l":"https://en.wikipedia.org/wiki/Top_Gun_(video_game)"},{"t":"Top Trumps: NBA All Stars","p":["Nintendo 3DS"],"r":"October 7"},{"t":"Torchlight II","p":["Windows","macOS"],"g":"Role-playing (RPG), Hack and slash/Beat 'em up, Adventure, Indie","r":"September 20","l":"https://en.wikipedia.org/wiki/Torchlight_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co25z8.jpg","s":"Torchlight II features randomly generated dungeons and numerous types of monsters to fight for loot. Torchlight II is an action RPG as its predecessor, but features overland areas with multiple hub towns, and a longer campaign. Players are able to customize character appearance with choice of sex, face, hair style and hair color. Additionally, several elements from the first game return, such as pets and fishing.\nThe game features four playable character classes. Each class has 3 skill trees to choose from which enable customization within each class."},{"t":"Total War Battles: Shogun","p":["iOS","Windows","Android"],"d":"Creative Assembly","u":"Sega","g":"Real-time strategy","r":"April 19, 2012","l":"https://en.wikipedia.org/wiki/Total_War_Battles:_Shogun","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocbtd.jpg","s":"Specifically developed for touchscreen platforms, Total War Battles: Shogun is a real-time strategy game from the makers of the award-winning Total War series.\n\nTotal War Battles delivers quick-fire, tactical combat balanced with intuitive building and unit management. All set in a beautifully illustrated Medieval Japan."},{"t":"Total War: Shogun 2 – Fall of the Samurai","p":["Windows"],"r":"March 23"},{"t":"Touch My Katamari","p":["PlayStation Vita"],"r":"February 22","l":"https://en.wikipedia.org/wiki/Touch_My_Katamari"},{"t":"Towns","p":["Windows","macOS","Linux"],"d":"SMP, Florian Frankenberger","u":"SMP","g":"Simulation","r":"November 7, 2012","l":"https://en.wikipedia.org/wiki/Towns_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2rq8.jpg","s":"This game was released in 2012 on Steam through Steam Greenlight while still in its beta. The developers decided to abandon its development in 2014, leaving the game in an unfinished state but available for purchase.\n\n\"The game brings a fresh new take on the city building/management genre by introducing many RPG features.\n\nIn Towns you manage a settlement on top of an active dungeon. Instead of playing the hero who delves deep into the dungeon, how about playing the town that houses and caters to the hero's needs?\n\nBoth the RPG and strategic aspects will be fleshed out over a series of sprawling dungeons.\n\nAttract travelling heroes that will independently explore the dungeons below, fight off monsters, gain levels, special skills and collect the best loot they can find in order to clear the land of all evil!\n\nCraft unique weapons, trade with exotic items, obtain randomized loot, set up devious death traps and build a settlement capable of holding back the forces that come up from the depths!\""},{"t":"Township","p":["iOS","macOS","Facebook","Browser"],"d":"Playrix","u":"Playrix","g":"Construction and management simulation, city-building","r":"December 24, 2012","l":"https://en.wikipedia.org/wiki/Township_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaug6.jpg","s":"Township is a unique blend of city building and farming!\nBuild your dream town! Harvest crops, process them at your facilities, and sell goods to develop your town. Trade with distant islands. Open restaurants, cinemas and other community buildings to give life in your town special flavor. Explore the mine to get resources and find ancient artifacts. Run your own zoo and collect animals from around the world.\nAre you ready to build your dream? Let's get started!"},{"t":"Toy Defense","p":[],"l":"https://en.wikipedia.org/wiki/Toy_Defense"},{"t":"Toy Story Mania!","p":["PlayStation 3","Xbox 360"],"r":"October 30","l":"https://en.wikipedia.org/wiki/Toy_Story_Mania!_(video_game)"},{"t":"Transformers: Fall of Cybertron","p":["Windows","PlayStation 3","Xbox 360"],"g":"Shooter, Adventure","r":"August 21","l":"https://www.igdb.com/games/transformers-fall-of-cybertron","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2scl.jpg","s":"Transformers: Fall of Cybertron transports you to the final days of the planet Cybertron where you will experience the darkest hours of the apocalyptic war between the Autobots and Decepticons.\n\nEmbark on an adrenaline-fueled journey through a wide range of missions and massive environments designed around each character's unique abilities. Fight through both sides of the most epic battles leading to their legendary exodus from their homeworld. In addition, players experience action in the form of new Transformer bot types Combaticons, Insecticons, and Dinobots."},{"t":"Transformers: Prime – The Game","p":["Wii","Nintendo DS","Nintendo 3DS","Wii U"],"r":"October 30"},{"t":"Treasures Of Montezuma: Blitz","p":["PlayStation Vita"],"r":"April 10"},{"t":"Trials Evolution","p":["Xbox 360"],"u":"Microsoft Studios","g":"Platform, Racing","r":"April 18, 2012","l":"https://en.wikipedia.org/wiki/Trials_Evolution","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2src.jpg","s":"Trials Evolution is a downloadable 2.5D platform racing game developed by RedLynx and published by Microsoft Studios. Successor to 2009's critically acclaimed Trials HD.\nThe game uses 3D graphics, but is played on a 2D plane, so the rider can only move forwards and backwards. Players can also control the bike's pitch at slow speeds or while in the air.\nPlayers can also design and share their own maps utilizing the in-game editor. As with its predecessor, Trials HD."},{"t":"Tribes: Ascend","p":["Windows"],"g":"Shooter, Role-playing (RPG), Sport, Adventure","r":"April 12","l":"https://www.igdb.com/games/tribes-ascend","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1xxh.jpg","s":"Tribes: Ascend is the fourth major installation into this series of multiplayer FPS, centred around speed and pure teamwork, with the primary game mode of capture the flag."},{"t":"Trine 2","p":["Linux"],"r":"March 31","l":"https://en.wikipedia.org/wiki/Trine_2"},{"t":"Trine 2: Director's Cut","p":["Wii U"],"r":"November 18","l":"https://en.wikipedia.org/wiki/Trine_2"},{"t":"Trine 2: Goblin Menace","p":["Windows","macOS"],"r":"September 6","l":"https://en.wikipedia.org/wiki/Trine_2#Expansions"},{"t":"Tropico 3: Gold Edition","p":["macOS"],"r":"January 26","l":"https://en.wikipedia.org/wiki/Tropico_3"},{"t":"Tropico 4: Modern Times","p":["Xbox 360"],"r":"March 27","l":"https://en.wikipedia.org/wiki/Tropico_4#Expansion"},{"t":"Turma do Chico Bento","p":["Browser","Facebook"],"d":"Insolita Studios","u":"Level Up! Games","g":"Simulation","r":"September 3, 2012","l":"https://en.wikipedia.org/wiki/Turma_do_Chico_Bento_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6knr.jpg","s":"Turma do Chico Bento was a social farm simulation game developed by Insolita Studios and published by Level Up! in partnership with Mauricio de Sousa Produções. In the game, the player needed to take care of his farm, planting and taking care of the animals, while participating in adventures as if he were in a story of Chico Bento, the “caipirinha” created by Mauricio de Sousa."},{"t":"TwinGo!","p":["iOS"],"d":"SpaceNoize","u":"Chillingo","g":"Puzzle","r":"March 8, 2012","l":"https://en.wikipedia.org/wiki/TwinGo!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coa7hy.jpg","s":"TwinGo! was a 2012 puzzle game developed by Portuguese developer SpaceNoize and published by Chillingo. It was released for iOS on March 8, 2012."},{"t":"Twisted Metal","p":["PlayStation 3"],"g":"Shooter, Racing","r":"February 14","l":"https://en.wikipedia.org/wiki/Twisted_Metal_(2012_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2sjc.jpg","s":"Twisted Metal is a vehicle combat video game developed by Eat Sleep Play and published by Sony Computer Entertainment for the PlayStation 3. It is a reboot of the Twisted Metal franchise. The game was originally planned to be released in October 2011 but was delayed to early 2012."},{"t":"UEFA Euro 2012","p":["Windows","PlayStation 3","Xbox 360"],"r":"April 24","l":"https://en.wikipedia.org/wiki/UEFA_Euro_2012_(video_game)"},{"t":"UFC Undisputed 3","p":["PlayStation 3","Xbox 360"],"r":"February 14","l":"https://en.wikipedia.org/wiki/UFC_Undisputed_3"},{"t":"Ultima Ratio Regum","p":["Windows"],"g":"Roguelike, puzzle","r":"July 9, 2012","l":"https://en.wikipedia.org/wiki/Ultima_Ratio_Regum_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4o3a.jpg","s":"Ultima Ratio Regum (\"the last argument of kings\") is a game which aims to integrate thematic content on historiography, philosophical idealism and the rise of modernist grand narratives, with the deep, complex and challenging gameplay one expects from a \"classic\" roguelike (and, of course, an ANSI display and permadeath). Set approximately around the Scientific Revolution, the player is tasked with discovering a conspiracy via identifying procedurally-generated clues hidden throughout the world's cultures, religions and societies; the game features extensive procedural generation of everything from tombs and religious altars to (in the future) paintings and sculptures, any or all of which may contain the clues required in a given playthrough."},{"t":"Ultimate Marvel vs. Capcom 3","p":["PlayStation Vita"],"r":"February 22","l":"https://en.wikipedia.org/wiki/Ultimate_Marvel_vs._Capcom_3"},{"t":"UltraStar","p":["Windows","Linux","macOS"],"d":"Loud Arts","u":"Loud Arts","g":"Music game","l":"https://en.wikipedia.org/wiki/UltraStar","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobn6t.jpg","s":"UltraStar is a clone of SingStar, a music video game by Polish developer Patryk \"Covus5\" Cebula. UltraStar lets one or several players score points by singing along to a song or music video and match the pitch of the original song. UltraStar displays lyrics as well as the correct notes similar to a piano roll."},{"t":"Unchained Blades","p":["PlayStation Portable"],"r":"June 26","l":"https://en.wikipedia.org/wiki/Unchained_Blades"},{"t":"Uncharted: Fight for Fortune","p":["PlayStation Vita"],"r":"December 4"},{"t":"Uncharted: Golden Abyss","p":["PlayStation Vita"],"r":"February 15"},{"t":"Under Defeat HD","p":["PlayStation 3"],"r":"November 28","l":"https://en.wikipedia.org/wiki/Under_Defeat"},{"t":"Under Night In-Birth","p":["Arcade","PlayStation 3","Windows","PlayStation 4","PlayStation Vita"],"d":"French-Bread, Ecole Software","u":"Sega, Arc System Works, Aksys Games, NIS America, PQube, Clear River Games, Arc System Works","g":"Fighting, visual novel","l":"https://en.wikipedia.org/wiki/Under_Night_In-Birth","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4gae.jpg","s":"Under Night In-Birth is a 2D fighting game co-developed by Ecole Software and French-Bread. It received many updates for adjustments and characters."},{"t":"Unit 13","p":["PlayStation Vita"],"r":"March 6","l":"https://en.wikipedia.org/wiki/Unit_13"},{"t":"Unmechanical","p":["Windows"],"r":"August 9","l":"https://en.wikipedia.org/wiki/Unmechanical"},{"t":"Unstoppable Gorg","p":["Windows","macOS","iOS"],"d":"Futuremark","u":"Headup Games","g":"Tower defense","r":"January 19, 2012","l":"https://en.wikipedia.org/wiki/Unstoppable_Gorg","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3pcl.jpg","s":"DANGER! Earth is under attack from a vast armada of flying saucers. Only you can stop the invasion of these relentless alien monsters - don't let a single one through!\n\nGet ready for a revolution in tower defense that will send you spinning. Defend the solar system by sending satellites into orbit around planets, moons and space stations. Create the perfect defense by rotating orbits to move your satellites into the best positions. Do you have what it takes to defeat the Gorg and save the solar system? Find out in more than 40 levels of thrilling tower defense action inspired by classic sci-fi films from the 1950s."},{"t":"Unvanquished","p":[],"l":"https://en.wikipedia.org/wiki/Unvanquished_(video_game)"},{"t":"Uta no Prince-sama","p":[],"l":"https://en.wikipedia.org/wiki/Uta_no_Prince-sama"},{"t":"Vampire Season Monster Defense","p":["iOS","Android"],"d":"Brainz","g":"real-time strategy","r":"June 28, 2012","l":"https://en.wikipedia.org/wiki/Vampire_Season_Monster_Defense"},{"t":"Vector","p":["Android","iOS","Windows"],"d":"Nekki","u":"Nekki","g":"Platform","r":"August 28, 2012","l":"https://en.wikipedia.org/wiki/Vector_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4t1l.jpg","s":"Vector is an exciting, arcade-style game featuring you as the exceptional free runner who won’t be held down by the system. In this totalitarian world freedom and individually is nothing more than a distant dream. But the heart of a freerunner is strong, and so you break free."},{"t":"Velocity","p":["PlayStation Portable"],"d":"FuturLab, Curve Studios","u":"FuturLab, Curve Studios","g":"Shoot 'em up","r":"May 15, 2012","l":"https://en.wikipedia.org/wiki/Velocity_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wii.jpg","s":"Velocity is a shoot 'em up involving navigating the Quarp Jet: a teleporting spacecraft – through space, whilst avoiding and defeating enemies using bombs that can be flung in cardinal directions. The main goal of the game is to rescue stranded ships."},{"t":"Vessel","p":["Windows"],"r":"March 1","l":"https://en.wikipedia.org/wiki/Vessel_(video_game)"},{"t":"Victorious: Taking the Lead","p":["Nintendo DS","Wii"],"r":"November 13"},{"t":"Viking: Battle for Asgard","p":["Windows"],"r":"October 17"},{"t":"Virtua Fighter 2","p":["PlayStation Network","Xbox 360"],"r":"November 27","l":"https://en.wikipedia.org/wiki/Virtua_Fighter_2"},{"t":"Virtua Tennis 4: World Tour Edition","p":["PlayStation Vita"],"r":"February 22","l":"https://en.wikipedia.org/wiki/Virtua_Tennis_4"},{"t":"Virtua Tennis Challenge","p":["iOS"],"r":"May 24","l":"https://en.wikipedia.org/wiki/Virtua_Tennis_Challenge"},{"t":"Virtual Pool 4","p":[],"l":"https://en.wikipedia.org/wiki/Virtual_Pool_4"},{"t":"Vox","p":[],"l":"https://en.wikipedia.org/wiki/Vox_(video_game)"},{"t":"VS. Racing 2","p":["iOS"],"d":"Maciek Drejak Labs","u":"Maciek Drejak Labs","g":"Racing","r":"September 6, 2012","l":"https://en.wikipedia.org/wiki/VS._Racing_2"},{"t":"Wakfu","p":["Windows","Linux","macOS"],"g":"Role-playing (RPG), Strategy, Turn-based strategy (TBS), Tactical, Adventure, Indie","r":"February 29","l":"https://en.wikipedia.org/wiki/Wakfu","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coatkr.jpg","s":"Immerse yourself in the WAKFU universe with this free to play MMORPG. Select your class, travel the world, meet adventurers to challenge powerful monsters in epic turn-based battles.\nParticipate in the kingdom’s economy and politics and create your own legend!"},{"t":"Waking Mars","p":["Windows","macOS","iOS","Android"],"r":"March 8","l":"https://en.wikipedia.org/wiki/Waking_Mars"},{"t":"War of the Monsters","p":["PlayStation Network"],"r":"July 31","l":"https://en.wikipedia.org/wiki/War_of_the_Monsters"},{"t":"War of the Roses","p":["Windows"],"r":"October 2","l":"https://en.wikipedia.org/wiki/War_of_the_Roses_(video_game)"},{"t":"Wargame: European Escalation","p":["Windows"],"r":"February 23"},{"t":"Warlock: Master of the Arcane","p":["Windows"],"d":"1C:Ino-Co Plus","u":"Paradox Interactive","g":"Turn-based strategy","r":"May 8, 2012","l":"https://en.wikipedia.org/wiki/Warlock:_Master_of_the_Arcane","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ruk.jpg","s":"Research and master dozens of spells, conjure powerful enchantments and discover awesome spell combinations. Command an expansive range of units, all with unique abilities. Engage in epic battles with large armies marching across the landscape. Command the game Fight on the side of one of the eight gods."},{"t":"Warp","p":["Xbox 360","Windows","PlayStation Network"],"r":"February 15","l":"https://en.wikipedia.org/wiki/Warp_(2012_video_game)"},{"t":"Warriors Orochi 3","p":["PlayStation 3","Xbox 360"],"r":"March 20","l":"https://en.wikipedia.org/wiki/Warriors_Orochi_3"},{"t":"Warriors Orochi 3: Hyper","p":["Wii U"],"r":"November 18","l":"https://en.wikipedia.org/wiki/Warriors_Orochi_3"},{"t":"Warsow","p":["Windows","macOS","Linux"],"r":"July 28","l":"https://en.wikipedia.org/wiki/Warsow_(video_game)"},{"t":"Waveform","p":["Windows","macOS","Linux"],"d":"Eden Industries","u":"Eden Industries","g":"Action","r":"March 20, 2012","l":"https://en.wikipedia.org/wiki/Waveform_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2fyd.jpg","s":"Navigate the beauty and hazards of the solar system while riding on a wave of light in this innovative action-puzzle game. On your journey to restore light to a dying galaxy being consumed by a Singularity, you'll travel from Pluto to the Sun and interact with a wide variety of strange objects, and mind-bending situations that will affect the path of your wave, and the world around you, in interesting ways.\n\nSimple to play but difficult to master, Waveform combines the pure fun of retro arcade titles with all the modern bells and whistles of modern gaming. Colorful graphics and a retro soundtrack accompany 100 levels of increasingly fascinating and wondrous challenges featuring mysterious and fun objects like Wormholes, Particle Accelerators, and the enigmatic Space Squids of Venus."},{"t":"Way of the Samurai 4","p":["PlayStation Network"],"r":"August 21","l":"https://en.wikipedia.org/wiki/Way_of_the_Samurai_4"},{"t":"We Sing Pop!","p":["Wii","Xbox One","PlayStation 4"],"d":"Le Cortex","u":"Nordic Games","g":"Music Video game","r":"March 23, 2012","l":"https://en.wikipedia.org/wiki/We_Sing_Pop!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/vy7kwx6q2os1jmvwtmmw.jpg","s":"We Sing Pop! a brand new addition to the We Sing range of games for Wii it will feature 40 of the greatest pop tracks around.\n\nWe Sing Pop! will be available in Europe and the US on Wii and will feature some of the most well-known pop hits covering four poptastic decades. The look and feel of the game will also replicate a real 'pop' vibe."},{"t":"Weapon Shop de Omasse","p":["Nintendo 3DS"],"d":"Nex Entertainment","u":"Level-5","g":"Role-playing video game, Rhythm game","r":"November 21, 2012","l":"https://en.wikipedia.org/wiki/Weapon_Shop_de_Omasse"},{"t":"When Vikings Attack!","p":["PlayStation 3","PlayStation Vita"],"d":"Clever Beans and XDev Studios Europe","u":"Sony Computer Entertainment","g":"Fighting","r":"November 6, 2012","l":"https://en.wikipedia.org/wiki/When_Vikings_Attack!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co61e6.jpg","s":"When Vikings Attack! plays like an arena melee brawler game. The only hard rule is that throwing objects are only allowed. Players control a small group of civilians fighting hordes of vikings. The objective is to pick up objects and throw to knock out enemies. Every vikings and civilians are fragile to every strike from a thrown object and will be knocked out in one hit. Each time an object collides with a figure, they're knocked out and excluded from the group, but larger or wide objects may even knock out an entire group, resulting in the player being eliminated. Lost civilians can be replaced by recruiting stray people roaming field. The game also features special items to be thrown such as explosive bombs for an area of effect attack."},{"t":"Where's My Perry?","p":["iOS"],"r":"June 28","l":"https://en.wikipedia.org/wiki/Where%27s_My_Perry%3F"},{"t":"Wii Karaoke U","p":["Wii U"],"d":"Xing","u":"Nintendo","g":"Rhythm","r":"December 8, 2012","l":"https://en.wikipedia.org/wiki/Wii_Karaoke_U"},{"t":"Wild Blood","p":["Android","iOS"],"d":"Gameloft","u":"Gameloft","g":"Hack and slash","r":"September 6, 2012","l":"https://en.wikipedia.org/wiki/Wild_Blood_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7rli.jpg","s":"King Arthur has gone mad, fueled by his jealousy toward Lancelot for romancing his wife, Queen Guinevere. In his desperation, Arthur has been tricked by his sister, the all-powerful sorceress Morgana Le Fey, to open the Hellgate and allow all forms of demons to enter the world. Meanwhile, Morgana has captured Guinevere and holds her hostage on the magical island of Avalon.\n\nNow Lancelot needs to confront King Arthur and the evil Morgana in order to free the world from these evil creatures and save Guinevere.\nThe time for Sir Lancelot to face his destiny is now!"},{"t":"Wing Commander Saga: The Darkest Dawn","p":["Windows"],"g":"Space combat simulation","r":"March 22, 2012","l":"https://en.wikipedia.org/wiki/Wing_Commander_Saga:_The_Darkest_Dawn","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/wx84izjj7247gozp9jxm.jpg","s":"Wing Commander Saga: The Darkest Dawn concludes a forty-year galactic struggle between the Terran Confederation and the Kilrathi Empire, an imperialistic, xenophopic alien race. Victory and survival for humanity can only be bought at a terrible cost. Gather your wingmen and face the enemy. Make your mark as the Confederation faces its darkest dawn."},{"t":"Winx Club: Magical Fairy Party","p":["Nintendo DS"],"d":"1st Playable Productions","u":"D3 Publisher, Namco Bandai Games","g":"Simulation","r":"October 30, 2012","l":"https://en.wikipedia.org/wiki/Winx_Club:_Magical_Fairy_Party","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coa0nt.jpg","s":"Girls will embrace the magic within and discover their inner fairy in Winx Club: Magical Fairy Party, through the enchanting story and exciting mini-games filled with fairies, fashion, friendship (and pets) that fans love. Fans can star in the game as their own fairy, interact with their favorite show characters and enroll in the enchanting Alfea School. They will form new friendships, perform spells and plan unforgettable events that include a wondrous ball!"},{"t":"Wipeout 2048","p":["PlayStation Vita"],"r":"February 22","l":"https://en.wikipedia.org/wiki/Wipeout_2048"},{"t":"Wipeout: The Game 3","p":["Wii U"],"r":"November 18"},{"t":"Witch on the Holy Night","p":["Windows"],"d":"Type-Moon","u":"Type-Moon, Aniplex","g":"Visual novel","r":"April 12, 2012","l":"https://en.wikipedia.org/wiki/Witch_on_the_Holy_Night","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6acy.jpg","s":"“Near the end of the Showa Era. (Late 1980s)\nIn the old mansion rumored that a witch lives, Aoko Aozaki who just started learning sorcery and her teacher, a young mage Alice Kuonji, lived together.\nBut as if he was guided by an invisible string of fate, a young boy called Soujuurou Shizuki joins them and a strange communal life begins…”\n\n“Late 1980s. The golden age full of brightness and spirits. The boy who came to the urban city passes by the two witches who live in the present”\n\n“The boy lived a really normal life\nShe lived with pride and confidence\nThe girl lived hidden as if she’s asleep”"},{"t":"Wonderbook: Book of Spells","p":["PlayStation 3"],"r":"November 13","l":"https://en.wikipedia.org/wiki/Book_of_Spells"},{"t":"Word Streak with Friends","p":["iOS","Android"],"d":"Zynga","g":"Word game","l":"https://en.wikipedia.org/wiki/Word_Streak_with_Friends","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/ryibqv0ag9vxljlxzhek.jpg","s":"Scramble With Friends was a boggle clone played online with friends. In June 2015, the game was rebranded as \"Word Streak with Friends\" as part of a major update, before being replaced by \"Boggle with Friends\" after Zynga acquired the Boggle license."},{"t":"World Gone Sour","p":["PlayStation Network","Xbox 360"],"r":"April 10","l":"https://en.wikipedia.org/wiki/World_Gone_Sour"},{"t":"World of Warcraft: Mists of Pandaria","p":["Windows","macOS"],"r":"September 25"},{"t":"WorldBox","p":["macOS","Linux","Browser"],"d":"Maxim Karpenko","g":"Sandbox, god game","r":"September 24, 2012","l":"https://en.wikipedia.org/wiki/WorldBox"},{"t":"Worms Revolution","p":["PlayStation 3","Windows","Xbox 360"],"d":"Team17","u":"Team17","g":"Artillery, Strategy","r":"October 10, 2012","l":"https://en.wikipedia.org/wiki/Worms_Revolution","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1xqw.jpg","s":"Worms Revolution is the latest game in the classic turn-based strategy series to come to the PC, featuring exciting new features and beautiful 3D graphics whilst retaining the classic 2D gameplay that fans love. Choose to play the extensive single player mode which features both campaign and puzzle missions or dive straight into multiplayer warfare via online or local play. For the first time ever see the inclusion of dynamic water, physics objects and worm classes! Customize your experience by choosing what classes you play with, what they look like and even how they speak!"},{"t":"Worms Ultimate Mayhem","p":["PlayStation Network"],"r":"February 14","l":"https://en.wikipedia.org/wiki/Worms_Ultimate_Mayhem"},{"t":"Wraithborne","p":["iOS"],"d":"Alpha Dog Games","u":"Crescent Moon Games","g":"Action role-playing","r":"November 8, 2012","l":"https://en.wikipedia.org/wiki/Wraithborne"},{"t":"WRC 3: FIA World Rally Championship","p":["PlayStation 3","PlayStation Vita","Windows","Xbox 360","OnLive"],"d":"Milestone srl","u":"Milestone srl, Bandai Namco Entertainment","g":"Racing","r":"October 12, 2012","l":"https://en.wikipedia.org/wiki/WRC_3:_FIA_World_Rally_Championship","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co30zw.jpg","s":"The official video game of the 2012 FIA World Rally Championship (WRC), WRC 3 marks a radical departure from the previous titles and sees the team using a completely new graphics and game engine, developed in-house, in order to bring the most advanced WRC driving experience to players. WRC 3 features all the rallies in the 2012 WRC calendar, complete with all leading WRC teams and drivers in the revamped career mode."},{"t":"Wreckateer","p":["Xbox 360"],"r":"July 25","l":"https://en.wikipedia.org/wiki/Wreckateer"},{"t":"Wrecked: Revenge Revisited","p":["PlayStation Network","Xbox 360"],"r":"March 28"},{"t":"WWE '13","p":["PlayStation 3","Xbox 360","Wii"],"g":"Fighting, Platform, Sport, Strategy","r":"October 30","l":"https://en.wikipedia.org/wiki/WWE_%2713","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2sjj.jpg","s":"WWE ’13 transforms WWE gameplay through the introduction of WWE Live, completely changing the way players experience the videogame’s audio and presentation elements. Predator Technology returns to further implement critical gameplay improvements, while fan favourites in WWE Universe Mode and the franchise’s renowned Creation Suite offer the utmost in player freedom.\n\nFurthermore, WWE ’13 focuses on the Attitude Era of the WWF, replacing its Road to WrestleMania Mode with an Attitude Era Mode where the player plays through the Attitude Era. The game gives such characters as Stone Cold Steve Austin and elements as the Monday Night Wars a more important role in the game than in any previous WWE game."},{"t":"WWE WrestleFest","p":["iOS"],"r":"February 21","l":"https://en.wikipedia.org/wiki/WWF_WrestleFest#Remake"},{"t":"XCOM: Enemy Unknown","p":["Xbox 360","Windows","PlayStation 3"],"u":"2K","g":"Role-playing (RPG), Simulator, Strategy, Turn-based strategy (TBS), Tactical","r":"October 8, 2012","l":"https://www.igdb.com/games/xcom-enemy-unknown","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co29i2.jpg","s":"XCOM: Enemy Unknown is a turn-based tactics game with a strategic management layer, and a reimagining of the 1994 strategy title UFO: Enemy Unknown. Players lead a squad of soldiers through turn-based combat missions against alien forces, using cover, positioning, and class-based abilities, where fallen soldiers can be lost permanently. Between missions, players oversee a central base: researching recovered alien technology, building facilities, managing funds, and deciding which global threats to respond to as they try to keep member nations from abandoning the project."},{"t":"Xenoblade Chronicles","p":["Wii"],"d":"MonolithSoft","u":"Nintendo","g":"Action RPG","r":"April 6","l":"https://en.wikipedia.org/wiki/Xenoblade_Chronicles_(video_game)"},{"t":"Yakuza 5","p":["PlayStation 3"],"d":"Ryu Ga Gotoku Studio","u":"Sega","g":"Action-adventure, beat 'em up","r":"December 5, 2012","l":"https://en.wikipedia.org/wiki/Yakuza_5","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1n1g.jpg","s":"Yakuza 5 is an open-world action-adventure game and the fifth main title in the Yakuza series developed by Sega. For the first time in the series, it features five settings across Japan along with five playable main characters. The game also features a brand new graphics engine, unlike previous games in the series that have been re-utilizing the same engine since Yakuza 3."},{"t":"Yakuza: Dead Souls","p":["PlayStation 3"],"r":"March 13"},{"t":"Yesterday","p":["Windows","iOS","Android"],"d":"Pendulo Studios","u":"Focus Home Interactive, FX Interactive","g":"Adventure","r":"March 22, 2012","l":"https://en.wikipedia.org/wiki/Yesterday_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2rx5.jpg","s":"After captivating players from all around the world with the mythic Runaway trilogy, Pendulo Studios presents a new adventure gaming masterpiece! This thrilling mystery, presenting a unique, dark and somber style, will not leave you indifferent! With an incredible story, superb environments, perplexing and shady characters, Yesterday throws you into an unforgettable adventure from which you will not emerge unscathed."},{"t":"Your Shape: Fitness Evolved 2013","p":["Wii U"],"r":"November 18"},{"t":"Ys Origin","p":["Windows"],"r":"May 29","l":"https://en.wikipedia.org/wiki/Ys_Origin"},{"t":"Ys: The Oath in Felghana","p":["Windows"],"r":"March 19"},{"t":"Yumby Toss","p":["iOS","Android"],"r":"September 25"},{"t":"Zack Zero","p":["PlayStation 3"],"r":"January 17","l":"https://en.wikipedia.org/wiki/Zack_Zero"},{"t":"Zafehouse: Diaries","p":["Windows"],"d":"Screwfly Studios","u":"Screwfly Studios","g":"Strategy","r":"September 28, 2012","l":"https://en.wikipedia.org/wiki/Zafehouse:_Diaries","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co81fx.jpg","s":"Safehouse: Diaries is a fresh take on the zombie / survival horror genre. If you're sick of mindless shooters or generic-looking top down affairs that just don't get what the zombie genre is about, this is the game for you.About Screwfly Studios\nWe're a two-man developer based in Australia, dedicated to creating deep, innovative strategy games for PC. Zafehouse: Diaries is Screwfly's debut title and the spiritual successor to the highly-regarded Zafehouse."},{"t":"Zen Pinball 2","p":["PlayStation Network"],"r":"September 4","l":"https://en.wikipedia.org/wiki/Zen_Pinball_2"},{"t":"Zen Pinball 3D","p":["Nintendo 3DS"],"r":"January 12","l":"https://en.wikipedia.org/wiki/Zen_Pinball"},{"t":"Zero Escape: Virtue's Last Reward","p":["Nintendo 3DS","PlayStation Vita"],"g":"Point-and-click, Puzzle, Adventure, Visual Novel","r":"October 23","l":"https://www.igdb.com/games/zero-escape-virtue-s-last-reward","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co260l.jpg","s":"The second game in the Zero Escape series.\nZero Escape: Virtue's Last Reward is a mystery/thriller visual novel. It is story focused with multiple endings that use player choices and puzzle rooms to progress.\n\nAdditions to the game include an 'auto-advance text' mode, so players can listen to the voice acting without clicking through dialog, a memo function that allows players to note anything they feel is useful, and a flow chart that shows how alternate choices unfold. The in-game calculator has been removed."},{"t":"ZiGGURAT","p":["iOS"],"r":"February 17","l":"https://en.wikipedia.org/wiki/Ziggurat_(2012_video_game)"},{"t":"Zineth","p":["Windows","macOS"],"d":"Arcane Kids","u":"Arcane Kids","g":"Strategy","l":"https://en.wikipedia.org/wiki/Zineth","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6ilm.jpg","s":"A movement based adventure game released in 2012 by Arcane Kids. Features unique integration of Twitter through an in-game smartphone."},{"t":"Zombie Tsunami","p":["Android","iOS","Windows Phone"],"d":"Mobigame","u":"Mobigame","g":"Side scrolling endless runner","r":"May 31, 2012","l":"https://en.wikipedia.org/wiki/Zombie_Tsunami","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4k5i.jpg","s":"The zombies are revolting ! Attack the city with a horde of zombies, change pedestrians into zombies and create the largest horde.\nEat your friends, and challenge them to a crazy race by destroying everything in your path.\n\nZombie Tsunami has proudly exceeded 200 million players around the world."},{"t":"Zombies, Run!","p":["iOS"],"r":"February 27","l":"https://en.wikipedia.org/wiki/Zombies,_Run!"},{"t":"ZombiU","p":["Wii U"],"g":"Shooter, Adventure","r":"November 18","l":"https://en.wikipedia.org/wiki/ZombiU","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22ag.jpg","s":"Developed by Ubisoft Montpellier, the studio behind critically acclaimed titles like From Dust, Beyond Good & Evil and, Ghost Recon Advanced Warfighter, ZombiU puts players in the middle of London circa 2012, where an outbreak has infected the population, destroying their humanity and turning them into mindless monsters preying on the flesh of the few remaining survivors. This fear-fueled first-person shooter invites takes all the horror, chaos and tension found in the best of the horror genre and adds original interactive elements, including a unique death mechanic that puts players in the body of a different survivor each time they die, allowing them to track and take down their old, infected characters, recover their equipment and see if they can stay alive just a little bit longer this time."},{"t":"Zone of the Enders HD Collection","p":["PlayStation 3","Xbox 360"],"r":"October 30","l":"https://en.wikipedia.org/wiki/Zone_of_the_Enders_(video_game)"},{"t":"Zuma's Revenge!","p":["Nintendo DS","Xbox 360"],"r":"February 21","l":"https://en.wikipedia.org/wiki/Zuma%27s_Revenge!"},{"t":"Zumba Fitness Core","p":["Wii","Xbox 360"],"d":"Zoë Mode","u":"Majesco","g":"Fitness game","r":"October 16, 2012","l":"https://en.wikipedia.org/wiki/Zumba_Fitness_Core","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22ub.jpg","s":"Rock your core and dance your way to toned, sexy abs with Zumba Fitness Core, featuring 40 new songs and routines, more than 30 international dance styles from around the world and hot new choreography that's designed to sculpt stronger abs through an exhilarating full body workout. Lose yourself in the music as celebrity Zumba instructors guide you through choreography set to contagious new Zumba fitness originals and a broader mix of smash hits from hot artists including Enrique Iglesias and Don Omar (full soundtrack to be announced at a future date)."},{"t":"Zynga Bingo","p":["Facebook"],"d":"Zynga","g":"Social network game","l":"https://en.wikipedia.org/wiki/Zynga_Bingo"},{"t":"Zynga Slingo","p":["Facebook"],"d":"Zynga","g":"social, casino, slots, bingo game","l":"https://en.wikipedia.org/wiki/Zynga_Slingo"},{"t":"Ōkami HD","p":["PlayStation 3","PlayStation Network"],"u":"Capcom","g":"Role-playing (RPG), Adventure","r":"October 30, 2012","l":"https://en.wikipedia.org/wiki/%C5%8Ckami#High-definition_remaster","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22s8.jpg","s":"Experience the critically acclaimed masterpiece with its renowned Sumi-e ink art style in breathtaking high resolution. Take on the role of Amaterasu, the Japanese sun goddess who inhabits the form of a legendary white wolf, on a quest to defeat Orochi, an eight-headed demon and tyrannical monster responsible for turning the world of Nippon into a ruined wasteland."}];
